  @override
  String get synthetic_cannabinoidsInfoBox =>
      '합성 칸나비노이드(“Spice”, “K2”)는 대마초보다 훨씬 강력하고 예측하기 어려울 수 있습니다. 금단은 더 심할 수 있으며 발작, 초조, 빠른 심박수 등이 보고되었습니다. 급성 중독은 정신병적 증상을 일으킬 수도 있습니다. 심한 증상이 나타나면 즉시 의료 도움을 받으세요.';

