  @override
  String get steroidsInfoBox =>
      '동화작용 스테로이드를 중단하면 신체가 호르몬 생산을 다시 시작할 때까지 테스토스테론 수치가 낮게 유지됩니다. 일반적으로 수개월에 걸쳐, 때로는 더 길어질 수도 있습니다. 이 단계에서는 우울증과 낮은 성욕이 흔히 나타납니다. 심한 우울증이나 자살 충동은 긴급한 치료가 필요합니다.';

