      '동화작용 스테로이드는 신체의 테스토스테론을 억제합니다. 중단하면 호르몬 결핍이 발생하여 피로, 기분 저하, 성욕 저하가 발생할 수 있습니다. 의학적 지도가 권장됩니다.';

  @override
