  @override
  String get steroidsMilestone14Description =>
      '첫 주는 낮은 에너지, 기분, 성욕 등 호르몬 저하가 가장 힘든 시기입니다. 이는 많은 사람들이 이를 피하기 위해 재발하는 단계입니다. 지원이 도움이 됩니다.';

  @override
