  @override
  String get steroidsMilestone30Description =>
      '한 달이 지나면 뇌-고환 호르몬 시스템이 다시 시작됩니다. 테스토스테론과 테스토스테론 자체를 유도하는 호르몬은 상승하기 시작하지만 낮은 기분, 성욕 또는 에너지는 여전히 남아 있을 수 있습니다.';

  @override
