  @override
  String get nitrousOxideMilestone1Title => '첫 24시간 – 가스 배출 완료';

  @override
  String get nitrousOxideMilestone1Description =>
      '가스 자체는 몇 분 안에 몸에서 빠져나가지만 회복에는 더 오래 걸립니다. 어지럼증과 두통이 가라앉고, 뇌는 빠른 도파민 자극 없이 적응하기 시작합니다. B12 회복도 이제 시작됩니다.';

  @override
  String get nitrousOxideMilestone3Title => '3일차 – 신체적 금단 없음';

  @override
  String get nitrousOxideMilestone3Description =>
      '좋은 소식은 아산화질소가 신체적 금단을 일으키지 않는다는 점입니다. 느껴지는 충동은 습관과 연상에서 오는 심리적 갈망이지, 몸이 물질을 요구하는 반응이 아닙니다. 그래서 충분히 관리할 수 있습니다.';

  @override
  String get nitrousOxideMilestone7Title => '1주 – B12 수치 회복 시작';

  @override
  String get nitrousOxideMilestone7Description =>
      '새로운 아산화질소 노출 없이 일주일이 지났습니다. 보충 치료를 시작했다면 B12 수치가 이미 오르고 있을 수 있습니다. 에너지, 기분, 집중력은 B12와 연결되어 있어 조금씩 나아지는 변화를 느낄 수 있습니다.';

  @override
  String get nitrousOxideMilestone14Title => '2주 – 신경 회복 진행 중';

  @override
  String get nitrousOxideMilestone14Description =>
      'B12는 신경섬유를 보호하는 피복에 꼭 필요합니다. 2주가 지난 지금 이 회복 과정이 진행되고 있습니다. 저림이나 무감각이 있었다면 완화될 수 있으며, 신경계는 계속 회복하고 있습니다.';

  @override
  String get nitrousOxideMilestone30Title => '1개월 – 에너지 회복';

  @override
  String get nitrousOxideMilestone30Description =>
      'B12는 적혈구 생성과 세포에 산소를 전달하는 데 중요한 역할을 합니다. 한 달 동안 회복하고 필요한 경우 보충 치료를 받았다면 에너지, 사고의 선명함, 기분 안정에서 의미 있는 개선을 느낄 수 있습니다.';

  @override
  String get nitrousOxideMilestone90Title => '3개월 – 신경 회복';

  @override
  String get nitrousOxideMilestone90Description =>
      '새로운 B12 비활성화 없이 3개월이 지났다는 것은 신경이 회복할 시간을 3개월 확보했다는 뜻입니다. 신경계는 회복력이 있으며, 치료를 일찍 시작한 사람에게서는 저림, 쇠약, 머리가 흐린 느낌이 크게 좋아지는 경우가 흔히 보고됩니다.';

  @override
  String get nitrousOxideMilestone365Title => '1년 – 장기적인 보호';

  @override
  String get nitrousOxideMilestone365Description =>
      '아산화질소 없이 꼬박 1년을 보냈습니다. B12 저장량은 회복됐고, 신경계는 1년 동안 회복할 시간을 가졌으며, 높아진 호모시스테인과 관련된 심혈관 위험도 해소됐습니다. 몸은 다시 본래의 화학 작용으로 움직이고 있습니다.';

