  @override
  String get cocaineMilestone3Title => '3일: 가장 힘든 시기';

  @override
  String get cocaineMilestone3Description =>
      '금단 증상은 이 무렵 가장 심해지는 경우가 많습니다. 강한 사용 욕구, 과민함, 불안, 탈진이 나타날 수 있습니다. 이는 일시적이며 뇌는 다시 균형을 찾는 중입니다.';

  @override
  String get cocaineMilestone7Title => '1주: 신체 회복 시작';

  @override
  String get cocaineMilestone7Description =>
      '가장 심한 신체 증상이 가라앉기 시작합니다. 심박수와 혈압이 안정되고 있습니다. 심리적인 사용 욕구는 계속될 수 있지만 몸은 회복하고 있습니다.';

  @override
  String get cocaineMilestone14Title => '2주: 안정감 회복';

  @override
  String get cocaineMilestone14Description =>
      '많은 사람이 정서적으로 더 안정되기 시작합니다. 에너지 수준이 좋아지고 급성 금단 증상이 완화됩니다. 심혈관 건강도 계속 개선됩니다.';

  @override
  String get cocaineMilestone60Title => '2개월: 수면과 기분 개선';

  @override
  String get cocaineMilestone60Description =>
      '뇌의 화학적 균형이 계속 정상화되면서 수면의 질이 눈에 띄게 좋아집니다. 더 개운하게 쉬고 하루 동안 더 안정된 기분을 느낄 수 있습니다.';

  @override
  String get cocaineMilestone90Title => '3개월: 뇌 회복';

  @override
  String get cocaineMilestone90Description =>
      '도파민 시스템이 회복되고 있습니다. 집중력, 의사결정, 감정 조절이 뚜렷하게 좋아지고 생각도 더 선명해집니다.';

  @override
  String get cocaineMilestone180Title => '6개월: 더 선명한 사고';

  @override
  String get cocaineMilestone180Description =>
      '뇌 영상에서는 계획과 자기 통제를 담당하는 뇌 앞부분의 회복이 관찰됩니다. 기억력, 충동 조절, 명확한 사고가 계속 강화됩니다.';

  @override
  String get cocaineMilestone365Title => '1년: 심혈관 건강';

  @override
  String get cocaineMilestone365Description =>
      '심장과 심혈관계가 크게 회복되었습니다. 혈압과 심박수가 정상화되었고 심장마비와 뇌졸중 위험도 크게 낮아졌습니다. 몸은 계속 회복하고 있습니다.';

  @override
  String get cocaineMilestone730Title => '2년 - 지속적인 회복';

  @override
  String get cocaineMilestone730Description =>
      '뇌 치유는 기억력, 집중력, 감정 조절의 지속적인 개선을 통해 계속됩니다. 신경 경로가 크게 재구성되어 더 건강한 패턴과 더 나은 전반적인 웰빙을 지원합니다.';

  @override
  String get cocaineMilestone1095Title => '3년: 더 단단한 기반';

  @override
  String get cocaineMilestone1095Description =>
      '코카인 없이 3년을 이어온 것은 꾸준한 진전입니다. 그동안 만든 일상, 관계, 대처 기술이 여러 해에 걸쳐 자리 잡으며 회복의 기반을 더 단단하게 만들었습니다.';

  @override
