  @override
  String get nicotinePouchesMilestone1Description =>
      '니코틴 금단은 마지막 파우치 후 4~24시간 안에 시작될 수 있습니다. 파우치 없이 보낸 첫날은 분명한 생물학적 이정표입니다. 몸은 이미 반복적인 니코틴 공급 없이 지내는 상태에 적응하고 있습니다.';

