  @override
  String get nicotinePouchesReferenceDay1095 =>
      '3년: 자유가 이어진다\n\n출처: CDC — 니코틴 파우치\n\nCDC는 니코틴 파우치의 단기 및 장기 건강 영향을 이해하려면 더 많은 연구가 필요하다고 밝힙니다. 중단 후 정확히 3년에 특별한 의학적 변화가 생긴다고 제시하지는 않습니다.\n\n파우치 없이 보낸 3년은 그 자체로 축하할 가치가 있습니다. 파우치 니코틴에서 벗어난 상태를 3년 동안 꾸준히 이어 왔습니다.';

