      '통제할 수 없는 성적 행동에 대한 무작위 CBT 연구에서는 3개월 및 6개월 추적 조사에서 증상, 성적 강박, 웰빙의 개선이 안정적으로 유지되는 것으로 나타났습니다. 장기간 관리가 유지될 수 있습니다.';

  @override
  String get pornographyMilestone365Title => '1년: 지속 가능한 변화';

  @override
  String get pornographyMilestone365Description =>
      '수용 기반 치료 연구의 1년 후속 데이터에 따르면 참가자들은 치료 전 성욕과다 수준으로 돌아가지 않은 것으로 나타났습니다. 1년간의 지속적인 변화는 마법의 두뇌 재설정 날짜가 아니라 내구성 있는 패턴의 신뢰할 수 있는 증거입니다.';

  @override
  String get pornographyMilestone730Title => '2년: 안정된 통제';

  @override
  String get pornographyMilestone730Description =>
      '2년 동안 변화를 유지한 것은 큰 행동적 성과입니다. CSBD와 문제적 음란물 이용에 관한 근거는 모두에게 적용되는 2년의 뇌 재설정이 아니라 통제력, 고통, 기능, 맥락을 중요하게 봅니다. 좋은 선택을 쉽게 만드는 습관을 계속 지키세요.';

  @override
  String get pornographyMilestone1095Title => '3년: 단단해진 변화';

  @override
  String get pornographyMilestone1095Description =>
      '3년은 변화가 다양한 기분, 일상, 삶의 사건을 지나서도 유지됐음을 보여줍니다. 3년에 생물학적으로 끝난다는 근거는 없으며, 지속적인 통제력과 더 나은 기능 자체가 중요한 결과입니다.';

  @override
  String get pornographyMilestone1460Title => '4년: 오래가는 변화';

  @override
  String get pornographyMilestone1460Description =>
      '4년은 장기 유지의 단계입니다. 가장 좋은 근거는 CSBD와 문제적 음란물 이용을 복잡하고 개인차가 큰 문제로 보므로, 통제력, 고통, 관계, 시간 사용, 이전 패턴이 삶을 방해하는지를 계속 살피는 것이 중요합니다.';

  @override
  String get pornographyMilestone1825Title => '5년간의 통제';

  @override
  String get pornographyMilestone1825Description =>
      '5년은 장기적으로 변화를 유지해 온 기간입니다. CSBD는 지속적인 통제력 상실과 그로 인한 고통 또는 기능 저하를 중심으로 임상적으로 정의되므로, 수년에 걸쳐 통제력과 좋은 기능을 유지하는 것 자체가 의미 있는 결과입니다.';

  @override
  String get customMilestone1Title => '첫 24시간 완료';

  @override
  String get customMilestone1Description =>
      '끊기로 한 습관 없이 꼬박 하루를 보냈습니다. 일부 물질은 중단한 뒤 첫 며칠 동안 금단으로 수면이 흐트러질 수 있고, 이런 수면 변화가 회복기까지 이어질 수 있습니다. 수면을 기록하면 이런 변화를 더 쉽게 알아차릴 수 있습니다.';

  @override
  String get customMilestone3Title => '금단 증상이 정점에 이르는 시기';

  @override
  String get customMilestone3Description =>
      '힘든 시기를 정면으로 지나고 있습니다. 많은 물질에서 불안, 기분 변화, 신체적 불편감 같은 금단 증상은 대개 3일 전후에 가장 심해집니다. 가장 어려운 구간을 통과하고 있다는 뜻입니다.';

  @override
  String get customMilestone7Title => '급성 금단 단계가 잦아드는 시기';

