  @override
  String get customMilestone90Title => '회복 3개월';

  @override
  String get customMilestone90Description =>
      '꾸준함이 결실을 맺고 있습니다. 회복 3개월은 큰 성취입니다. 급성기 이후의 금단 증상은 대개 서서히 줄어들고, 많은 사람이 다시 자기다운 느낌을 되찾기 시작합니다.';

  @override
  String get customMilestone180Title => '회복 6개월';

