  @override
  String get customMilestone365Title => '회복 1년';

  @override
  String get customMilestone365Description =>
      '놀라운 성과입니다. 회복 1년은 삶의 큰 이정표입니다. 많은 사람이 이 무렵 신체 건강, 관계, 전반적인 삶의 질에서 뚜렷한 개선을 경험합니다.';

