  @override
  String get ssriMilestone3Description =>
      '금단 증상은 대개 2~4일째에 가장 심해집니다. SSRI는 세로토닌 재흡수 방식에 영향을 주므로 중단 후 뇌가 적응할 시간이 필요합니다. 독감 같은 증상, 어지럼, 불면, 메스꺼움, 전기충격 같은 감각인 ‘브레인 잽’이 나타날 수 있습니다. 파록세틴은 금단 증상이 더 강한 편이고, 플루옥세틴은 체내에 훨씬 오래 남아 보통 더 완만합니다.';

