  String get ssriMilestone30Description =>
      '한 달은 중요한 이정표입니다. 수면의 질이 향상되고, 에너지 수준이 안정되고, 많은 사람들이 자신의 기분이 새로운 균형을 찾기 시작하는 것을 알아차립니다. 뇌는 자연적인 세로토닌 조절을 적극적으로 회복하고 있습니다.';

