  @override
  String get snriMilestone3Title => '3일차: 극심한 중단 증후군 최고점';

  @override
  String get snriMilestone3Description =>
      'SNRI, 특히 벤라팍신(Effexor)은 가장 심각한 항우울제 중단 증후군과 관련이 있습니다. 벤라팍신의 매우 짧은 반감기(5시간)는 대부분의 SSRI보다 증상이 더 심할 수 있음을 의미합니다. FINISH 증상(독감 같은 느낌, 불면증, 메스꺼움, 불균형, 감각 장애, 각성 과다)은 세로토닌과 노르에피네프린 시스템에 동시에 영향을 미칩니다.';

  @override
  String get snriMilestone7Title => '일주일: 두 가지 뇌 화학 시스템 조정';

  @override
  String get snriMilestone7Description =>
      'SNRI는 세로토닌과 노르에피네프린 재흡수 모두에 영향을 미칩니다. 두 시스템 모두 동시에 조정 중입니다. 가장 극심한 신체 증상이 가라앉기 시작했지만, 이중 메커니즘으로 인해 SSRI만 사용할 때보다 조정이 더 복잡하게 느껴질 수 있습니다.';

  @override
  String get snriMilestone14Title => '2주: 신체적 증상이 사라짐';

  @override
  String get snriMilestone14Description =>
      '급성 신체 중단 증상의 대부분이 크게 줄었습니다. 브레인 잽, 메스꺼움, 어지럼이 서서히 가라앉습니다. 노르에피네프린 체계가 다시 적응하면서 불안이나 혈압 변동이 조금 남을 수 있지만, 보통 다음 몇 주에 걸쳐 완화됩니다.';

  @override
  String get snriMilestone30Title => '한 달: 노르에피네프린 시스템 안정화';

  @override
  String get snriMilestone30Description =>
      '한 달은 중요한 이정표입니다. 세로토닌과 노르에피네프린 시스템 모두 적극적으로 재균형을 이루고 있습니다. 수면의 질과 에너지 수준이 안정되고 있습니다. 많은 사람들은 감정 둔화에 대한 약물의 효과가 해결되기 시작하면서 감정 범위가 개선되었음을 알아차립니다.';

  @override
  String get snriMilestone90Title => '3개월: 일반적인 금단 기간을 지남';

  @override
  String get snriMilestone90Description =>
      'SNRI 금단 증상은 보통 중단 후 며칠 안에 시작해 몇 주간 지속됩니다. 90일째에는 그 일반적인 증상 기간을 훨씬 지난 상태이며, 이는 구체적인 회복 이정표입니다.';

  @override
  String get snriMilestone180Title => '6개월: 신경학적 회복';

  @override
  String get snriMilestone180Description =>
      '6개월이면 세로토닌과 노르에피네프린 시스템 모두가 실질적으로 재조정됩니다. SNRI가 노르에피네프린을 통해 영향을 미치는 HPA 축은 정상화되고 있습니다. 많은 사람들이 이 시점에서 일상적인 스트레스 요인에 대한 회복력이 눈에 띄게 향상되었다고 보고합니다.';

  @override
  String get snriMilestone365Title => '1년: 회복 달성';

  @override
  String get snriMilestone365Description =>
      '1년은 이중 세로토닌-노르에피네프린 회복의 완전한 주기를 나타냅니다. 연구에 따르면 의학적 감독과 심리적 지원 하에 SNRI를 성공적으로 중단한 사람들은 1년 후에도 좋은 결과를 유지하는 것으로 나타났습니다.';

  @override
  String get snriMilestone730Title => '2년: 단단한 발걸음';

  @override
  String get snriMilestone730Description =>
      'SNRI 감량을 마친 뒤 2년은 충분히 기념할 만한 순간입니다. 금단 경험은 사람마다 다르므로 이 기념일은 보편적인 생물학적 회복 시한이 아니라 꾸준한 진전을 뜻합니다.';

  @override
  String get snriReferenceDay730 =>
      'SNRI 중단 후 2년: 진전의 이정표\n\n출처: Royal College of Psychiatrists — 항우울제 중단\n\n항우울제는 보통 갑자기 끊지 않고 개인에 맞춰 감량해야 합니다. 둘록세틴이나 벤라팍신은 수개월 이상 더 천천히 줄여야 할 수 있습니다.\n\n지침은 2년을 생물학적 회복 기준으로 정하지 않습니다. 이 기념일은 꾸준한 진전을 축하합니다.';

  @override
  String get snriMilestone1095Title => '3년: 이어진 진전';

  @override
  String get snriMilestone1095Description =>
      '감량을 마친 뒤 3년은 큰 시간의 축적입니다. 여기까지 이어 온 습관, 지원, 선택을 기념하세요. 의학은 이 날짜를 특별한 회복 기준으로 정하지 않습니다.';

  @override
  String get snriReferenceDay1095 =>
      'SNRI 중단 후 3년: 지속되는 진전\n\n출처: Royal College of Psychiatrists — 항우울제 중단\n\n금단 경험은 사람마다 다르며 감량 속도는 개인 상태, 치료 기간, 과거 증상, 약물에 맞춰야 합니다.\n\n3년을 보편적인 SNRI 회복 기한으로 정한 임상 지침은 없습니다. 이 이정표는 3년간의 진전을 인정합니다.';

  @override
  String get snriMilestone1460Title => '4년: 시간 속의 힘';

  @override
  String get snriMilestone1460Description =>
      '4년은 시간에 걸쳐 쌓아 온 지속적인 진전을 보여 줍니다. 경험은 개인마다 다르며, 이 이정표는 고정된 신경학적 시간표를 주장하지 않고 유지해 온 성과를 기립니다.';

  @override
  String get snriReferenceDay1460 =>
      'SNRI 중단 후 4년: 장기적인 진전\n\n출처: Royal College of Psychiatrists — 항우울제 중단\n\n금단에는 개인차가 있으며 점진적이고 개인화된 감량이 권고됩니다. 둘록세틴과 벤라팍신은 금단 증상 위험이 더 높은 약입니다.\n\n이 근거가 4년이라는 신경학적 기준을 만들지는 않습니다. 오늘은 꾸준한 진전을 기념합니다.';

  @override
  String get snriMilestone1825Title => '5년: 5년의 성취';

  @override
  String get snriMilestone1825Description =>
      '5년은 큰 개인적 이정표입니다. SNRI 중단 후의 장기적인 진전을 기념하면서, 금단과 회복이 하나의 보편적 일정대로 진행되지 않는다는 점도 인정합니다.';

  @override
  String get snriReferenceDay1825 =>
      'SNRI 중단 후 5년: 5년 이정표\n\n출처: Royal College of Psychiatrists — 항우울제 중단\n\n지침은 모두에게 하나의 회복 일정을 정하는 대신 안전하고 개인화된 감량과 증상 대응에 초점을 둡니다.\n\n근거 기반의 5년 SNRI 회복 기준은 없습니다. 그래도 5년은 의미 있는 개인적 기념일입니다.';

  @override
  String get settingsShowSnriTracking => 'SNRI 추적 표시';

  @override
