  @override
  String get tcaPageTitle => 'TCA 회수';

  @override
  String get tcaHeaderStarted => '귀하의 회복 여정';

  @override
  String get tcaHeaderNotStarted => 'TCA 축소의 이점';

  @override
  String get tcaSubtitleStarted => '진행 상황을 추적하고 각 목표를 축하하세요';

  @override
  String get tcaSubtitleNotStarted => '테이퍼오프하면 어떤 일이 발생하는지 확인하세요.';

  @override
  String get tcaMilestone3Title => '3일차: 콜린성 반동';

  @override
  String get tcaMilestone3Description =>
      'TCA 중단은 실제 금단 증상을 유발할 수 있으며, 콜린성 과활성은 제안된 기전 중 하나입니다. 메스꺼움, 설사, 복통, 불면, 불안, 초조, 두통은 특히 갑작스러운 중단이나 빠른 감량 뒤 일찍 나타날 수 있습니다. 3일째는 하나의 이정표이며 증상의 시기와 강도는 사람마다 다릅니다.';

  @override
  String get tcaMilestone7Title => '1주: 첫 구간을 지나며';

  @override
  String get tcaMilestone7Description =>
      '항우울제 금단은 보통 며칠 안에 시작해 몇 주 동안 이어집니다. 1주가 지나도 메스꺼움, 발한, 수면 문제, 두근거림, 어지럼증이 남아 있을 수 있습니다. 7일은 분명한 진전이며, 회복은 사람마다 다른 속도로 계속될 수 있습니다.';

  @override
  String get tcaMilestone14Title => '2주: 급성 금단이 보통 가라앉기 시작합니다';

  @override
  String get tcaMilestone14Description =>
      '메스꺼움, 불면, 균형 장애, 감각 이상, 과각성 같은 전형적인 항우울제 중단 증상은 보통 1~2주 지속됩니다. 14일째에는 많은 사람이 이 급성 구간의 끝에 가까워집니다.';

  @override
  String get tcaMilestone30Title => '한 달: 급성 중단 증상은 보통 가라앉음';

  @override
  String get tcaMilestone30Description =>
      '전형적인 항우울제 중단 증상은 보통 1~2주 지속됩니다. 30일이면 대부분 그 급성 시기를 지나며, 독감 같은 증상, 메스꺼움, 균형 이상, 불면, 감각 이상, 과각성은 대개 크게 줄거나 사라집니다.';

  @override
  String get tcaMilestone90Title => '3개월: 급성 중단 시기는 한참 지났습니다';

  @override
  String get tcaMilestone90Description =>
      '전형적인 항우울제 중단 증상은 보통 1~2주 지속됩니다. 90일은 그 일반적인 급성 시기의 상한에서 10주 이상 지난 시점이며, 독감 같은 증상, 메스꺼움, 균형 이상, 불면, 감각 이상, 과각성은 대개 오래전에 크게 줄거나 사라졌습니다.';

  @override
  String get tcaMilestone180Title => '6개월: 대부분 재발 없이 유지';

  @override
  String get tcaMilestone180Description =>
      '주요우울장애 치료 후 항우울제를 중단한 사람들을 대상으로 한 35개 시험 메타분석에서 6개월 통합 재발률은 34.8%였고, 약 65%는 재발 없이 지냈습니다. 큰 안정 구간입니다.';

  @override
  String get tcaMilestone365Title => '1년: 대부분 재발 없이 유지';

  @override
  String get tcaMilestone365Description =>
      '주요우울장애 치료 후 항우울제를 중단한 사람들을 대상으로 한 35개 시험 메타분석에서 12개월 통합 재발률은 45.12%였고, 약 55%는 1년 내내 재발 없이 지냈습니다. 장기 안정성의 큰 이정표입니다.';

  @override
  String get tcaMilestone730Title => '2년: 단단한 기반';

  @override
  String get tcaMilestone730Description =>
      'TCA 감량을 마친 뒤 2년은 큰 이정표입니다. 중단 후 경험은 사람마다 다르므로, 이 시점은 모두에게 같은 생물학적 종착점을 주장하기보다 꾸준히 이어 온 진전을 기념합니다.';

  @override
  String get tcaReferenceDay730 =>
      'TCA 중단 2년: 지속된 진전\n\n출처: NICE NG222 — Depression in adults: treatment and management\n\nNICE는 TCA를 중단 증상이 생길 수 있는 항우울제에 명확히 포함합니다. 경험은 사람마다 다르며, 용량은 단계적으로 줄이고 개인의 반응에 맞춰 속도를 조절하도록 권고합니다.\n\n지침은 2년을 생물학적 회복의 경계로 정하지 않습니다. 이 기념일은 보편적인 종착점을 만들지 않고 2년 동안 이어 온 진전을 기념합니다.';

  @override
  String get tcaMilestone1095Title => '3년: 이어지는 진전';

  @override
  String get tcaMilestone1095Description =>
      '3년은 오랫동안 이어 온 진전을 보여 주는 기간입니다. 임상 지침은 이 날짜를 TCA 회복의 특별한 종착점으로 정하지 않습니다. 그동안 지켜 온 안정, 습관, 선택 자체가 중요한 성과입니다.';

  @override
  String get tcaReferenceDay1095 =>
      'TCA 중단 3년: 이어지는 진전\n\n출처: NICE NG222 — Depression in adults: treatment and management\n\nNICE는 TCA를 중단 증상이 생길 수 있는 항우울제에 명확히 포함합니다. 경험은 사람마다 다르며, 용량은 단계적으로 줄이고 개인의 반응에 맞춰 속도를 조절하도록 권고합니다.\n\n지침은 3년을 보편적인 회복 기한으로 제시하지 않습니다. 이 이정표는 3년 동안 유지한 안정과 진전을 인정합니다.';

  @override
  String get tcaMilestone1460Title => '4년: 오래가는 진전';

  @override
  String get tcaMilestone1460Description =>
      '4년은 시간에 걸쳐 쌓인 지속적인 진전을 보여 줍니다. TCA 중단 뒤의 경험은 개인마다 다르며, 이 이정표는 고정된 신경학적 시간표를 만들지 않고 유지해 온 변화를 기립니다.';

  @override
  String get tcaReferenceDay1460 =>
      'TCA 중단 4년: 장기적인 진전\n\n출처: NICE NG222 — Depression in adults: treatment and management\n\nNICE는 TCA를 중단 증상이 생길 수 있는 항우울제에 명확히 포함합니다. 경험은 사람마다 다르며, 용량은 단계적으로 줄이고 개인의 반응에 맞춰 속도를 조절하도록 권고합니다.\n\n지침에는 4년이라는 생물학적 경계가 없습니다. 그래도 4년은 장기적인 진전을 돌아보는 의미 있는 기준점입니다.';

  @override
  String get tcaMilestone1825Title => '5년: 지속된 진전';

  @override
  String get tcaMilestone1825Description =>
      '5년은 큰 개인적 기념일입니다. TCA 중단 뒤 지속된 변화를 보여 주면서, 중단과 회복이 모두에게 하나의 일정대로 진행되는 것은 아니라는 점도 존중합니다.';

  @override
  String get tcaReferenceDay1825 =>
      'TCA 중단 5년: 큰 기념일\n\n출처: NICE NG222 — Depression in adults: treatment and management\n\nNICE는 TCA를 중단 증상이 생길 수 있는 항우울제에 명확히 포함합니다. 경험은 사람마다 다르며, 용량은 단계적으로 줄이고 개인의 반응에 맞춰 속도를 조절하도록 권고합니다.\n\n근거는 5년을 TCA 회복의 경계로 정하지 않습니다. 그래도 5년은 큰 개인적 기념일이자 지속된 변화를 보여 주는 강한 표지입니다.';

