  @override
  String get adderallReferenceDay1 =>
      '암페타민 금단: 초기에 일어나는 일\n\n출처: MedlinePlus (U.S. National Library of Medicine)\n\n암페타민이란?\n암페타민은 불법 약물(예: 길거리에서 유통되는 스피드)과 ADHD 및 기면증 치료에 쓰이는 처방약(예: Adderall, Vyvanse)을 모두 포함하는 각성제입니다. 도파민과 노르에피네프린을 크게 높여 강한 집중, 에너지, 도취감을 유발할 수 있습니다. 규칙적으로 많은 양을 사용하면 뇌가 이런 반복적인 변화에 적응하므로, 중단했을 때 기분, 에너지, 동기가 일시적으로 낮아질 수 있습니다.\n\n흔한 금단 증상\nMedlinePlus는 암페타민을 중단할 때 흔히 나타날 수 있는 증상으로 다음을 제시합니다:\n• 약물에 대한 강한 갈망\n• 우울, 초조, 불안 사이를 오가는 기분 변화\n• 하루 종일 피곤함\n• 집중하기 어려움\n• 환각(실제로 없는 것을 보거나 듣는 것)\n• 두통, 몸살과 통증, 식욕 증가, 수면 문제 같은 신체 반응\n\n금단은 위험한가요?\nMedlinePlus는 암페타민 금단 자체를 의학적으로 위험한 상태라고 설명하지는 않지만, 증상이 심하면 입원형 치료 프로그램이 필요할 수 있고 우울증을 포함한 기분·정서 문제가 심각해 지원이 필요할 수 있다고 설명합니다.\n\n도움 받기\nMedlinePlus는 본인이나 아는 사람이 암페타민 의존으로 중단에 도움이 필요하다면 의료진에게 연락하라고 권합니다. 자해 생각이 들 경우 988이나 911 같은 위기 지원 자원을 이용하도록 안내합니다.';

  @override
  String get adderallReferenceDay3 =>
      '암페타민 금단 관리: 3일차\n\n출처: \"Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings,\" World Health Organization (2009), NCBI Bookshelf\n\n3일차의 위치\nWHO 지침은 각성제 금단 증상이 “마지막 각성제 사용 후 24시간 이내에 시작되어 3–5일 동안 지속된다”고 설명합니다. 3일차는 이 급성기의 한가운데로, 증상이 가라앉기 전 가장 힘든 시기 중 하나일 수 있습니다.\n\n증상\n암페타민계 각성제의 금단 증상으로 지침은 다음을 제시합니다:\n• 초조와 과민함\n• 우울\n• 수면 및 식욕 증가\n• 근육통\n사용량이 많은 사람은 편집증, 사고의 혼란, 환각 같은 정신병적 증상을 겪을 수도 있습니다.\n\n주로 심리적인 어려움\n알코올이나 오피오이드 금단과 달리 각성제 금단의 특징은 구토, 떨림, 발작이 아닙니다. 주된 어려움은 낮은 기분, 즐거움의 상실, 갈망 등 심리적인 증상입니다.\n\n관리 방법\nWHO 지침은 지지 치료를 권합니다:\n• 하루 최소 2–3리터의 물 마시기\n• 비타민 B군과 비타민 C가 포함된 종합비타민\n• 통증과 불안을 위한 증상 치료\n• 심한 초조에는 행동 전략을 먼저 사용하고, 필요할 때만 디아제팜 진정을 사용\n\n급성기 이후\n지침은 가장 힘든 금단이 며칠간 지속된 뒤, 약 1–2개월 동안 더 가벼운 회복 기간이 이어질 수 있다고 설명합니다.';

  @override
  String get adderallReferenceDay7 =>
      'Adderall 중단 1주: 가장 힘든 시기가 지나가는 중\n\n출처: Li & Shoptaw, \"Clinical Management of Psychostimulant Withdrawal: Review of the Evidence,\" Addiction (2023), PubMed Central\n\n급성기의 완화\n이 근거 검토는 정신자극제 금단을 여러 단계로 설명합니다. 급성기에는 증상이 “처음 2–3일 후 정점에 이르고”, “주요 불편감은 보통 4–7일 안에 해소”됩니다. 첫 주가 끝날 무렵에는 대부분의 사람이 가장 힘든 crash 구간을 지나며, 에너지와 식욕이 안정되고 수면도 조절되기 시작합니다.\n\n그다음에는\n검토에 따르면 남아 있는 증상 대부분은 이후 2–3주 동안 계속 줄어듭니다. 7일차에는 회복이 이미 진행 중입니다.\n\n7일차에도 남을 수 있는 증상\n심리적 증상은 신체적 crash보다 오래 지속되는 경우가 많습니다:\n• 낮은 동기와 즐거움의 감소\n• 집중의 어려움\n• 아직 평소보다 낮은 기분\n이는 도파민 체계가 다시 적응하는 과정으로, 회복의 정상적이고 일시적인 부분입니다.\n\n회복의 신호\n각성제 금단을 특별히 치료하도록 FDA가 승인한 약물은 없습니다. 따라서 지지 치료, 규칙적인 생활, 수면, 영양, 심리적 지원이 이 단계의 핵심입니다.';

  @override
  String get adderallReferenceDay14 =>
      'Adderall 중단 2주: 더 긴 회복 단계로\n\n출처: \"Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings,\" World Health Organization (2009), NCBI Bookshelf\n\n급성기를 지나\nWHO는 가장 심한 각성제 금단이 약 3–5일 지속되고, 이후 약 1–2개월의 더 가벼운 회복 기간이 이어질 수 있다고 설명합니다. 2주가 되면 초기 crash는 이미 상당히 지나간 시점입니다.\n\n더 긴 회복 단계에서 느낄 수 있는 것\n과도한 수면, 초조, 근육통은 대부분 가라앉습니다. 남는 증상은 보통 더 가볍습니다. 낮거나 변하는 기분, 낮은 동기, 뇌의 보상 체계가 다시 적응하면서 간헐적으로 나타나는 갈망 등이 있을 수 있습니다.\n\n수면과 식욕\n급성기에 늘었던 수면과 식욕은 정상화되기 시작합니다. 수면이 안정되면 기분, 집중력, 에너지도 따라 좋아지는 경향이 있습니다.\n\n재발 위험과 ADHD\n이 시기에도 재발 위험은 상대적으로 높을 수 있으며, 특히 약 없이 기저 ADHD 증상이 다시 나타날 경우 그렇습니다. WHO 지침은 심리적 지원과 재발 예방 기술을 강조합니다. ADHD 때문에 Adderall을 복용했다면 비각성제 전략이나 대안을 의사와 상의하기 좋은 시기입니다.';

  @override
  String get adderallReferenceDay30 =>
      'Adderall 중단 1개월: 대부분의 증상이 뒤로\n\n출처: Li & Shoptaw, \"Clinical Management of Psychostimulant Withdrawal: Review of the Evidence,\" Addiction (2023), PubMed Central\n\n1개월의 위치\n검토에 따르면 대부분의 금단 증상은 처음 2–3주 동안 줄어듭니다. 30일이 되면 대부분이 완화되고, 기분과 동기도 보통 첫 주보다 훨씬 나아집니다.\n\n후기 회복 단계\n1–6개월 동안 기억, 계획, 집중, 의사 결정은 계속 개선될 수 있습니다. 한 달이 되면 초기 crash는 끝났고 이런 회복이 이미 진행 중입니다.\n\n기분과 동기\n초기 crash에서 느끼던 깊은 무쾌감은 대부분 줄어들기 시작합니다. 첫 주에 아무런 즐거움을 주지 못했던 활동도 자연스러운 도파민 신호가 회복되면서 다시 보람 있게 느껴질 수 있습니다.\n\nADHD가 있는 경우\nAdderall이 ADHD 치료를 위해 처방됐다면 기저 증상이 더 눈에 띌 수 있습니다. 이 단계에서는 의료진과 비각성제 전략이나 대안을 검토하는 것이 중요합니다.';

  @override
  String get adderallReferenceDay60 =>
      'Adderall 중단 2개월: 더 긴 회복 단계의 끝 무렵\n\n출처: \"Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings,\" World Health Organization (2009), NCBI Bookshelf\n\n2개월의 위치\nWHO는 초기 crash 후 약 1–2개월 동안 이어지는 더 가벼운 회복 기간을 설명합니다. 60일은 그 범위의 끝 무렵이며 남아 있던 증상도 대부분 가라앉는 시기입니다.\n\n개선되는 부분\n각성제 금단에서 나타나는 초조, 우울한 기분, 수면 및 식욕 문제는 대부분의 사람에게 크게 줄어듭니다:\n• 평소 기분이 더 안정되고 초기 회복기의 변동이 줄어듭니다\n• 수면과 식욕이 정상화됩니다\n• 보상 체계가 음식, 운동, 사람과의 관계 같은 일상적인 즐거움에 더 자연스럽게 반응합니다\n\n회복의 신호\n복용량이 높거나 사용 기간이 길수록 회복에 더 오래 걸릴 수 있습니다. 계속 사용하지 않는 것은 이후 몇 달 동안 기분, 동기, 명료한 사고가 정상에 가까워지는 데 도움이 됩니다.\n\n신체 건강\n약물이 일상에서 사라지면서 심박수, 식욕, 체중에 대한 각성 효과가 줄고, 각성제 사용으로 인한 심혈관 부담도 완화됩니다.';

  @override
  String get adderallReferenceDay90 =>
      'Adderall 중단 3개월: 가장 힘든 시기는 지나고 회복은 계속\n\n출처: Li & Shoptaw, \"Clinical Management of Psychostimulant Withdrawal: Review of the Evidence,\" Addiction (2023), PubMed Central\n\n90일의 위치\n3개월에는 초기 증상이 이미 오래전에 지나갔고, 기억, 계획, 집중, 의사 결정, 보상 체계는 계속 개선될 수 있습니다.\n\n사고와 기억의 회복\n검토에 따르면 기억, 계획, 집중, 위험 관련 의사 결정은 수개월 동안 계속 나아질 수 있습니다. 90일에도 사용을 중단한 상태가 이어지면 집중력과 기억은 계속 좋은 방향으로 움직입니다.\n\n이 시기가 여전히 중요한 이유\n각성제 금단을 특별히 치료하도록 FDA가 승인한 약물은 없으므로 규칙적인 생활, 치료, 운동, 수면, 지원이 이 단계를 지나는 중요한 도구입니다. 지금 만든 습관이 이후의 회복을 뒷받침합니다.\n\n더 큰 그림\n3개월은 분명한 성취입니다. 가장 힘든 신체적·정서적 구간은 지나갔고, 계속 사용하지 않는다면 앞으로도 점진적인 개선을 기대할 수 있습니다.';

  @override
  String get adderallReferenceDay180 =>
      'Adderall 중단 6개월: 힘든 시기를 훨씬 넘어\n\n출처: \"Withdrawal Syndromes,\" StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\nStatPearls가 각성제에 대해 설명하는 것\n이 임상 참고 자료는 각성제 회복을 crash 이후 점진적인 개선이 이어지는 과정으로 설명합니다. 흔한 문제로 우울, 많은 수면, 식욕 증가, 낮은 기분, 느려진 움직임과 사고가 있습니다. 우울은 수주간 지속될 수 있고, 그 이후에도 더 가벼운 회복이 이어질 수 있습니다.\n\n6개월의 위치\n6개월이면 StatPearls가 설명하는 급성기와 수주간의 우울 단계 모두를 훨씬 지나온 시점입니다. 점진적인 회복에는 충분한 시간이 있었고, 대부분의 사람에게 평소의 기분, 수면, 식욕, 동기가 안정되는 방향으로 진행합니다.\n\n회복의 신호\nStatPearls는 초기 몇 주 이후에도 점진적인 회복이 이어진다고 설명합니다. 6개월에는 급성 crash와 수주간의 우울 단계가 멀리 지나가고, 안정된 기분, 수면, 식욕, 동기가 주된 양상이 됩니다.\n\nADHD와의 관계\nADHD 때문에 Adderall을 복용했다면 6개월은 현재 증상을 의사와 차분히 검토하고 운동, 수면, 규칙적인 생활, 치료, 대체 약물 같은 비각성제 접근이 자신의 필요를 충족하는지 살펴보기 좋은 시점입니다.';

  @override
  String get adderallReferenceDay365 =>
      'Adderall 중단 1년: 상당한 회복을 현실적으로 보기\n\n출처: Berman et al., \"Potential Adverse Effects of Amphetamine Treatment on Brain and Behavior: A Review,\" Molecular Psychiatry (2008), PubMed Central\n\n이 검토에 대하여\n이 검토는 고용량 또는 장기간의 암페타민 노출이 뇌에 미칠 수 있는 영향을 살펴보고, 사용을 중단한 기간에 측정 가능한 회복이 나타난다는 점을 기록합니다.\n\n회복에 대해 보고한 내용\n장기간 사용을 중단한 뒤 뇌 혈류와 도파민을 재활용하는 단백질에서 회복이 관찰됐습니다. 일부 뇌 영역은 다른 영역보다 더 빠르게 회복되지만 전체적인 방향은 분명합니다. 사용을 중단한 뒤 뇌는 회복됩니다.\n\n장기 회복\n검토는 장기간 사용을 중단한 뒤 뇌 혈류와 도파민 재활용에 측정 가능한 회복이 있음을 기록합니다. 1년이라는 기간 동안 이런 뇌 체계는 회복할 시간을 충분히 가졌습니다.\n\n1년이 의미하는 것\n대부분의 사람, 특히 처방 용량으로 Adderall을 복용한 사람에게 1년의 중단은 보상, 주의, 동기 체계가 일상에서 잘 기능하는 단계에 해당할 수 있습니다. 더 많이 또는 더 오래 사용했다면 더 시간이 걸릴 수 있지만 회복은 계속됩니다. 재발 위험도 초기 회복기보다 훨씬 낮습니다.';

  @override
  String get alcoholReferenceDay1 =>
      '술을 끊으면 수면에 어떤 변화가 생기나요?\n\n출처: \"Alcohol and the Sleeping Brain\"(Colrain, Nicholas & Baker), Handbook of Clinical Neurology — 동료 심사, NIH 수록\n\n알코올과 수면 구조\n알코올에는 진정 작용이 있어 잠드는 시간을 줄이고 밤 전반부의 깊은 서파 수면을 늘릴 수 있습니다. 하지만 그 대가로 REM(빠른 안구 운동) 수면을 억제하고, 알코올이 대사되는 밤 후반부의 수면을 잘게 끊어 놓습니다. REM 수면은 기억 공고화와 감정 조절에 중요한 회복 단계입니다.\n\n술 없이 보내는 첫날 밤\n알코올이 REM 수면을 억제하기 때문에 처음 며칠은 REM 반동으로 생생한 꿈과 가볍고 끊기는 잠이 나타날 수 있습니다. 정상적인 수면 패턴이 돌아오는 과정에서 흔히 나타나는 일시적인 현상입니다.\n\n회복의 시작\n다음 며칠과 몇 주 동안 뇌가 다시 적응하면서 REM 수면과 전반적인 수면의 질이 좋아집니다. 수면 장애는 금단과 관련된 증상 중 오래 지속되는 편이지만, 금주가 이어지면 점차 정상에 가까워집니다.\n\n과음에 대한 주의\n매일 많은 양을 마셨거나 장기간 음주한 사람은 처음 24시간에 불안, 발한, 떨림, 메스꺼움 같은 금단 증상이 나타날 수 있습니다. 심한 금단은 위험할 수 있으므로 매일 과음해 왔다면 갑자기 끊기 전에 의료진과 상담하세요.';

  @override
  String get alcoholReferenceDay3 =>
      '3일차: 금단 정점 구간\n\n출처: \"Alcohol Withdrawal\", StatPearls — 동료심사, NIH National Library of Medicine\n\n약 72시간\n알코올 금단 증상은 중단 후 몇 시간 안에 시작될 수 있고 흔히 약 72시간에 정점에 도달합니다. StatPearls는 떨림, 불면, 초조, 발한, 고혈압, 빠른 심박수, 발작을 이 과흥분 상태의 징후로 설명합니다.\n\n강한 3일\n72시간에 도달한 것은 큰 이정표입니다. 많은 급성 증상에서 문서화된 정점 구간에 바로 해당하기 때문입니다.\n\n심한 금단은 더 늦게 올 수 있습니다\n알코올 금단 섬망(delirium tremens)은 중단 후 3~8일에 발생할 수 있으며 치명적일 수 있습니다. 심한 금단은 의학적 응급상황입니다. 매일 많은 양을 마셨거나 금단 발작 또는 섬망 병력이 있는 사람은 도움 없이 갑자기 끊기보다 의료진의 조언을 받아야 합니다.\n\n주의해야 할 증상\n발열, 심한 초조, 과도한 발한, 환각, 지남력 저하, 발작, 매우 빠른 심박수 또는 매우 높은 혈압이 나타나면 즉시 의료 도움을 받아야 합니다.';

  @override
  String get alcoholReferenceDay7 =>
      '면역 체계는 어떻게 회복되나요?\n\n출처: \"Alcohol and the Immune System\"(Sarkar, Jung & Wang), Alcohol Research: Current Reviews — 동료 심사, NIH 수록\n\n알코올이 면역을 약화시키는 방식\n알코올은 여러 경로로 면역 체계를 약화시킵니다. 한 번의 과음만으로도 최대 24시간 동안 감염에 맞서는 능력이 떨어질 수 있습니다. 장기간의 음주는 백혈구를 줄이고 면역 신호를 흐트러뜨리며 장과 폐의 방어 기능을 손상시켜 감염 위험과 상처 회복 지연을 높입니다.\n\n해로운 자극을 없애기\n알코올 노출이 사라지면 이런 영향 중 많은 부분이 좋아지기 시작합니다. 백혈구와 면역 신호가 회복되고 장과 기도의 방어 기능도 복구되기 시작합니다. 첫 주에는 면역 체계가 더 이상 매일 알코올에 의해 억눌리지 않으면서 흔한 감염에 대한 저항력이 서서히 나아집니다.\n\n점진적인 과정\n면역 기능이 충분히 회복되려면 일주일보다 더 오래 걸립니다. 회복 정도는 이전 음주의 양과 기간에 따라 달라지지만, 술을 끊은 첫 주가 재건의 출발점입니다.';

  @override
  String get alcoholReferenceDay14 =>
      '금욕의 조기 뇌 회복\n\n출처: Bartsch AJ 외, \"알코올 중독 금욕과 관련된 초기 뇌 회복의 징후\", Brain(2007) — 동료 검토\n\n회복 측정\n이 연구에서는 MRI를 사용하여 금주 첫 주 동안 알코올 의존이 있는 최근 해독된 사람들을 추적하고 건강한 대조군과 비교했습니다. 음주를 중단한 후 뇌가 물리적으로 재건되는 모습을 포착했습니다.\n\n뇌량 리바운드\n만성 알코올 사용은 영구적인 세포 손실뿐만 아니라 세포 크기의 가역적인 감소를 부분적으로 통해 뇌를 수축시킵니다. 연구자들은 금욕을 통해 소뇌, 중뇌, 심실 및 전두엽 주변에 집중적으로 거의 2%에 달하는 전 세계 뇌 용적 증가를 측정했습니다. 이러한 재성장의 대부분은 술을 끊은 첫 2주 동안 초기에 발생합니다.\n\n소뇌와 주의력\n특히 움직임과 주의에 사용되는 뇌 영역의 회복이 뚜렷했습니다. 주의력의 측정 가능한 향상과 함께 뇌세포 건강 지표가 상승했기 때문에 신체적 치유는 사고력의 실질적인 향상을 가져왔습니다.\n\n마무리가 아닌 기초\n복잡한 추론과 같은 고급 기능은 점진적으로 회복되지만 처음 2주 동안은 알코올을 제거하면 뇌가 빠르게 치유되기 시작합니다.';

  @override
  String get alcoholReferenceDay30 =>
      '술을 끊으면 혈압이 떨어진다\n\n출처: Roerecke et al., \"혈압에 대한 알코올 소비 감소 효과: 체계적 검토 및 메타 분석\", Lancet Public Health(2017) — 동료 검토\n\n증거\n이 메타 분석은 사람들이 술을 덜 마실 때 혈압에 어떤 일이 일어나는지 테스트하는 36개의 무작위 시험(약 2,865명의 참가자)을 모았습니다. 이는 분명하고 복용량에 따른 효과를 발견했습니다. 즉, 혈압을 더 많이 줄일수록 혈압이 더 많이 떨어졌습니다.\n\n효과는 얼마나 큽니까?\n하루에 두 잔 이하의 술을 마신 사람들은 술을 줄여도 혈압에 큰 변화가 없었습니다. 이 임계값을 초과하면 효과는 용량에 따라 달라집니다. 하루에 6잔 이상의 음료를 마시는 사람들이 섭취량을 약 절반으로 줄인 경우 가장 강력했으며, 수축기 혈압은 평균 약 5.5mmHg, 확장기 혈압은 약 4.0mmHg 감소했습니다. 그 크기의 감소는 임상적으로 의미가 있습니다. 일부 혈압약과 비슷하며 장기적인 뇌졸중 및 심장병 위험을 낮추기에 충분합니다.\n\n한 달이 중요한 이유\n알코올은 스트레스 반응을 활성화하고 코티솔을 높이며 혈관을 경화시켜 혈압을 높입니다. 이 리뷰의 실험에서는 몇 주 동안 지속적인 감소를 통해 이점이 나타나는 것으로 나타났습니다. 따라서 약 한 달 동안 금욕을 하면 술을 많이 마시는 사람의 혈압이 더 건강한 수준으로 안정될 시간을 갖게 되었습니다.\n\n임계값 효과\n이 검토에서는 명확한 한계점을 발견했습니다. 하루에 두 잔 이상 술을 마시는 사람들에게 혜택이 집중되었으며, 이전에 술을 많이 마실수록 혜택이 점차 커졌습니다. 술을 적게 마시는 사람이라면 이러한 혈압 상승 효과를 기대하지 마십시오. 그러나 술을 많이 마시는 사람은 술을 끊음으로써 실질적이고 측정 가능한 심혈관 혜택을 얻을 수 있습니다.';

  @override
  String get alcoholReferenceDay60 =>
      '음주를 중단한 후 간 회복\n\n출처: 국립 알코올 남용 및 알코올 중독 연구소(NIAAA), \"알코올이 신체에 미치는 영향\"\n\n알코올이 간을 손상시키는 방법\n간은 우리가 마시는 대부분의 알코올을 처리하며, 가장 큰 피해를 입습니다. NIAAA는 알코올 관련 간 손상의 진행을 설명합니다. 이는 지방간(지방증 - 간 세포에 지방이 축적됨)으로 시작하여 알코올성 간염(염증)으로 진행될 수 있으며, 장기간 과다 사용하면 섬유증 및 간경변(반흔)으로 진행될 수 있습니다.\n\n이전 단계는 되돌릴 수 있습니다.\n중요한 점은 간은 재생 능력이 뛰어나며, 음주를 중단하면 이러한 손상의 초기 단계가 호전될 수 있다는 점입니다. 특히 지방간은 ​​지속적인 금욕으로 해결되는 경우가 많습니다. 약 2개월 동안 알코올을 마시지 않으면 간은 실시간으로 지방 축적물을 제거하고 염증을 진정시키며 더 건강한 기능을 회복하게 됩니다. 이는 일반적으로 간 효소 수치(ALT 및 AST) 감소에 반영됩니다.\n\n간 너머\nNIAAA는 알코올이 심장, 췌장 및 면역 체계에도 부담을 준다고 지적합니다. 신체가 지속적으로 알코올을 끊으면 이러한 시스템도 회복될 수 있습니다. 이는 이 단계에서 많은 사람들이 느끼는 꾸준한 에너지와 전반적인 건강 개선에 기여합니다.';

  @override
  String get alcoholReferenceDay90 =>
      '금주 3개월 후의 사고와 기억\n\n출처: 금주 후 신경심리학적 회복에 대한 체계적 문헌고찰(PubMed Central, 2024) — 동료 심사\n\n근거가 보여 주는 것\n이 문헌고찰은 술을 끊은 뒤 사고력과 기억력이 어떻게 회복되는지 추적한 연구들을 종합했습니다. 대부분의 능력은 대략 6~12개월 사이에 정상 범위로 가까워지며, 일부는 더 일찍 좋아집니다.\n\n먼저 좋아지는 능력\n기본적인 처리 속도와 작업 기억 업데이트는 비교적 일찍 회복되는 능력입니다. 처리 속도는 보통 약 한 달이면 좋아지지만 복잡한 과제의 정확도는 더 늦게 회복될 수 있습니다. 약 3개월이 되면 많은 사람이 이런 변화를 체감하기 시작합니다.\n\n더 오래 걸리는 부분\n주의력, 계획, 의사결정, 충동 조절, 지각과 기억력은 6~12개월의 회복 기간 동안 계속 좋아집니다.\n\n회복에 영향을 주는 요인\n회복에는 나이, 흡연 여부, 질환 이전의 능력 같은 요인이 영향을 줍니다. 반면 과거에 마신 총량과의 관계는 일관되게 나타나지 않았습니다. 전반적으로 예상되는 방향은 회복입니다.\n\n왜 중요한가?\n더 또렷한 사고는 실질적인 회복입니다. 주의력과 의사결정 능력이 좋아지면 치료를 계속하고 재발을 피하는 데 도움이 됩니다.';

  @override
  String get alcoholReferenceDay180 =>
      '금주 6개월 후의 뇌 회복\n\n출처: 물질 사용 중단 후 구조적·기능적 뇌 회복에 대한 동료 심사 문헌고찰(PubMed Central)\n\n회복은 계속됩니다\n첫 몇 주에 나타나는 뇌 용적의 초기 반등은 시작에 불과합니다. 금주가 이어지면 뇌는 구조와 기능 양쪽에서 계속 회복됩니다. 회백질이 회복되고, 뇌 영역 사이의 소통을 담당하는 손상된 백질 경로도 여러 달에 걸쳐 복구됩니다.\n\n뇌의 앞부분\n판단, 계획, 자기 통제를 담당하는 전두부의 회복은 특히 중요합니다. 이 영역이 회복되면서 의사결정과 충동 조절 능력도 강해집니다.\n\n뇌의 재조직과 기능\n물리적 회복과 함께 뇌의 기능과 연결도 좋아집니다. 뇌는 신경 연결을 재구성하고 다시 학습할 수 있으므로, 지속적인 금주는 치료와 새로운 습관을 쌓기에 중요한 시기입니다.\n\n회복의 신호\n6개월이 되면 뇌의 구조와 기능은 더 건강한 상태를 향해 분명히 움직이고 있습니다. 금주를 이어 갈수록 회복할 시간이 더 쌓입니다.';

  @override
  String get alcoholReferenceDay365 =>
      '알코올, 암 위험, 그리고 금주\n\n출처: 미국 국립암연구소(NCI), \"Alcohol and Cancer Risk\"\n\n알코올은 암을 유발합니다\nNCI는 음주가 암을 유발할 수 있다는 강한 과학적 합의가 있다고 설명합니다. 알코올은 구강, 인두, 후두, 식도, 간, 유방, 결장·직장암과 관련이 있습니다. 더 많이, 더 오래 마실수록 위험은 커집니다.\n\n알코올이 암 위험을 높이는 방식\n알코올의 독성 대사산물인 아세트알데히드가 DNA를 손상시키는 것, 산화 스트레스와 염증, 보호 영양소 흡수 저하, 그리고 유방암과 관련된 에스트로겐 상승 등이 기전에 포함됩니다.\n\n금주 후 위험은 낮아집니다\nNCI는 술을 끊는 것이 시간이 지나면서 위험 감소와 관련된다고 보고합니다. 구강암과 식도암의 높아진 위험은 금주 후 감소하지만, 술을 전혀 마시지 않은 사람의 위험 수준에 가까워지는 데에는 여러 해가 걸릴 수 있습니다. 1년 금주는 그 과정에서 의미 있는 단계입니다.\n\n겹쳐 쌓이는 이점\n1년에 도달하면 혈압 저하, 부정맥 위험 감소, 지속적인 간 회복 같은 심혈관·간 관련 이점도 함께 쌓입니다. 여기에 암 위험 감소가 더해집니다.';

  @override
  String get benzodiazepineReferenceDay7 =>
      '벤조디아제핀 금단: 첫 주\n\n출처: \"Clinical Guidelines for Withdrawal Management and Treatment of Drug Dependence in Closed Settings\", 세계보건기구(2009), NCBI Bookshelf\n\n안전이 우선입니다\n벤조디아제핀 금단은 발작을 일으킬 수 있습니다. WHO는 벤조디아제핀 용량을 점차 줄이는 것이 가장 안전한 관리 방법이며, 금단 증상을 완화하고 발작 예방에 도움이 된다고 설명합니다. 장기간 사용했다면 갑자기 중단하지 말고 의료진과 함께 감량하세요.\n\n금단이 시작되는 시기\nWHO의 시기는 약물의 작용 지속시간에 따라 다릅니다.\n• 단시간 작용(oxazepam, alprazolam, temazepam): 보통 마지막 복용 후 1–2일에 시작해 2–4주 이상 지속\n• 장시간 작용(diazepam, nitrazepam): 보통 마지막 복용 후 2–7일에 시작해 2–8주 이상 지속\n첫 주는 장시간 작용 벤조디아제핀까지 포함한 전형적인 발현 시기를 모두 포괄합니다.\n\n나타날 수 있는 증상\nWHO는 불안, 불면, 안절부절못함, 초조 또는 과민함, 집중력이나 기억력 저하, 근육 긴장 또는 통증을 제시합니다.\n\n모니터링\n금단의 심각도는 크게 변동할 수 있습니다. WHO는 증상과 합병증을 정기적으로 관찰하도록 권고하며, 폐쇄 환경 지침에서는 의료진이 3–4시간마다 환자와 대화하고 필요할 때 안심시키고 증상을 설명하도록 합니다.';

  @override
  String get benzodiazepineReferenceDay14 =>
      '벤조디아제핀 중단: 2주\n\n출처: Poyares 등, \"Chronic benzodiazepine usage and withdrawal in insomnia patients\", Journal of Psychiatric Research (2004), PubMed\n\n약 2주에 확인된 실제 회복 신호\n연구진은 수년 동안 매일 밤 벤조디아제핀을 복용해 온 지속성 불면증 환자들을 추적하고, 점진적 중단 15일 뒤 수면을 다시 측정했습니다. 만성 복용 중 측정값과 비교해 서파수면, 수면 EEG의 델타 활동, 주관적 수면의 질이 모두 개선되었습니다.\n\n깊은 잠이 돌아옵니다\n서파수면은 비REM 수면에서 가장 깊은 단계입니다. 15일째에는 서파수면과 델타 활동이 증가했고, 2단계 비REM 수면은 건강한 대조군에서 보인 패턴 쪽으로 감소했습니다.\n\n측정으로 확인된 초기 회복\n중단을 완료한 참가자들은 중단 직후 수면이 악화됐지만, 15일 추적 시점에는 객관적인 깊은 수면 지표와 주관적 수면의 질이 개선되었습니다. 따라서 2주는 실제로 측정된 회복의 이정표입니다.';

  @override
  String get benzodiazepineReferenceDay60 =>
      '벤조디아제핀: 8주 시점의 낮 시간 기능\n\n출처: Tsunoda 등, \"Effects of discontinuing benzodiazepine-derivative hypnotics on postural sway and cognitive functions in the elderly\", International Journal of Geriatric Psychiatry (2010), PubMed\n\n8주에 측정된 회복 신호\n연구진은 요양시설에 거주하며 벤조디아제핀 수면제를 사용하던 60세 이상 성인을 추적했습니다. 3주에 걸쳐 용량을 줄여 중단했고, 8주 시점에 인지 기능과 균형 검사를 다시 시행했습니다.\n\n집중력과 기억력이 상승\n연구를 완료한 26명에서는 즉각 기억, 주의력, 언어 지표 점수가 유의하게 향상되었습니다. 벤조디아제핀 중단 뒤 낮 시간 기능에서 실제로 측정된 개선입니다.\n\n서 있을 때도 더 안정적\n눈을 감은 상태의 자세 흔들림 지표도 유의하게 개선되었습니다. 연구진은 이 고령자 집단에서 벤조디아제핀 수면제 중단이 신체 안정성 향상과 낮 시간 인지 기능 회복과 관련됐다고 결론내렸습니다.\n\n수면은 안정적으로 유지\n연구를 완료한 사람들은 수면 설문에서 주관적인 수면 악화를 보고하지 않았습니다. 8주 시점에는 보고된 수면의 질 저하 없이 낮 시간 기능의 측정 가능한 향상이 확인됐습니다.';

  @override
  String get benzodiazepineReferenceDay90 =>
      '벤조디아제핀 중단 3개월: 더 빠른 사고, 덜한 진정감\n\n출처: Rickels et al., \"Psychomotor performance of long-term benzodiazepine users before, during, and after benzodiazepine discontinuation,\" Journal of Clinical Psychopharmacology (1999),, PubMed\n\n12주에 측정된 회복 신호\n연구진은 장기간 벤조디아제핀을 사용한 사람들을 감량 전과 감량 5주, 12주 후에 검사했습니다. 12주 자료는 77명에게서 확보됐고, 성공적으로 중단한 참가자는 매주 혈액검사로 벤조디아제핀을 복용하지 않았음을 확인했습니다.\n\n더 빠른 인지 수행\n벤조디아제핀 중단에 성공한 사람들은 계속 복용한 참가자보다 기호 베끼기와 숫자-기호 치환 과제를 더 빠르게 완료했습니다. 나이, 교육 수준, 초기 점수를 고려한 뒤에도 차이는 유의했습니다.\n\n정신적·신체적 진정감 감소\n성공적으로 중단한 사람들은 계속 복용한 사람들보다 정신적·신체적 진정감도 덜하다고 보고했습니다.\n\n3개월에 보일 수 있는 변화\n이 연구에서 중단에 성공한 사람들은 감량 12주 후 처리 속도가 측정 가능하게 좋아지고 정신적·신체적 진정감이 줄었습니다. 생각은 더 빨라지고 진정된 듯한 둔한 느낌은 약해졌습니다.';

  @override
  String get benzodiazepineReferenceDay180 =>
      '6개월의 사고력과 기억력: 측정 가능한 향상\n\n출처: Tata et al., \"장기 벤조디아제핀 사용 중단 후 인지 회복 부족\", Psychological Medicine(1994), PubMed\n\n연구 결과\n이 연구에서는 21명의 장기 벤조디아제핀 환자를 중단 전, 중단 직후, 그리고 다시 6개월간 중단한 후 대조 대조군과 비교하여 테스트했습니다. 이는 벤조 회수 문헌에서 가장 솔직한 데이터 포인트 중 하나입니다.\n\n무엇을 발견했나요?\n중단하기 전에 환자들은 언어 학습, 기억, 이동 속도, 시각적 조정 및 시각적 추론에 문제가 있었습니다. 멈춘 직후에는 거의 변화가 없었습니다. 6개월이 되자 이러한 영역 중 일부가 눈에 띄게 개선되었습니다.\n\n이것이 의미하는 바\n6개월이 되자 언어 학습, 기억력, 이동 속도, 시각적 조정 능력이 눈에 띄게 회복되었습니다. 개선 사항은 이미 명확했고 계속해서 개선할 여지가 있었습니다.\n\n더 큰 그림\n6개월이 되어도 몽롱함을 느낀다면, 이 연구에 따르면 그것은 예상된 일이며 지속적인 금욕이 앞으로 나아갈 길입니다. 장기간의 연구에 따르면 이 시점 이후에도 회복이 계속되며, 뇌는 계속 치유됩니다.';

  @override
  String get benzodiazepineReferenceDay365 =>
      '벤조디아제핀 복용 후 1년: 사고와 기억력이 계속 회복됨\n\n출처: Barker et al., \"장기 벤조디아제핀 사용 중단 후 인지 효과의 지속성: 메타 분석,\" Archives of Clinical Neuropsychology(2004), PubMed\n\n우리가 가지고 있는 가장 강력한 증거\n연구자들은 벤조디아제핀을 장기간 중단한 후 최소 6개월 후에 장기간 벤조디아제핀 사용자를 다시 테스트한 연구를 결합했습니다. 종합 결과는 금단 후 사고와 기억의 뚜렷한 회복을 보여줍니다.\n\n좋은 소식\n결합된 연구에서는 금단 후 사고와 기억의 여러 영역에서 실질적이고 측정 가능한 개선이 발견되었습니다. 약 1년이 지나면 회복은 적극적으로 사용하는 것에 비해 광범위하고 명백합니다.\n\n복구가 계속됩니다\n결합된 연구에서는 사고와 기억의 광범위한 회복이 발견되었습니다. 1년이 지나면 이미 6개월 만에 측정할 수 있었던 회복 추세를 잘 따르고 있습니다.\n\n1년에 이것이 의미하는 바\n1년이 지나면 사고력, 기억력, 명료성이 크게 회복될 것으로 예상됩니다. 대부분의 사람들은 사용하는 동안보다 눈에 띄게 예리함을 느낍니다. 그러나 일부 영역이 여전히 뒤처진다면 이는 지연되었다는 신호가 아니라 증거와 일치하는 것입니다. 회복은 계속되고 있으며, 금욕의 1년은 그 길에서 중요하고 가치 있는 이정표입니다.';

  @override
  String get benzodiazepineReferenceDay540 =>
      '벤조디아제핀 복용 후 18개월: 느리지만 실질적인 회복\n\n출처: Ashton, \"벤조디아제핀의 장기간 금단 증후군,\" 약물 남용 치료 저널(1991), PubMed\n\n벤조디아제핀 회복에 시간이 오래 걸리는 이유\n벤조디아제핀은 뇌의 주요 진정 시스템인 GABA에 작용합니다. 장기간 사용하면 시스템이 얼마나 강력하게 반응하는지 변경되며 이러한 변경 사항을 되돌리려면 몇 달이 걸릴 수 있습니다. 이것이 바로 벤조디아제핀 회복 과정을 몇 주가 아닌 몇 달 단위로 측정하는 이유입니다.\n\n18개월이 있는 곳\nAshton은 완화되는 데 몇 달이 걸릴 수 있는 오래 지속되는 금단 증상을 설명합니다. 18개월이 되면 최악의 상황은 대부분의 사람들보다 훨씬 뒤쳐지고 지속적인 불안, 감각 변화 및 뇌 혼미 현상이 실질적으로 해결됩니다.\n\n천천히 되돌릴 수 있음\n결정적으로 Ashton은 근본적인 변화를 \'중추 신경계의 천천히 가역적인 기능적 변화\'로 구성합니다. 느리지만 되돌릴 수 있습니다. 긴 타임라인은 대부분의 사람들에게 영구적인 손상이 아니라 벤조디아제핀으로 인한 적응의 깊이를 반영합니다.\n\n회복 신호\nAshton은 근본적인 변화를 천천히 되돌릴 수 있다고 설명합니다. 18개월이 되면 뇌의 진정 GABA 시스템이 안정되는 데 오랜 시간이 걸리며 주된 방향은 정상을 향한 지속적인 회복입니다.';

  @override
  String get benzodiazepineReferenceDay730 =>
      '벤조디아제핀 사용 후 2년: 주요하고 지속적인 진전\n\n출처: Barker et al., \"장기 벤조디아제핀 사용 중단 후 인지 효과의 지속성: 메타 분석,\" Archives of Clinical Neuropsychology(2004), PubMed\n\n회복의 중요한 이정표\n2년은 중요한 이정표입니다. 특히 오랜 금단 과정 이후에는 더욱 그렇습니다. 초기 및 지속적인 증상 단계는 오래 전에 지나갔고, 첫 해의 이득은 또 한 해 더 강화되었습니다.\n\n증거가 뒷받침하는 것\n결합된 연구는 금단 후 많은 영역에서 회복을 보여줍니다. 2년이 지나면 대부분의 사람들은 벤조디아제핀 사용 전 수준 이하의 불안, 약물 없이도 안정적인 수면, 안정된 감정, 사용 중보다 더 명확한 사고를 보고합니다.\n\n회복 신호\n결합된 연구는 사고와 기억의 여러 영역에 걸쳐 회복을 확립합니다. 2년 후에는 지속적인 회복이 증거에 의해 뒷받침될 것으로 예상됩니다.\n\n관점 유지\n2년은 수면, 기분, 기억력, 명확한 사고를 위한 긴 회복 기간을 제공합니다. 증거는 여기에서 치유가 계속되면서 네 가지 모두에서 상당한 개선을 보여줍니다.';

  @override
  String get benzodiazepineReferenceDay1095 =>
      '벤조디아제핀 복용 후 3년: 장기적인 치유\n\n출처: Barker et al., \"장기 벤조디아제핀 사용 중단 후 인지 효과의 지속성: 메타 분석,\" Archives of Clinical Neuropsychology(2004), PubMed\n\n장기적 관점\n3년은 벤조디아제핀의 장기 회복 과정에서 상당히 먼 지점입니다. 대다수의 사람들의 경우 장기간 지속되는 심한 금단 증상 후에도 파괴적인 증상은 훨씬 사라지고 적극적인 사용에 비해 삶의 질이 변화됩니다.\n\n메타 분석을 통해 밝혀진 것\n장기 사용자에 대한 종합 연구에서는 중단 후 여러 영역에서 회복이 나타나는 것으로 나타났습니다. 수년간 중단을 이어 간 연구에서 전반적인 양상은 사고, 기억 및 일상 기능의 광범위한 회복입니다.\n\n회복 신호\n장기 연구에 따르면 사고와 기억의 여러 영역에서 회복이 이루어지고 있는 것으로 나타났습니다. 3년이 지나면 초기 및 지속적인 금단 단계가 훨씬 뒤쳐지고 이러한 이득을 강화하는 데 수년이 걸렸습니다.\n\n희망의 메시지\n벤조 회복 여정은 의학에서 가장 힘든 과정 중 하나이며, 3년간의 지속적인 치유는 엄청난 성과입니다. 증거는 분명합니다. 뇌가 실질적으로 치유되고 대부분의 사람들이 명료함, 수면 및 감정 범위를 회복하며 시간이 지남에 따라 개선이 계속됩니다.';

  @override
  String get benzodiazepineReferenceDay1460 =>
      '벤조디아제핀 중단 4년: 지속되는 진전\n\n출처: ASAM이 주도한 다학제 「벤조디아제핀 감량 공동 임상진료지침」(2025)\n\n지침이 뒷받침하는 내용\n지침은 벤조디아제핀 중단 후 적응이 약물이 몸에서 제거되는 시간보다 훨씬 오래 이어질 수 있다고 설명합니다. 일부 사람은 수개월 또는 수년 동안 지연성 금단 증상을 겪을 수 있으므로 회복은 개인별로 관찰하고 지원해야 합니다.\n\n4년의 의미\n지침은 4년에 모두가 도달하는 보편적인 생물학적 종점을 정하지 않습니다. 따라서 이 이정표는 과장 없이, 회복이 각자의 속도로 진행될 수 있음을 인정하면서 4년간 지속한 변화 자체를 기념합니다.\n\n기념할 만한 이정표\n4년은 1,460일입니다. 회복이 순조로웠든 들쭉날쭉했든 그 시간은 분명한 성취입니다.';

  @override
  String get benzodiazepineReferenceDay1825 =>
      '벤조디아제핀 중단 5년: 장기적 성취\n\n출처: ASAM이 주도한 다학제 「벤조디아제핀 감량 공동 임상진료지침」(2025)\n\n하나의 결승선은 없습니다\n지침은 벤조디아제핀 금단과 중단 후 적응이 사람마다 다르다고 강조합니다. 5년이 되면 뇌나 몸이 완전히 회복됐다고 선언하는 보편적인 기준은 제시하지 않습니다.\n\n5년이 뜻하는 것\n5년은 진정한 장기 기념일입니다. 1,825일간 지속한 변화 속에서 습관, 지원, 일상이 수년 동안 뿌리내릴 시간을 가졌습니다.\n\n노력 자체에 의미가 있습니다\n이 이정표는 만들어 낸 의학적 기한이 아니라 실제로 이어 온 노력을 기념합니다. 5년의 꾸준한 진전은 그 자체로 큰 성취입니다.';

  @override
  String get cocaineReferenceDay1 =>
      '코카인 금단: 첫 24시간\n\n출처: \"Withdrawal Syndromes\", StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\n코카인과 뇌\n코카인은 뇌의 보상 회로에서 도파민과 다른 모노아민의 재흡수를 막아 도파민이 축적되게 하고 강한 행복감과 에너지를 만들어 냅니다. 반복해서 사용하면 뇌는 이 시스템의 활동을 낮추는 방식으로 적응하기 때문에 약물이 없을 때 일상적인 활동이 덜 보람 있게 느껴질 수 있습니다.\n\n\'크래시\' 단계\nStatPearls는 자극제 사용을 중단한 뒤 나타나는 금단이 \'크래시\' 단계로 시작한다고 설명합니다. 이 단계는 뚜렷한 우울감, 과도한 수면, 허기, 저조한 기분, 움직임과 사고의 심한 둔화를 특징으로 합니다. 첫 24시간에는 보통 다음이 포함됩니다:\n• 극심한 피로와 늘어난 수면 욕구\n• 우울한 기분과 느려진 움직임 및 사고\n• 식욕 증가. 코카인은 식욕을 억제합니다\n\nStatPearls가 이를 크래시의 개별 항목으로 열거하지는 않지만, 더 넓은 중독 연구에서는 이 시기에 강한 코카인 사용 욕구, 과민함, 불안도 매우 흔하게 보고됩니다.\n\n일부 다른 약물과의 차이\nStatPearls는 자극제 금단을 관찰과 지지 치료로 관리한다고 설명합니다. 알코올이나 벤조디아제핀 금단과 달리 일반적으로 발작이나 섬망을 일으키지는 않습니다. 주요 위험은 심리적입니다. 크래시 동안 우울증이 나타날 수 있고 사용량이 많은 사람에게는 자살 사고가 생길 수 있어 지원과 관찰이 권장됩니다.\n\n승인된 약물 없음\n현재 코카인 금단을 치료하도록 승인된 약물은 없습니다. 치료는 지지적으로 이루어지며, 컨틴전시 매니지먼트 같은 비약물적 접근은 기저의 물질사용장애에 근거가 있는 치료법입니다.';

  @override
  String get cocaineReferenceDay3 =>
      '코카인 없이 3일: 가장 힘든 시기\n\n출처: \"Cocaine Toxicity\", StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\n코카인이 몸에 미치는 영향\nStatPearls는 코카인이 도파민, 노르에피네프린, 세로토닌의 재흡수를 막아 교감신경 자극을 오래 지속시킨다고 설명합니다. 이 작용은 행복감을 만들면서 동시에 위험을 높이며, 거의 모든 장기계에 영향을 줄 수 있습니다.\n\n2~4일: 심리적 금단의 정점\n3일 무렵에는 급성 크래시가 가장 강한 심리적 금단 단계로 넘어가는 경우가 많습니다:\n• 가장 심한 저조한 기분과 우울감\n• 즐거움을 느끼기 어려움\n• 단서나 상황에 의해 촉발되는 강한 사용 욕구\n• 불안과 초조함\n• 수면 장애. 어떤 사람은 지나치게 많이 자고, 다른 사람은 불면을 겪습니다\n\n심혈관 위험은 줄어들기 시작합니다\nStatPearls는 심혈관 독성을 코카인의 가장 치명적인 영향으로 설명합니다. 심박수와 혈압 상승, 심근의 산소 요구량 증가, 관상동맥 혈관 연축, 혈소판 활성화가 젊은 사람에게도 부정맥, 심근경색, 뇌졸중 위험을 높입니다. 코카인 자체의 반감기는 약 한 시간으로 짧아 3일째에는 약물이 몸에서 제거되어 있습니다. 다만 대사산물이 사용 뒤 몇 시간 동안 혈관 수축을 일으킬 수 있고 한 대사산물은 수주 동안 남을 수 있어, 일부 심혈관 부담은 코카인 자체보다 오래 지속될 수 있다고 StatPearls는 설명합니다.\n\n앞으로의 과정\n급성 단계는 힘들지만 우울감, 사용 욕구, 즐거움 상실 같은 심리적 증상이 가장 많은 지원을 필요로 하고 가장 오래 지속될 수 있습니다.';

  @override
  String get cocaineReferenceDay7 =>
      '코카인 없이 1주: 신체 회복 시작\n\n출처: \"Withdrawal Syndromes\", StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\n급성 단계가 끝나 갑니다\nStatPearls는 코카인 금단이 초기 크래시에서 더 긴 회복 단계로 넘어간다고 설명합니다. 첫 주가 끝날 무렵에는 가장 심한 증상이 보통 완화되기 시작하고 도파민 시스템은 계속 회복됩니다.\n\n신체 회복 진행\n코카인에 의한 교감신경 자극이 멈추면 심혈관계, 식욕, 수면, 기도에 미친 영향이 이후 며칠과 수주에 걸쳐 되돌아가기 시작합니다:\n• 심박수와 혈압이 정상 범위 쪽으로 돌아갑니다\n• 코카인이 강하게 억제했던 식욕이 서서히 돌아옵니다\n• 수면 양상이 안정되기 시작합니다\n• 코카인을 코로 흡입했다면 비강이 회복되기 시작합니다\n\n심리적 증상은 더 오래 갈 수 있습니다\nStatPearls는 우울감과 즐거움 상실이 자극제 금단의 특징이며 신체 증상보다 더 오래 이어질 수 있다고 설명합니다:\n• 기분은 낮게 유지되지만 정점보다는 보통 덜 심합니다\n• 단서에 의해 촉발되는 사용 욕구는 여전히 강할 수 있습니다\n• 집중력과 동기는 아직 저하되어 있을 수 있습니다\n\n급성기 이후\n이후 회복은 수주 또는 수개월에 걸쳐 기분, 사용 욕구, 명확한 사고가 더 느리지만 꾸준히 좋아지는 단계로 이어집니다. 이런 흐름을 아는 것은 느린 회복 구간을 이해하는 데 도움이 됩니다.';

  @override
  String get cocaineReferenceDay14 =>
      '코카인 없이 2주: 안정감 회복\n\n출처: \"Withdrawal Syndromes\", StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\n2주 시점\n2주가 지나면 깊은 우울감, 지나친 수면, 느려진 움직임과 사고 같은 심한 크래시 증상은 대체로 크게 완화됩니다. 이제 회복은 뇌와 정서 건강을 다시 세우는 데 더 집중됩니다.\n\n기분과 정서 상태\n도파민 시스템이 회복되는 동안 2주 시점에도 기분은 정상보다 낮을 수 있습니다. 첫 주와 비교하면 심한 즐거움 상실이 완화되기 시작하고 실제로 편안함이나 만족감을 느끼는 순간이 돌아옵니다.\n\n사용 욕구와 촉발 요인\n상황이나 단서에 의해 촉발되는 사용 욕구는 이 단계에서 중요한 과제입니다. 뇌는 코카인 사용을 특정 환경, 사람, 감정, 활동과 강하게 연결해 두었을 수 있습니다. 전반적인 기분이 좋아져도 이런 촉발 요인을 만나면 강한 사용 욕구가 생길 수 있습니다. 고위험 환경을 피하고 새로운 연관성을 만드는 것이 중요합니다.\n\n수면 개선\n2주 시점의 수면은 급성 금단기보다 대체로 더 안정적이고 회복에 도움이 됩니다. 수면이 좋아지면 기분, 명확한 사고, 사용 욕구를 관리하는 능력에도 긍정적인 영향을 줍니다.\n\n기반 다지기\n자극제 사용장애에 근거가 있는 치료는 행동 치료 중심이며 컨틴전시 매니지먼트, 치료, 동료 지원 등이 포함됩니다. 2주 시점은 장기 회복을 뒷받침할 지원 체계와 연결되기 좋은 시기입니다.';

  @override
  String get cocaineReferenceDay60 =>
      '코카인 없이 2개월: 기분과 보상 체계의 회복\n\n출처: \"Recovering from Cocaine: Insights from Clinical and Preclinical Investigations\", Neuroscience & Biobehavioral Reviews (2013), PubMed Central\n\n뇌에서 일어나는 변화\n이 종설은 코카인 사용을 중단했을 때 뇌에서 나타나는 변화를 다룬 사람과 동물 연구를 종합합니다. 만성적인 코카인 사용은 도파민 시스템을 변화시키고 전두피질의 활동을 낮춥니다. 이러한 시스템의 회복은 초기 금단기에 나타나는 기분과 동기의 개선을 뒷받침합니다.\n\n보상 체계의 변화\n동물 연구에서는 코카인과 관련된 도파민 수용체 및 운반 단백질 변화가 지속적인 사용 중단과 함께 건강한 수준 쪽으로 돌아갔습니다. 보상 체계가 회복되면서 심한 즐거움 상실이 완화되고 음식, 관계, 성취 같은 일상의 보상이 다시 보람 있게 느껴질 수 있습니다.\n\n회복의 신호\n2개월 시점에는 기분이 좋아지고 수면이 더 안정되며 도파민과 전두피질 시스템은 계속 회복됩니다. 영장류 연구에서는 코카인과 관련된 D1 수용체 및 운반체 변화가 지속적인 사용 중단과 함께 대조군 수준 쪽으로 돌아가는 모습을 보였습니다.';

  @override
  String get cocaineReferenceDay90 =>
      '코카인 없이 3개월: 도파민 지표의 회복\n\n출처: \"Recovering from Cocaine: Insights from Clinical and Preclinical Investigations\", Neuroscience & Biobehavioral Reviews (2013), PubMed Central\n\n90일이 의미 있는 이유\n이 종설은 3개월 시점을 생물학적으로 의미 있는 시점으로 다룹니다. 사람 이외의 영장류에서는 코카인으로 증가했던 도파민 D1 수용체와 운반체가 약 90일 동안 사용하지 않은 뒤 대조군 수준 쪽으로 돌아간다는 증거가 나타났습니다. 이는 약물 사용이 끝난 뒤 보상 체계가 다시 적응할 수 있음을 보여 주는 직접적인 근거입니다.\n\n뇌 앞부분\n저자들은 뇌 앞부분의 회복을 장기간의 사용 중단에서 중요한 신호 중 하나로 강조합니다. 이 영역은 충동 조절, 의사결정, 자기 통제를 담당하며 회복과 함께 이런 능력도 강화됩니다.\n\n90일이 보여 주는 것\n90일 시점의 영장류 연구에서는 D1, D2 및 도파민 운반체 밀도가 약물에 노출되지 않은 대조군과 더 이상 유의하게 다르지 않았습니다. 장기간 노출 뒤에도 이 시점에는 상당한 도파민 시스템 회복이 관찰되며, 사용 중단이 이어지면 회복도 계속됩니다.';

  @override
  String get cocaineReferenceDay180 =>
      '코카인 없이 6개월: 더 선명한 사고\n\n출처: \"Structural and Functional Brain Recovery in Individuals with Substance Use Disorders During Abstinence: A Review of Longitudinal Neuroimaging Studies\", PubMed Central\n\n영상으로 확인되는 회복\n이 종설은 사용 중단 기간이 길어지는 동안 같은 사람을 반복해서 촬영한 종단 뇌 영상 연구를 종합합니다. 코카인에 대해서는 지속적인 사용 중단과 함께 기능적 뇌 활동이 측정 가능한 수준으로 회복된다고 보고합니다.\n\n뇌 영상 근거\n두 건의 기능적 MRI 연구가 코카인 사용자를 시간에 따라 추적했고, 둘 다 사용 중단 기간이 길수록 중뇌와 시상의 활성화가 개선되는 것을 확인했습니다. 한 연구에서는 약 6개월 동안 사용하지 않은 뒤 뇌 활성화 양상이 중독이 없는 건강한 대조군과 비슷했습니다. 여러 물질을 함께 살핀 결과에서도 핵의학 영상 결과가 사용 중단에 따른 도파민계 회복을 시사한다고 종설은 설명합니다.\n\n6개월 시점의 의미\n이러한 기능적 개선은 이 단계에서 사람들이 보고하는 일상 변화와도 맞닿아 있습니다:\n• 더 나은 주의력과 작업 기억\n• 더 나은 의사결정과 충동 조절\n• 더 안정된 기분과 감정 조절\n\n회복의 신호\n약 6개월 시점에 한 종단 fMRI 코호트는 중독이 없는 건강한 대조군과 비슷한 활성화 양상을 보였고, 사용 중단 기간이 길어질수록 중뇌와 깊은 뇌 영역의 활성화가 개선되었습니다. 이는 영상으로 직접 관찰된 기능적 뇌 회복입니다.';

  @override
  String get cocaineReferenceDay365 =>
      '코카인 없이 1년: 반복되는 심혈관 부담의 중단\n\n출처: \"Cocaine Toxicity\", StatPearls (NCBI Bookshelf), U.S. National Library of Medicine\n\n심장이 중요한 이유\nStatPearls는 심혈관 독성을 코카인의 가장 치명적인 영향으로 설명합니다. 사용할 때마다 심박수와 혈압, 심근의 산소 요구량이 올라가고 관상동맥 혈관 연축과 혈전 형성이 촉진됩니다. 이 조합은 젊은 사람에게도 심장마비, 부정맥, 뇌졸중 위험을 높입니다.\n\n1년 동안 사용하지 않으면 사라지는 반복 부담\n코카인을 사용하지 않는 매일은 이런 급성 부담이 없는 날입니다. 1년 동안 사용으로 인한 혈압과 심박수의 반복적인 급등이 사라지고, 새로운 사용으로 유발되는 관상동맥 연축과 급성 심근경색 위험도 없어지며, 심장이 산소 수요와 공급의 불균형에 반복해서 노출되지 않습니다.\n\n회복의 신호\n코카인 사용을 중단하면 급성 심장 손상을 일으키는 반복적인 관상동맥 혈관 연축, 빈맥, 고혈압, 혈전 촉진, 산소 불균형이 멈춥니다. 기존의 섬유화나 심근염은 여전히 의학적 문제로 남지만 코카인으로 인한 반복 손상은 중단됩니다.\n\n뇌 회복도 계속됩니다\n1년 동안 보상 및 자기 통제 시스템은 회복할 시간을 충분히 얻습니다. 이는 더 나은 충동 조절, 더 안정된 기분, 일상적인 보상에 대한 더 강한 반응을 뒷받침합니다.';

  @override
  String get cocaineReferenceDay730 =>
      '코카인 없이 2년: 지속적인 회복\n\n출처: \"Recovering from Cocaine: Insights from Clinical and Preclinical Investigations\", Neuroscience & Biobehavioral Reviews (2013), PubMed Central\n\n장기적 관점\n이 종설은 장기간 코카인을 사용하지 않았을 때 나타나는 변화를 다룬 사람과 동물 연구를 종합합니다. 핵심 결론은 전두피질 기능의 보존과 회복이 장기적인 코카인 사용 중단을 보여 주는 중요한 지표라는 것입니다. 10개월 넘게 사용하지 않은 사람들은 더 짧은 기간 사용하지 않은 사람들보다 전두피질 활동이 높았습니다.\n\n계속되는 회복\n• 코카인으로 변한 도파민 관련 지표는 사용 중단이 이어지면서 정상 범위 쪽으로 계속 이동합니다\n• 현재 사용 중이거나 사용 중단 초기인 사람에게서 관찰되는 회백질과 백질의 무결성 저하는 더 오래 사용하지 않을수록 개선될 수 있으며, 지속적인 미엘린 성숙이 한 요인일 수 있습니다\n• 충동 조절, 판단, 감정 조절을 담당하는 전두엽 조절 회로가 강화됩니다\n\n회복의 신호\n저자들은 중요한 과학적 주의점을 제시합니다. 장기간 사용하지 않은 사람들에게서 보이는 차이의 일부는 \"생존자 효과\"를 반영할 수 있습니다. 처음부터 뇌의 무결성이 더 좋았던 사람이 사용 중단을 유지하기 더 쉬웠을 수 있으므로, 모든 차이를 회복만으로 설명할 수는 없습니다. 분명한 점은 코카인을 2년 동안 사용하지 않는 상태가 비사용자에 훨씬 가까운 뇌 기능과, 단순히 사용을 중단한 것을 넘어 크게 재건된 삶을 뒷받침한다는 것입니다.';

  @override
  String get cocaineReferenceDay1095 =>
      '코카인 없이 3년: 더 단단한 기반\n\n출처: SAMHSA, Treatment of Stimulant Use Disorders\n\nSAMHSA의 근거 기반 지침은 코카인을 명확히 다루며 장기 회복을 돕는 방법에 초점을 둡니다. 3년을 모두에게 적용되는 생물학적 종착점으로 정하지는 않습니다.\n\n3년 자체가 오래 이어온 큰 성취입니다. 회복을 지속 가능하게 해 주는 일상, 지원, 대처 전략을 계속 지켜가세요.';

  @override
  String get cocaineReferenceDay1460 =>
      '코카인 없이 4년: 이어지는 전진\n\n출처: SAMHSA, Treatment of Stimulant Use Disorders\n\nSAMHSA는 코카인을 포함한 자극제 사용 장애에 대해 근거 기반 접근과 장기 회복 지원을 설명합니다. 4년을 보편적인 의학적 종착점으로 제시하지는 않습니다.\n\n4년은 평범한 날과 힘든 시기, 큰 순간을 지나서도 변화가 이어졌다는 증거입니다.';

  @override
  String get cocaineReferenceDay1825 =>
      '코카인 없이 5년: 뿌리내린 변화\n\n출처: SAMHSA, Treatment of Stimulant Use Disorders\n\nSAMHSA 지침은 코카인을 포함한 자극제 사용 장애에서 장기 회복을 목표로 하는 근거 기반 치료를 지지합니다. 5년을 생물학적 결승선으로 주장하지는 않습니다.\n\n5년은 변화를 꾸준히 유지해 온 시간입니다. 그 꾸준함과 그 위에 세운 삶이 바로 이 이정표입니다.';

  @override
  String get ghbReferenceDay1 =>
      'GHB 금단: 첫 몇 시간\n\n출처: “Characterization of the GHB Withdrawal Syndrome”, PubMed Central\n\n⚠ 의료 응급상황입니다\nGHB 금단은 가장 위험한 물질 금단 중 하나로, 심한 알코올이나 벤조디아제핀 금단에 맞먹을 수 있습니다. 치료하지 않으면 절반이 넘는 사례에서 섬망으로 진행할 수 있고, 심박수와 혈압의 위험한 변동 및 발작이 나타날 수 있습니다. GHB, GBL 또는 1,4-부탄디올에 의존하는 사람은 혼자 끊지 말고 입원 상태에서 감독받는 해독 치료를 받아야 합니다.\n\n왜 이렇게 빨리 시작되는가\nGHB의 반감기는 30–60분에 불과합니다. 의존이 생긴 사람은 금단을 피하기 위해 보통 2–3시간마다 다시 사용해야 하며, 이는 알코올이나 벤조디아제핀보다 훨씬 짧은 간격입니다. 이런 빠른 약동학 때문에 다른 진정·수면제 금단보다 증상이 훨씬 빨리 나타날 수 있습니다.\n\n초기 증상\n불안, 불면, 떨림, 발한, 빠른 심박수, 혈압 상승.';

  @override
  String get ghbReferenceDay3 =>
      'GHB 금단: 가장 힘든 며칠\n\n출처: “Characterization of the GHB Withdrawal Syndrome”, PubMed Central\n\n가장 힘든 구간\n이 연구에서는 근육통, 근육 경련, 긴장되고 스트레스받는 느낌, 빠른 심박수, 복부 경련 같은 핵심 금단 증상이 첫 3일에 가장 심했고, 4일째에는 많은 증상의 심각도가 70% 넘게 감소했습니다. 이 초기 구간은 일반적으로 위험이 가장 높은 시기이며, 치료하지 않은 금단이 섬망, 발작, 또는 심박수와 혈압의 위험한 변동으로 악화될 가능성이 가장 큽니다.\n\n심한 증상\n• 심한 초조와 불안\n• 청각·시각 환각, 편집증\n• 떨림, 발한, 심계항진, 고혈압\n• 발작 위험\n\n치료\n연구에서는 벤조디아제핀 감량과 의약품 GHB 감량을 흔히 사용되는 두 해독 방법으로 설명하며, GHB 감량이 벤조디아제핀 단독보다 증상을 더 효과적으로 조절할 수 있다는 일부 근거도 언급합니다. 어느 방법이든 면밀한 관찰이 필요하며 집에서 스스로 관리하는 것은 안전하지 않습니다.';

  @override
  String get ghbReferenceDay7 =>
      'GHB 없이 일주일\n\n출처: “Characterization of the GHB Withdrawal Syndrome”, PubMed Central\n\n대부분의 증상이 가라앉는 중\n여러 핵심 금단 증상은 첫 4일 동안 심각도나 빈도가 70% 넘게 감소했습니다. 의료진의 감독 아래 감량했을 때 감량 단계는 평균 11일, 이후 회복 단계는 약 6일이었습니다. 따라서 일주일 시점에는 과정이 완전히 끝나지 않았더라도 많은 사람이 이미 상당한 호전을 겪고 있습니다.\n\n남을 수 있는 증상\n• 발한, 떨림, 손 떨림\n• 지나치게 많이 자거나 반대로 불면과 안절부절못함\n• GHB에 대한 갈망\n\n연구에서는 이런 증상이 11일까지도 비교적 적게 변했습니다. 따라서 일주일째에도 남아 있는 것은 드문 일이 아닙니다. 증후군이 분명히 가라앉을 때까지 의료진의 지속적인 관찰이 중요합니다.';

  @override
  String get ghbReferenceDay14 =>
      'GHB 없이 2주\n\n출처: “Characterization of the GHB Withdrawal Syndrome”, PubMed Central\n\n급성 증후군을 지나\n2주가 되면 이 연구에서 설명한 급성 신체 증후군은 대개 해소되었거나 거의 끝나 가는 단계입니다. 감독 치료에서 감량과 회복 단계는 합쳐 평균 약 17일이었습니다. 심박수, 혈압, 대부분의 신체 증상도 안정되는 시기입니다.\n\n남을 수 있는 것\n연구는 일부 환자에서 퇴원 시에도 갈망과 불면이 남아 있었고, 이것이 재발 위험에 기여할 수 있다고 지적합니다. 위험한 초기 단계가 지나도 지원과 생활 구조는 여전히 중요합니다.';

  @override
  String get ghbReferenceDay30 =>
      'GHB 없이 한 달\n\n출처: “Characterization of the GHB Withdrawal Syndrome”, PubMed Central\n\n한 달의 위치\n한 달 시점에는 이 연구에서 설명한 급성 위험 단계가 이미 오래전에 지나 있습니다. 가장 위험한 시기는 첫 며칠에 집중됐고, 그 뒤에는 평균 약 2주 반의 감독된 감량·회복 기간이 이어졌습니다. 퇴원 시 확인된 주요 잔여 재발 위험은 갈망과 불면이었습니다.\n\n지원이 계속 도움이 되는 이유\n한 달이 지나도 갈망, 우울한 기분, 수면 문제가 남아 있다면 이는 연구진이 재발 위험 요인으로 언급한 내용과 맞습니다. 그래서 지속적인 지원과 규칙적인 생활이 중요합니다.';

  @override
  String get ghbReferenceDay90 =>
      'GHB 없이 3개월\n\n출처: “Characterization of the GHB Withdrawal Syndrome”, PubMed Central\n\n3개월의 회복\n3개월이면 급성 GHB 금단 증후군은 이미 오래전에 끝난 상태입니다. 퇴원 시 남아 있던 위험으로는 갈망과 불면이 언급됐기 때문에, GHB 없이 3개월을 보내는 것은 수면, 자율신경계 안정, 재발 예방 습관이 자리 잡을 충분한 시간을 줍니다.\n\n흔히 보고되는 변화\n• 평소 기분이 더 차분함\n• 더 안정적인 수면\n• 더 명료한 사고와 줄어든 갈망\n\n3개월이 지나도 불안, 불면, 우울한 기분이 뚜렷하다면 저절로 해결될 것이라 단정하지 말고 의료진과 상의할 가치가 있습니다.';

  @override
  String get ghbReferenceDay180 =>
      'GHB 없이 6개월\n\n출처: “Characterization of the GHB Withdrawal Syndrome”, PubMed Central\n\n반년 후\n6개월이면 급성 GHB 금단 증후군은 오래전에 끝났고, 회복의 초점은 해독에서 안정적인 수면, 갈망 관리, 재발 예방으로 완전히 옮겨갑니다. 자율신경계가 크게 흔들리고 섬망 위험이 높은 시기는 첫 며칠과 몇 주에 해당하며 이 단계가 아닙니다.\n\n더 큰 그림\n위험한 GHB 금단을 안전하게 넘기고 반년 동안 사용하지 않은 것은 큰 성취입니다. 초기 단계가 위험하고, 남은 갈망과 불면이 재발 위험에 영향을 줄 수 있다는 점을 생각하면 더욱 그렇습니다. 여기까지 오게 한 습관과 지원은 계속 지킬 가치가 있습니다.';

  @override
  String get inhalantsReferenceDay1 =>
      '흡입제 중단: 첫날\n\n출처: Radparvar, \"The Clinical Assessment and Treatment of Inhalant Abuse\", The Permanente Journal (2023), PubMed Central\n\n금단이 생기는 이유\n흡입제를 만성적으로 사용하면 신경계가 물질의 존재에 적응하는 신경적응이 일어납니다. 많은 흡입제는 알코올과 비슷한 뇌 회로에 영향을 주기 때문에 사용을 중단하면 뇌가 일시적으로 불균형한 상태가 될 수 있습니다. 화학물질은 혈액에서는 빠르게 줄어들지만 체지방에 저장될 수 있어 금단 시점을 정확히 예측하기 어렵습니다.\n\n초기 증상\n이 검토 논문은 흡입제 금단을 알코올이나 벤조디아제핀 금단과 비슷하다고 설명하며, 보고된 증상에는 다음이 포함됩니다.\n• 메스꺼움, 구토, 발한\n• 떨림과 빠른 심박수\n• 불면증과 수면 장애\n• 불안과 과민함\n\n안전 참고\n더 심한 경우에는 환각, 망상, 발작도 보고된 증상에 포함됩니다. 다만 논문은 정확한 일별 일정을 제시하지 않으므로, 이를 고정된 시간표가 아니라 발생할 수 있는 증상으로 봐야 합니다. 특히 장기간 많이 사용한 경우에는 해독 과정에서 의료진의 감독을 받는 것이 바람직합니다.';

  @override
  String get inhalantsReferenceDay7 =>
      '흡입제를 끊은 지 1주\n\n출처: Radparvar, \"The Clinical Assessment and Treatment of Inhalant Abuse\", The Permanente Journal (2023), PubMed Central\n\n급성기\n임상 문헌에서는 흡입제 금단을 알코올이나 벤조디아제핀 금단과 비슷하지만 대체로 더 짧게 지속되는 것으로 설명합니다. 첫 주가 끝날 무렵에는 메스꺼움, 떨림, 발한, 불면증 같은 급성 신체 증상이 대부분의 사람에게서 보통 가라앉기 시작합니다.\n\n남을 수 있는 증상\n• 피로와 머리가 멍한 느낌\n• 가라앉거나 불안정한 기분\n• 강한 사용 욕구\n\n초기 금단에 관한 참고\n이 시기의 머리가 멍한 느낌이 영구적인 손상을 뜻하는 것은 아닙니다. 뇌는 여전히 다시 적응하는 중입니다. 이후의 이정표에서는 사고와 기억이 다음 몇 주와 몇 달 동안 어떻게 회복되는지에 대한 연구를 다룹니다.';

  @override
  String get inhalantsReferenceDay14 =>
      '흡입제를 끊은 지 2주\n\n출처: Radparvar, \"The Clinical Assessment and Treatment of Inhalant Abuse\", The Permanente Journal (2023), PubMed Central\n\n급성기를 지나며\n임상 검토에서는 흡입제 금단을 알코올이나 벤조디아제핀 금단과 비슷하지만 더 짧은 것으로 설명합니다. 2주가 지나면 메스꺼움, 떨림, 불면증, 불안은 대개 가라앉습니다.\n\n앞으로의 회복\n주의력, 기억력, 움직임, 협응은 이후 몇 달에 걸쳐 더 천천히 회복됩니다. 계속 사용하지 않는 것은 이런 기능들이 나아질 시간을 줍니다. 흡입제 사용은 비타민 B12를 고갈시킬 수 있으므로, 좋은 영양 상태와 금단 유지가 회복에 도움이 되는 조건을 만듭니다.';

  @override
  String get inhalantsReferenceDay30 =>
      '흡입제를 끊은 지 1개월\n\n출처: Dingwall 등, \"Cognitive recovery during and after treatment for volatile solvent abuse\", Drug and Alcohol Dependence (2011), PubMed\n\n한 달의 위치\n초기 금단 기간은 이미 충분히 지나왔습니다. 이 연구에서는 일부 학습 능력이 6주 안에 좋아졌고, 시각적 협응, 기억, 계획, 의사결정은 이후 몇 달 동안 더 점진적으로 개선됐습니다.\n\n좋아질 수 있는 부분\n• 주의력과 일부 학습 과제\n• 몸이 안정되면서 나아지는 기분과 수면\n• 운동 속도의 점진적인 개선\n\n회복 신호\n연구의 결론은 분명합니다. 기억, 계획, 의사결정 능력은 수개월에서 수년의 금단 기간에 걸쳐 점진적으로 좋아집니다. 계속 사용하지 않는 것이 이 회복을 이끄는 가장 강력한 요인입니다.';

  @override
  String get inhalantsReferenceDay90 =>
      '흡입제를 끊은 지 3개월\n\n출처: Dingwall 등, \"Cognitive recovery during and after treatment for volatile solvent abuse\", Drug and Alcohol Dependence (2011), PubMed\n\n고르지 않고 더 긴 과정\n이 연구는 8주 치료 프로그램 이후까지 참가자들을 추적했고, 일부는 약 1년 뒤 다시 평가했습니다. 일부 학습 능력은 6주 안에 개선됐지만 시각적 협응, 기억, 계획, 의사결정은 더 긴 기간에 걸쳐 계속 좋아졌습니다.\n\n꾸준히 이어가기\n연구는 회복이 느린 기능도 수개월에서 수년에 걸쳐 점차 나아질 수 있음을 보여줍니다. 3개월 시점에는 계속 사용하지 않는 것이 매달 더 많은 회복을 쌓는 가장 중요한 요인입니다.';

  @override
  String get inhalantsReferenceDay365 =>
      '흡입제를 끊은 지 1년\n\n출처: \"A prospective study of neurocognitive changes 15 years after chronic inhalant abuse\", PubMed\n\n실제로 측정된 회복\n장기 연구에서는 만성 흡입제 사용과 관련된 뇌 및 사고 기능 문제가 2년의 금단 후 크게 회복된 것으로 나타났습니다. 1년 시점에는 그 회복 경로를 상당 부분 지나온 셈입니다.\n\n의미\n기억력, 주의력, 운동 기능은 계속 좋아집니다. 장기 금단은 실제 뇌 회복을 가능하게 합니다. 납으로 인한 뇌 손상이 없었던 만성 사용자에서는 2년 시점에 뇌 기능, 기억, 사고의 대부분 점수가 정상 범위로 돌아왔습니다.';

  @override
  String get inhalantsReferenceDay730 =>
      '흡입제를 끊은 지 2년\n\n출처: \"A prospective study of neurocognitive changes 15 years after chronic inhalant abuse\", PubMed\n\n2년이라는 지점\n연구에서 핵심이 되는 시점입니다. 장기간의 용제 사용으로 인한 뇌 손상을 반영하던 결손은 2년의 금단 후 크게 회복됐습니다. 연구진은 납 함유 휘발유로 인한 뇌 손상이 없다면 장기 금단을 통해 정상적인 뇌 기능이 회복될 수 있다고 결론지었습니다.\n\n회복 신호\n주요 예외는 납 함유 휘발유 남용으로 인한 손상으로, 지속적인 결손을 남길 수 있습니다. 그 밖의 경우 2년의 금단은 뇌가 회복할 수 있는 가장 잘 문서화된 기회를 보여 주며, 그와 함께 삶도 다시 세워집니다.';

  @override
  String get ketamineReferenceDay1 =>
      '케타민 중단: 첫날\n\n출처: PubMed Central의 “Ketamine-Induced Cystitis: A Comprehensive Review of the Urologic Effects of This Psychoactive Drug”\n\n금단은 주로 심리적입니다\n오피오이드나 알코올과 달리 케타민은 심한 신체적 금단을 일으키는 경우가 드뭅니다. 중단은 일반적으로 안전하며, 신체적 질환보다는 사용 욕구와 심리적 의존으로 어려움을 겪는 경우가 더 많습니다.\n\n느낄 수 있는 변화\n• 기분 변화와 가라앉은 기분\n• 케타민 사용 욕구\n• 간헐적인 발한이나 두근거림\n\n핵심 단계\n방광 증상이 있다면 즉시 완전히 중단하는 것이 회복의 필수 출발점입니다. 그래서 첫날의 결정이 무엇보다 중요합니다.';

  @override
  String get ketamineReferenceDay7 =>
      '케타민 없이 1주\n\n출처: PubMed Central의 “Ketamine-Induced Cystitis: A Comprehensive Review”\n\n심리적 단계\n케타민 중단 초기의 주된 어려움은 심리적입니다. 사용 욕구, 변하거나 가라앉은 기분, 브레인 포그가 나타날 수 있습니다. 신체적 금단이 있다면 대개 가볍습니다.\n\n이 시기에는 브레인 포그가 흔합니다. 집중하기가 힘들고 반응 속도가 느려지며 단기 기억이 불안정하게 느껴질 수 있습니다. 사고와 기억에 미치는 이런 영향은 케타민을 사용하지 않는 동안 개선됩니다. 케타민 사용자 114명을 추적한 종단 연구에서는 케타민 없이 12주를 보낸 뒤 언어 기억, 시각 기억, 처리 속도, 계획, 집중, 의사 결정이 유의하게 향상됐습니다.\n\n방광 증상\n케타민 유발 방광염(절박뇨, 빈뇨, 통증 또는 혈뇨)이 있다면 지금 중단하는 것이 방광에 가장 좋은 회복 기회를 줍니다. 통증 때문에 자가 치료 목적으로 케타민을 다시 사용할 수 있으므로, 적절한 통증 관리 지원으로 이 악순환을 끊는 것이 중요합니다.';

  @override
  String get ketamineReferenceDay14 =>
      '케타민 없이 2주\n\n출처: PubMed Central의 “Ketamine-Induced Cystitis: A Comprehensive Review”\n\n더 맑아지는 사고\n약물이 완전히 빠져나가면 정기적인 케타민 사용과 관련된 정신적 안개와 단절된 사고가 걷히기 시작합니다. 기억력과 집중력이 좋아지고 기분도 안정됩니다.\n\n방광 회복의 시작\n초기 방광염에서는 케타민을 중단하는 것이 증상을 되돌리는 가장 중요한 단계이며, 손상이 영구적으로 남기 전에 일찍 중단할수록 회복 가능성이 높다고 이 문헌고찰은 강조합니다. 케타민 없이 2주를 보내는 것이 그 과정의 시작입니다.';

  @override
  String get ketamineReferenceDay30 =>
      '케타민 없이 1개월\n\n출처: “Prevalence and Natural History of Urinary Symptoms Among Recreational Ketamine Users”, Winstock 외, BJU International (2012)\n\n방광 회복\n케타민 유발 방광염에서 가장 중요한 치료는 케타민을 중단하는 것입니다. 기분 전환 목적으로 케타민을 사용한 사람들을 조사한 이 연구에서는 요로 증상이 있던 사람의 51%가 사용 중단 뒤 호전을 보고했고, 악화된 사람은 4% 미만이었습니다. 더 일찍 중단할수록 결과가 좋습니다.\n\n사고와 기분\n한 달이 지나면서 인지와 기분은 계속 맑아집니다. 심리적·사회적 지원은 중단을 유지할 가능성을 의미 있게 높여 줍니다. 지원을 받을 때 중단을 더 잘 이어 갈 수 있습니다.';

  @override
  String get ketamineReferenceDay90 =>
      '케타민 없이 3개월\n\n출처: PubMed Central의 “Ketamine-Induced Cystitis: A Comprehensive Review”\n\n계속되는 회복\n케타민 중단 뒤 방광 회복은 흔히 서서히 진행됩니다. 문헌고찰은 중단 뒤 증상의 심각도가 호전될 수 있지만 회복 기간과 정도에는 차이가 있다고 설명합니다. 중단에 반응하는 경우, 3개월은 요로가 회복할 수 있는 지속적인 시간을 제공합니다.\n\n사고\n사고와 기분은 중단 초기보다 훨씬 맑아지고, 케타민 사용 욕구도 덜 자주 나타납니다. 방광 증상이 계속되거나 심하면 비뇨의학과 진료를 받아야 합니다.';

  @override
  String get ketamineReferenceDay180 =>
      '케타민 없이 6개월\n\n출처: PubMed Central의 “Ketamine-Induced Cystitis: A Comprehensive Review”\n\n반년이 지난 뒤\n케타민을 계속 사용하지 않으면 중단에 반응하는 경우 방광 증상이 계속 호전되고, 사고와 기억, 기분도 안정됩니다. 사용 충동은 크게 약해집니다.\n\n회복의 신호\n이미 생긴 방광 손상은 완전히 회복되지 않을 수 있기 때문에 조기 중단이 매우 중요합니다. 어느 단계에서 중단했든 계속 케타민을 사용하지 않는 것이 방광에 가능한 최선의 결과를 줍니다.';

  @override
  String get ketamineReferenceDay365 =>
      '케타민 없이 1년\n\n출처: PubMed Central의 “Ketamine-Induced Cystitis: A Comprehensive Review”\n\n1년이 지난 뒤\n케타민 없이 12개월을 보내면 조기에 발견된 경우 방광이 회복할 수 있는 최대한의 시간을 얻고, 사고와 기억, 기분도 안정되고 맑아집니다. 중단을 어렵게 했던 심리적 의존도 대부분 약해졌습니다.\n\n더 큰 변화\n케타민 없이 보낸 1년은 신체 건강, 사고의 명료함, 스스로 방향을 정하는 힘에 큰 변화를 뜻합니다. 여기까지 오게 한 지원을 계속 유지하는 것이 이 변화를 지키는 데 도움이 됩니다.';

  @override
  String get ketamineReferenceDay730 =>
      '케타민 없이 2년\n\n출처: 케타민 유발 방광염에 관한 2022년 종합 문헌고찰(PubMed Central).\n\n이 문헌고찰은 케타민 중단을 강하게 권고하며, 초기 질환은 중단 후 호전되는 경우가 많지만 손상이 진행된 경우 회복이 불완전할 수 있다고 설명합니다. 2년을 보편적인 생물학적 종착점으로 정하지는 않습니다. 이 이정표는 모두에게 같은 의학적 결과를 약속하지 않고 지속된 진전을 기념합니다.';

