  @override
  String get kratomReferenceDay1 =>
      '크라톰 금단: 첫날\n\n출처: Swogger 등 (2022), “Understanding Kratom Use: A Guide for Healthcare Providers,” Frontiers in Pharmacology\n\n금단 증상이 생기는 이유\n크라톰의 활성 성분은 전통적 오피오이드와 같은 오피오이드 수용체에 작용합니다. 규칙적으로 사용하면 신체가 적응하므로 중단 시 오피오이드와 비슷한 금단 증상이 나타날 수 있습니다. 이 임상 안내서는 의존과 금단을 규칙적인 크라톰 사용의 알려진 위험으로 설명합니다.\n\n발현 시점에 대한 근거\n안내서가 인용한 동물 연구에서는 약 12시간 안에 신체적 금단 징후가 나타나고 24시간에는 불안과 비슷한 효과가 관찰되었습니다. 사람에서 정확히 언제 시작되는지는 덜 확립되어 있지만 흔히 보고되는 초기 증상은 다음과 같습니다.\n• 안절부절못함, 불안, 과민함\n• 근육통과 콧물\n• 발한과 눈물\n• 강한 사용 욕구\n\n중증도에 대한 참고\n안내서는 사용 기간이 길고 용량이 높을수록 더 심하고 오래 지속되는 금단과 관련 있다고 설명합니다. 특히 고용량으로 사용했거나 오피오이드와 함께 사용했다면 의료진의 감독을 받는 지원을 고려할 가치가 있습니다.';

  @override
  String get kratomReferenceDay3 =>
      '크라톰 금단: 가장 힘든 날들\n\n출처: Singh 등 (2014), Drug and Alcohol Dependence — 말레이시아의 정기적 크라톰 사용자 293명 대상 설문\n\n근거가 보여 주는 것\n이 설문은 하나의 정해진 ‘정점 날짜’가 있는 것이 아니라 금단의 심한 정도가 사용량과 사용 기간에 따라 달라진다는 점을 보여 줍니다. 매일 크라톰을 세 잔 이상 마신 사람은 심한 의존과 더 어려운 금단을 겪을 가능성이 훨씬 높았습니다. 대부분의 사람에게는 중단 후 처음 며칠이 가장 힘듭니다.\n\n흔히 보고되는 증상\n• 근육과 관절 통증, 하지불안\n• 극심한 피로에도 불구한 불면\n• 메스꺼움, 복부 경련, 설사\n• 불안, 우울한 기분, 과민함\n• 강한 사용 욕구\n\n이 시기를 넘기기\n수분 섭취, 휴식, 증상 완화 지원이 도움이 됩니다. 지금까지 금단이 심하게 느껴졌다면 비정상적인 문제가 생겼다기보다 사용량이 많았거나 사용 기간이 길었던 것과 더 잘 맞으며, 대개 이 시점부터 완화되는 경향이 있습니다.';

  @override
  String get kratomReferenceDay7 =>
      '크라톰 없이 1주\n\n출처: Swogger 등 (2022), “Understanding Kratom Use: A Guide for Healthcare Providers,” Frontiers in Pharmacology\n\n급성기를 지나\n안내서에 인용된 사람 대상 자기보고 자료에 따르면 중단한 대부분의 사람에서 금단 증상은 약 1~3일 안에 가라앉습니다. 일주일 시점에는 근육통, 발한, 메스꺼움 같은 급성 신체 증상이 대개 대부분 가라앉습니다. 남을 수 있는 것은 피로, 수면 방해, 우울한 기분처럼 더 심리적인 부분이며, 크라톰이 자극하던 오피오이드 수용체가 신체 고유의 신호에 다시 적응해 가는 과정과 함께 나타날 수 있습니다.\n\n실제 위험\n안내서는 소수의 사람에게 크라톰 중단이 매우 어렵고, 사용량이 많거나 장기간 사용한 사람에서 더 심하고 오래 지속되는 금단이 보고된다고도 설명합니다. 이 시기는 다시 사용하기 쉬운 때이며 내성은 빠르게 낮아집니다. 특히 다른 오피오이드가 관련된 경우 예전 용량으로 돌아가는 것은 실제로 위험할 수 있습니다.';

  @override
  String get kratomReferenceDay14 =>
      '크라톰 없이 2주\n\n출처: National Institute on Drug Abuse (NIDA), “Kratom”\n\n연구된 기간을 넘어서\n크라톰 금단 시기에 대한 통제된 사람 대상 자료는 대체로 처음 며칠만 다루므로 정확히 2주를 특정 회복 이정표로 정하는 확립된 연구는 없습니다. 다만 더 넓은 양상은 알려져 있습니다. 크라톰은 전통적 오피오이드와 같은 오피오이드 수용체에 작용하며, 규칙적인 사용을 중단하면 이 수용체가 신체 고유의 신호에 대한 민감도를 서서히 회복합니다.\n\n사람들이 흔히 보고하는 변화\n• 식욕과 에너지가 좋아지는 경우가 많습니다\n• 수면이 더 안정되는 경향이 있습니다\n• 기분도 대체로 안정되지만 여전히 변동할 수 있습니다\n\n사용 욕구는 스트레스와 익숙한 단서로 여전히 유발될 수 있으므로 이를 다룰 계획을 마련해 두는 것이 계속 도움이 됩니다.';

  @override
  String get kratomReferenceDay30 =>
      '크라톰 없이 1개월\n\n출처: National Institute on Drug Abuse (NIDA), “Kratom”\n\n회복 중인 보상 체계\nNIDA는 크라톰이 뇌의 오피오이드 수용체에 작용하며 의존과 금단이 규칙적인 사용의 알려진 위험이라고 설명합니다. 한 달을 특정 회복 지점으로 정하는 연구는 없지만, 오피오이드 수용체 기반 의존에서는 사용을 지속적으로 중단할수록 일상의 즐거움에 대한 뇌의 반응이 서서히 정상화되는 일반적 양상이 있습니다.\n\n한 달이 만드는 변화\n크라톰 없이 한 달을 보내는 동안 사용에 들던 시간과 노력을 규칙적인 수면, 식사, 일상이 대신할 수 있습니다. 사용 욕구는 덜 자주 나타나고 관리하기 쉬워지는 경향이 있지만, 스트레스가 큰 순간은 여전히 가장 취약할 수 있습니다.';

  @override
  String get kratomReferenceDay90 =>
      '크라톰 없이 3개월\n\n출처: National Institute on Drug Abuse (NIDA), “Kratom”\n\n더 안정적인 일상 상태\n크라톰은 오피오이드 수용체에 작용하므로 3개월 동안 사용하지 않으면 뇌의 보상 및 스트레스 체계가 안정될 지속적인 시간을 갖습니다. 많은 사람이 적극적으로 사용하던 시기에서 멀어질수록 생각이 더 맑아지고 동기가 더 안정된다고 보고합니다.\n\n왜 중요한가\n마지막 사용 시점이 멀어질수록 크라톰의 일상적인 끌림은 보통 약해집니다. 이 이정표는 장기적인 회복을 위한 단단한 기반이 될 수 있습니다.';

  @override
  String get kratomReferenceDay365 =>
      '크라톰 없이 1년\n\n출처: National Institute on Drug Abuse (NIDA), “Kratom”\n\n급성 금단을 훨씬 지난 시점\nNIDA는 크라톰의 1년 회복 일정을 따로 제시하지 않습니다. 다만 1년간 지속적으로 사용하지 않은 상태는 크라톰 연구에서 문서화된 급성 및 초기 심리적 금단 시기를 훨씬 지난 것입니다. 이 지점에 도달한 대부분의 사람에게 사용 욕구는 드물고 훨씬 관리하기 쉬워집니다.\n\n더 큰 그림\n1년간 사용하지 않았다는 것은 건강, 재정, 자기 주도성에서 큰 변화를 뜻합니다. 지원과 계속 연결되어 있으면 그 진전을 지키는 데 도움이 됩니다.';

  @override
  String get kratomReferenceDay730 =>
      '크라톰 없이 2년\n\n출처: Stanciu et al. (2021), “Pharmacotherapy for Management of \'Kratom Use Disorder\': A Systematic Literature Review With Survey of Experts.”\n\n근거가 말하는 것\n이 문헌고찰은 크라톰 의존, 재발 위험, 장기 관리 접근을 다룹니다. 동시에 크라톰의 장기 금단 상태를 유지하기 위한 확립된 지침은 없다고 밝힙니다. 이 기념일을 생물학적 회복의 완료 시점으로 규정하는 근거도 없습니다.\n\n이 기념일의 의미\n이 날짜는 의학적 마감 시점이 아니라 지속해 온 변화를 기념하는 날로 보는 것이 적절합니다. 여러 해 동안 이어 온 습관, 지원, 선택은 그 자체로 중요한 성취입니다.';

