      '크라톰 없이 3년\n\n출처: Stanciu et al. (2021), “Pharmacotherapy for Management of \'Kratom Use Disorder\': A Systematic Literature Review With Survey of Experts.”\n\n근거가 말하는 것\n이 문헌고찰은 크라톰 의존, 재발 위험, 장기 관리 접근을 다룹니다. 동시에 크라톰의 장기 금단 상태를 유지하기 위한 확립된 지침은 없다고 밝힙니다. 이 기념일을 생물학적 회복의 완료 시점으로 규정하는 근거도 없습니다.\n\n이 기념일의 의미\n이 날짜는 의학적 마감 시점이 아니라 지속해 온 변화를 기념하는 날로 보는 것이 적절합니다. 여러 해 동안 이어 온 습관, 지원, 선택은 그 자체로 중요한 성취입니다.';

  @override
  String get kratomReferenceDay1460 =>
      '크라톰 없이 4년\n\n출처: Stanciu et al. (2021), “Pharmacotherapy for Management of \'Kratom Use Disorder\': A Systematic Literature Review With Survey of Experts.”\n\n근거가 말하는 것\n이 문헌고찰은 크라톰 의존, 재발 위험, 장기 관리 접근을 다룹니다. 동시에 크라톰의 장기 금단 상태를 유지하기 위한 확립된 지침은 없다고 밝힙니다. 이 기념일을 생물학적 회복의 완료 시점으로 규정하는 근거도 없습니다.\n\n이 기념일의 의미\n이 날짜는 의학적 마감 시점이 아니라 지속해 온 변화를 기념하는 날로 보는 것이 적절합니다. 여러 해 동안 이어 온 습관, 지원, 선택은 그 자체로 중요한 성취입니다.';

  @override
  String get kratomReferenceDay1825 =>
      '크라톰 없이 5년\n\n출처: Stanciu et al. (2021), “Pharmacotherapy for Management of \'Kratom Use Disorder\': A Systematic Literature Review With Survey of Experts.”\n\n근거가 말하는 것\n이 문헌고찰은 크라톰 의존, 재발 위험, 장기 관리 접근을 다룹니다. 동시에 크라톰의 장기 금단 상태를 유지하기 위한 확립된 지침은 없다고 밝힙니다. 이 기념일을 생물학적 회복의 완료 시점으로 규정하는 근거도 없습니다.\n\n이 기념일의 의미\n이 날짜는 의학적 마감 시점이 아니라 지속해 온 변화를 기념하는 날로 보는 것이 적절합니다. 여러 해 동안 이어 온 습관, 지원, 선택은 그 자체로 중요한 성취입니다.';

  @override
  String get maoiReferenceDay3 =>
      'MAOI 중단: 가장 위험한 단계\n\n출처: Dilsaver(1988), MAOI 금단반응 연구\n\n중요한 안전 경고\nMAOI는 모든 항우울제 계열 중에서 가장 심각한 중단 위험을 안고 있습니다. 특히 페넬진과 트라닐시프로민의 갑작스러운 중단은 다음과 같은 심각한 반응을 일으킬 수 있습니다.\n• 심한 불안과 동요\n• 압박감 있는 말투와 안절부절 못함\n• 불면증 또는 졸음\n• 환각\n• 섬망 및 편집증 정신병\n\n이러한 증상이 나타나면 즉시 의사의 진료를 받으십시오.\n\nMAOI의 작동 방식\nMAOI는 모노아민 산화효소(MAO-A 및 MAO-B)에 비가역적으로 결합하고 비활성화하는 방식으로 작동합니다. 이 효소는 일반적으로 뇌와 장에서 세로토닌, 노르에피네프린, 도파민, 티라민을 분해합니다. 단순히 차단되는 것이 아니라 효소 자체가 파괴되기 때문에 회복은 약물이 혈류를 얼마나 빨리 제거하느냐보다는 신체에서 신선한 효소를 생산하는 데 달려 있습니다.';

  @override
  String get maoiReferenceDay7 =>
      'MAOI 후 1주일: MAO 효소 합성 진행 중\n\n출처: \"모노아민 산화효소 억제제(MAOI)\"(StatPearls, NCBI Bookshelf)\n\n효소 회복 과정\n뇌의 화학적 재흡수를 가역적으로 억제하는 SSRI, SNRI 및 TCA와는 달리, 비가역적 MAOI(페넬진, 트라닐시프로민)는 모노아민 산화효소 효소 분자를 영구적으로 파괴합니다. 따라서 임상적 휴약 기간은 약물 자체가 혈류를 얼마나 빨리 제거하는가보다는 신체가 얼마나 빨리 완전히 새로운 효소를 합성할 수 있는지(약 2주)에 따라 결정됩니다.\n\n일주일 동안 무슨 일이 일어나고 있나요?\n• MAO-A 및 MAO-B 효소 합성이 잘 진행되고 있으며 대략 2주 재합성 기간의 중간쯤입니다.\n• 면밀한 의료 감독이 여전히 중요하지만 3일차에 설명된 급성 위험 단계는 지나가고 있습니다.\n\n식이상의 주의사항\nMAOI 치료에는 저티라민 식단이 필요합니다. 왜냐하면 이 효소는 일반적으로 티라민을 분해하여 고혈압 위기를 유발하는 것을 방지하기 때문입니다. 지침은 이 재합성 창을 통해 식이 제한 사항을 계속 관찰하는 것입니다. 처방자는 언제 완화해도 안전한지 조언할 것입니다.';

  @override
  String get maoiReferenceDay14 =>
      'MAOI 중단 2주 후: MAO 효소 활동이 실질적으로 회복됨\n\n출처: Fritz et al. (1983), 생물학적 정신의학\n\n중요한 2주 시점\n트라닐시프로민이나 페넬진과 같은 비가역적 MAOI를 중단한 후 MAO 효소 회복을 위한 표준 임상 휴약 기간은 2주입니다. 트라닐시프로민을 연구한 이 연구에서는 전체 MAO-B 단백질 수치가 전혀 변하지 않았음에도 불구하고 신체가 약물에 영향을 받은 혈소판을 활성 효소를 함유한 새로운 혈소판으로 대체함에 따라 투여 하루 만에 급격히 감소한 혈소판 MAO-B 촉매 활성이 약 2주 이내에 정상으로 회복된다는 사실을 발견했습니다.\n\nMAO 효소 회복\n• 혈소판 MAO-B 활동은 이 시점에 실질적으로 회복되었습니다.\n• 대체로 유사한 재합성 타임라인을 따르는 뇌 MAO-A 및 MAO-B도 대부분 복원됩니다.\n• 정상적인 티라민 대사가 다시 이루어지고 있습니다. MAOI 식이 제한은 일반적으로 처방자와 상담하여 완화할 수 있습니다.\n\n뇌-화학 균형 회복\nMAO 효소 활동이 회복되면서 MAOI가 영향을 미치는 뇌 화학 시스템이 자연적으로 조절되기 시작했습니다.\n• 세로토닌, 노르에피네프린, 도파민은 MAO 억제로 인해 더 이상 상승하지 않습니다.\n• 모노아민 수용체의 과민성(만성 MAOI로 인한 뇌 화학 수치 증가로 인해 발생)이 해결되기 시작했습니다.\n• 자연스러운 기분과 에너지 조절이 돌아오고 있습니다.';

  @override
  String get maoiReferenceDay30 =>
      'MAOI 중단 1개월 후: 뇌화학 시스템 재조정\n\n출처: \"모노아민 산화효소 억제제(MAOI)\"(StatPearls, NCBI Bookshelf)\n\n1개월 평가\nMAOI 중단 후 1개월은 이 출처에 설명된 대략 2주간의 MAO 효소 재합성 기간을 훨씬 지나서, 이 시점에서 MAO 효소 활동은 완전히 회복되었으며 뇌 화학 시스템은 완전히 자연적으로 조절됩니다.\n\n한 달 동안 회복된 것\n• 완전한 MAO 효소 활성: MAO-A와 MAO-B 모두 완벽하게 작동합니다.\n• 식이 제한 사항 해결: 티라민 제한 사항이 없는 일반 식이 요법\n• 자연적인 세로토닌 분해: 뇌의 정상적인 세로토닌 전환 주기가 회복됩니다.\n• 천연 카테콜아민 조절: 천연 MAO 활동에 의해 조절되는 도파민 및 노르에피네프린 수치\n\n약물 상호작용 주의사항\nMAOI는 세로토닌 약물과의 생명을 위협하는 상호작용과 관련이 있습니다. 이러한 상호 작용 위험은 한 달 만에 해결되었습니다. 그러나 새로운 약을 처방할 때는 항상 처방자와 약사에게 이전 MAOI 사용 사실을 알리십시오.';

  @override
  String get maoiReferenceDay90 =>
      'MAOI 중단 3개월 후: 급성 금단기를 지나\n\n출처: \"Antidepressant Withdrawal Syndrome\", Therapeutics Letter 112(2018), Therapeutics Initiative, NCBI Bookshelf\n\n항우울제 계열 전반의 금단\n이 근거 검토는 항우울제 금단을 내성과 의존과 관련된 실제 현상으로 다룹니다. 자세한 근거는 주로 SSRI와 SNRI에 초점을 맞추지만, MAOI 중단을 포함해 여러 항우울제 계열에서 금단 반응이 인정됩니다. 증상은 \"대개 중단 후 며칠 안에 나타나고\", \"대부분… 2주 안에 해소\"되지만 일부는 더 오래 지속될 수 있습니다.\n\n3개월 시점\n3개월이면 급성 금단기는 대부분의 사람에게 훨씬 이전의 일이 되었고, 신체는 이미 오래전부터 MAO 억제 없이 모노아민을 조절하도록 적응해 왔습니다.\n\n회복 신호와 \"수용체 재감작\"\n세로토닌, 노르에피네프린, 도파민 수용체가 모두 \"3개월이면 완전히 재감작된다\"고 단정하는 것은 근거가 뒷받침하는 범위를 넘어섭니다. 확실하게 말할 수 있는 것은 금단기가 대체로 이미 끝났고, 대부분의 사람에게서 기분, 에너지, 감정의 폭이 자연스럽고 자가 조절되는 뇌 신호에 맞춰 안정되고 있다는 점입니다.\n\n금단과 재발\nTherapeutics Letter는 금단과 기저 질환의 실제 재발을 구분해야 한다고 강조합니다. 3개월에도 증상이 계속되면 단순한 금단이라고 가정하지 말고 처방의와 함께 검토하십시오.';

  @override
  String get maoiReferenceDay180 =>
      'MAOI 중단 6개월 후: 장기 회복\n\n출처: Zwiebel & Viguera(2022), Cleveland Clinic Journal of Medicine\n\n6개월 평가\n이 검토는 항우울제가 시간이 지나면서 모노아민 수용체를 하향 조절하는 방식으로 일부 작용하며, 약물을 중단한 뒤 이 변화가 되돌아오는 데 몇 주에서 몇 달이 걸릴 수 있다고 설명합니다. 이는 약 2주가 걸리는 MAO 효소 재합성보다 느린 과정입니다.\n\n6개월 시점\n6개월은 대부분의 사람에게 몇 주에서 몇 달에 걸친 수용체 재조정 기간을 충분히 지난 시점이며, 효소 활동은 첫 달 안에 정상화됩니다. 세로토닌, 노르에피네프린, 도파민 수용체가 완전히 재감작되는 정확한 시점을 문헌이 하루 단위로 확정하지는 않습니다. 신뢰할 수 있는 점은 6개월이면 대부분의 사람이 자연스럽고 자가 조절되는 뇌 신호에 따라 기능한다는 것입니다.\n\n페네틸아민에 대한 참고\nMAOI는 기분과 에너지와 관련된 미량 아민인 페네틸아민(PEA)의 분해도 억제합니다. 그 대사는 전반적인 MAO 효소 회복과 함께 정상화될 것으로 예상되지만, 수용체 재감작과 마찬가지로 PEA만의 정확한 회복 시점은 연구 문헌에 확립되어 있지 않습니다.';

  @override
  String get maoiReferenceDay365 =>
      'MAOI 중단 1년 후: 회복의 한 해\n\n출처: \"Monoamine Oxidase Inhibitors (MAOIs)\" (StatPearls, NCBI Bookshelf)\n\n1년: 중요한 성취\nMAOI 중단 후 1년을 채운 것은 매우 의미 있는 이정표입니다. MAOI는 비가역적 작용 기전, 엄격한 저티라민 식단, 다른 항우울제 계열과 다른 약물 상호작용 주의사항 때문에 중단 과정에 특별한 관리가 필요합니다.\n\n이 한 해가 의미하는 것\n• 첫 달에 효소 재합성이 완료된 뒤 자연스럽고 자가 조절되는 모노아민 산화효소 활동을 1년 동안 유지함\n• 약물에 의한 MAO 억제 없이 웰빙을 유지할 수 있는 능력을 보여 줌\n• 3일차의 급성 중단 위험이 확실히 지나갔다고 볼 수 있을 만큼 충분히 긴 시간\n\nMAOI에 대한 참고\nMAOI는 일부 치료 저항성 질환과 비정형 우울증에서 여전히 특히 효과적입니다. 성공적으로 중단했다는 사실은 약물로서의 가치를 낮추지 않습니다. 이는 뇌의 회복 능력과 까다로운 의료 과정을 지나온 역량을 보여 줍니다. 한 가지 장기적인 주의사항은 새로운 처방의나 마취의에게 과거 MAOI 사용 사실을 계속 알리는 것입니다. 일부 약물 상호작용 위험은 장기적으로도 알려 둘 가치가 있습니다.';

  @override
  String get marijuanaReferenceDay1 =>
      '마리화나 금단: 첫날\n\n출처: PubMed Central의 \"대마초 금단 증후군: 현재 통찰력\" 약물 남용 및 재활(2017)\n\n대마초 금단는 현실입니다\n이 동료 검토 검토는 대마초 금단 증후군(CWS)이 대마초 중단 후 대마초 의존 진단을 받은 사람들의 약 90%에서 발생하는 잘 검증된 임상 상태임을 입증합니다. 평균 최고 심각도는 담배 금단 증후군의 심각도와 비슷합니다.\n\n탈퇴가 발생하는 이유\nTHC는 기분, 식욕, 수면, 기억 및 스트레스에 관여하는 CB1 수용체인 체내칸나비노이드 시스템에 작용합니다. 만성적으로 사용하면 뇌가 이 시스템을 하향 조절합니다. 대마초가 멈추면 일시적으로 활동이 저하됩니다. 검토 결과에 따르면 CB1 수용체는 금주 후 약 4주 이내에 정상적인 기능으로 돌아옵니다.\n\n첫날 발병\n리뷰에는 신체적 증상이 마지막 사용 후 1~3일 이내에 처음 나타나는 경향이 있는 반면, 심리적 증상은 2~10일에 걸쳐 나타나는 경향이 있다고 기록되어 있습니다. 초기 증상은 다음과 같습니다:\n• 과민성, 불안, 안절부절 못함\n• 수면 장애\n• 식욕 감소\n• 신체적 긴장, 발한 또는 오한\n• 우울한 기분\n\n심각도\nCWS는 의학적으로 위험하지 않으며 증상은 일반적으로 경증에서 중등도이지만 검토에서는 재발을 유발할 만큼 고통스러울 수 있다고 지적합니다. 이것이 바로 타임라인을 이해하는 것이 중요한 이유입니다.';

  @override
  String get marijuanaReferenceDay3 =>
      '대마초 금단 일정: 초기\n\n출처: PubMed Central의 \"다중 물질 남용자의 DSM-5 대마초 금단 증상의 시간 경과\", BMC Psychiatry(2013)\n\n측정된 시간 경과\n이 연구는 4주 동안 90명의 환자를 대상으로 DSM-5 대마초 금단 증상을 추적하여 증상이 어떻게 증가하고 감소하는지에 대한 가장 명확한 그림 중 하나를 생성했습니다. 전반적인 심각도는 다음 몇 주에 걸쳐 증가했다가 감소하는 곡선을 따랐습니다.\n\n조기에 정점에 도달하는 것\n가장 신체적으로 지장을 주는 증상 중 일부는 중단 후 처음 며칠 내에 최고조에 달합니다.\n• 불면증 — 1일차쯤에 최고조에 달함\n• 초조함 — 4일차쯤에 최고조에 달함\n• 우울한 기분과 신체 증상 — 5일차쯤에 최고조에 달함\n• 안절부절함 — 6일째에 최고조에 달함\n\n나중에 최고점에 도달하는 경우\n연구에 따르면 일부 증상은 첫 주 이후에 나타나고 최고조에 달합니다.\n• 생생하고 불쾌한 꿈 — 11일쯤에 최고조\n• 과민성과 분노 — 14일차에 최고조에 달함\n\n수면과 대마초\n지연되고 생생한 꿈은 REM 반동을 반영합니다. 대마초는 사용 중에 REM 수면을 억제하고, 사용을 멈춘 후에는 뇌가 과잉 보상합니다. 저자들은 이 증상이 공식적인 금단 기준에 속할 만큼 흔하다고 주장합니다.\n\n3일차의 교훈\n3일째에는 신체적 최고조에 이르게 됩니다. 불면증, 초조함, 초조함은 거의 최악에 가까워집니다. 일관되고 예측 가능한 곡선은 그 자체로 안심입니다. 이러한 증상에는 알려진 과정이 있으며 여기에서 사라집니다.';

  @override
  String get marijuanaReferenceDay7 =>
      '대마초 없는 일주일: 최악의 상황을 겪었습니다\n\n출처: PubMed Central의 \"대마초 금단 증후군: 현재 통찰력\" 약물 남용 및 재활(2017)\n\n한 주가 증후군에 걸리는 곳\n이 리뷰에서는 대마초 금단 증후군이 일반적으로 최대 약 3주까지 지속되며 가장 고통스러운 기간은 첫 번째와 세 번째 주 사이에 있음을 기록합니다. 일주일이 지나면 불면증, 식욕 부진, 초조함과 같은 초기 신체 증상이 일반적으로 최고조를 지나 완화되고 있습니다.\n\n아직 해결되지 않은 것\n이 검토에서는 초기에 나타나는 신체적 증상과 나중에 나타나는 심리적 증상을 구별합니다. 일주일 후:\n• 신체적 불편함과 식욕이 크게 개선됨\n• 아직도 많은 사람들의 수면이 방해를 받고 있으며 생생한 꿈(REM 반동)이 정점에 도달하는 경우가 많습니다.\n• 과민성과 기분은 계속 고조될 수 있습니다. 이러한 현상은 첫 2주 후반에 최고조에 달하는 경향이 있습니다.\n\n회복의 신경생물학\n이러한 변화의 근간이 되는 검토에서는 하향 조절된 CB1 수용체가 금주 후 약 4주 이내에 정상적인 기능으로 돌아간다고 지적합니다. 일주일 후, 재규제가 잘 진행되고 있습니다. 일부 증상이 지속되는 동안에도 시스템이 복구되고 있습니다.\n\n테이크아웃\n1주에 도달한다는 것은 극심한 신체적 정점이 지나갔다는 것을 의미합니다. 나머지 수면 및 기분 증상은 다음 몇 주에 걸쳐 계속 해결되는 유한한 과정이 알려진 증후군의 일부입니다.';

  @override
  String get marijuanaReferenceDay14 =>
      '대마초를 사용하지 않은 2주: 급성 금단 현상이 종료됩니다.\n\n출처: Budney, AJ 외. (2003) — 대마초 금단 시간 과정에 대한 동료 검토 연구\n\n연구 결과\n이 동료 검토 연구는 일반 사용자의 대마초 금단 증상의 시간 경과를 체계적으로 문서화했습니다. 연구 결과에 따르면 급성 금단 증후군은 첫 주 이내에 최고조에 달하고 대부분의 증상이 중단된 후 2주 이내에 대부분 해결되는 것으로 나타났습니다.\n\n2주 안에 해결되는 사항\n연구에 따르면 14일까지 연구 참가자에게서 다음 증상이 대부분 해결되었습니다.\n• 신체적 불편함 및 신체 증상\n• 식욕 장애\n• 대부분의 수면 방해\n• 극도의 과민성과 불안감\n\n2주 이상 지속될 수 있는 사항\n또한 연구에서는 일부 사용자에게서 2주 후에도 지속되는 증상을 확인했습니다.\n• 우울한 기분\n• 집중력 장애\n• 수면의 질(개선되지만)\n\n2주 표시의 중요성\n2주를 통과하는 것은 급성 금단 증후군이 대체로 완료되었음을 의미하므로 중요합니다. 이 시점 이후의 과제는 주로 대마초 중단에 대한 급성 생리학적 반응보다는 장기간의 뇌 회복 및 대마초 사용의 근본적인 이유를 관리하는 것과 관련이 있습니다.';

  @override
  String get marijuanaReferenceDay30 =>
      '대마초 없이 한 달: 기억 기능이 향상됩니다\n\n출처: Pope et al. (2001), 일반 정신의학 기록 보관소\n\n대마초와 기억: 문제\n이 연구에서는 대마초를 많이 사용하는 장기 사용자를 28일 동안 금단 확인하는 과정을 추적하고 이들의 사고 및 기억 테스트 결과를 가벼운 사용자 및 비사용자와 비교했습니다. 사용 중단 초기, 그리고 다시 1일과 7일에 과다 사용자는 단어 목록 회상에 대한 통제보다 더 나쁜 성과를 거두었습니다. 이는 평생 사용보다는 최근 약물 노출을 반영하여 소변 THC 대사 산물 수준을 추적하는 적자입니다.\n\n좋은 소식: 28일차까지 회복\n28일째에는 헤비 사용자, 라이트 사용자, 비사용자가 연구의 사고 및 기억 테스트에서 사실상 동일한 성능을 보였습니다. 또한 그 시점에서 총 평생 대마초 사용과 테스트 성능 사이에는 유의미한 관계가 없었습니다.\n\n30일 후 이것이 의미하는 바\n• 언어 학습 및 회상이 통제그룹 수준으로 돌아왔습니다.\n• 첫 주에 나타난 잔여 적자가 해결되었습니다.\n• 초기에 남은 적자는 영구적인 손상이 아닌 최근 노출과 관련이 있었습니다.\n\n증거가 보여주는 것\n28일째에는 연구의 전체 사고 및 기억 테스트에서 헤비 사용자가 라이트 사용자 및 비사용자와 거의 구별되지 않았습니다. 첫 주에 나타난 언어 학습 및 기억력 부족은 대조군 수준으로 회복되었습니다.';

  @override
  String get marijuanaReferenceDay60 =>
      '대마초를 사용하지 않은 2개월: 집중력이 향상됩니다.\n\n출처: Roten et al. (2015), 중독성 행동\n\n연구 질문\n이 청소년 대마초 중단 연구는 약 2개월에 걸쳐 소변 검사와 함께 기억력 및 사고력 테스트 점수를 추적하여 지속적으로 사용하는 사람들과 최근에 중단했거나 금주한 사람들을 비교했습니다.\n\n주요 결과\n지속적인 사용 중단은 다음과 같은 측면에서 상당한 개선과 관련이 있었습니다.\n• 종합 메모리 점수\n• 특히 언어 기억 — 가장 영향을 많이 받는 영역\n• 이동 및 반응 속도 성능\n\n두 달에\n대략 8주간의 지속적인 사용 중단으로 인해 기억력, 움직임 및 반응 속도 성능 점수가 적극적으로 사용하는 동안 앉아 있던 것보다 눈에 띄게 상승했으며 시간 단독이 아닌 확인된 비사용을 밀접하게 추적했습니다.\n\n연구 결과\n대마초 의존증이 있는 청소년 및 젊은 성인의 경우, 일관된 금욕은 대략 2개월의 치료 기간 동안 복합 기억, 언어 기억, 운동 및 반응 속도 성능에서 상당한 이득을 가져왔습니다.';

  @override
  String get marijuanaReferenceDay90 =>
      '대마초를 사용하지 않은 3개월: 기분 안정이 돌아왔습니다\n\n출처: Connor et al. (2022), 중독 — 대마초 금단에 대한 임상 검토\n\n금단 경과의 실제 모습\n이 검토에서는 대마초 금단 증상이 일반적으로 중단 후 24~48시간에 시작되어 2~6일에 최고조에 달하는 것에 대해 설명합니다. 분노, 공격성, 우울한 기분은 빠르면 일주일 만에 나타날 수 있지만 일반적으로 금주한 지 약 2주 후에 최고조에 달합니다. 특히 수면 장애는 다른 증상보다 오래 지속될 수 있습니다.\n\n3개월이 머무는 곳\n3개월이 지나면 문서화된 금단 과정을 훨씬 넘어서게 됩니다. 증상은 일반적으로 24~48시간 이내에 시작되고 2~6일 정도에 최고조에 달하며, 심지어 느린 기분과 수면 증상도 다음 주 내에 최고조에 달합니다. 90일이면 금단 증상과 수면 효과가 안정되는 데 몇 달이 걸립니다.\n\n체내칸나비노이드 시스템에 대한 참고 사항\n대마초 금단 연구에서는 또한 하향 조절된 CB1 수용체가 금주 후 약 4주 이내에 정상 기능으로 돌아오는 것으로 나타났습니다. 90일에는 수용체 회복 기간을 훨씬 넘어섰습니다.\n\n미래를 내다보며\n또한 이 검토에서는 해독 후 예후와 재발 예방에 대해 논의하고 지속적인 지원과 대처 전략이 급성 금단 기간을 훨씬 넘어서 중요하다는 점을 강조합니다.';

  @override
  String get marijuanaReferenceDay180 =>
      '대마초를 사용하지 않은 6개월: 계획 및 의사결정 회복\n\n출처: Crean, Crane & Mason(2011), 중독 의학 저널\n\n대마초 이후의 계획 및 의사결정\n이 검토에서는 장기간 사용 중단을 통해 사용 후 처음 몇 시간 동안 주의력, 의사 결정, 자제력, 작업 기억 및 언어 유창성을 조사했습니다. 6개월이 되면 단기적인 효과를 훨씬 넘어 회복 기간이 깊어집니다.\n\n연구 결과\n과도한 사용과 관련된 몇 가지 문제는 지속적인 사용 중단으로 사라지며, 일부 연구에서는 28일까지 회복되는 것으로 나타났습니다. 과도한 초기 사용 후 회복이 가장 느린 영역은 다음과 같습니다.\n• 의사 결정 및 위험 감수 - 특히 과다하고 만성적인 사용자의 경우 적자가 장기적으로 지속될 수 있는 영역으로 표시됩니다.\n• 추상적 추론 및 언어 능력 - 특히 17세 이전에 사용하기 시작한 성인의 경우 손상됨\n\n조기 발병 회복\n6개월은 이 검토에서 단기적인 효과를 훨씬 뛰어넘는 기간입니다. 지속적인 사용 중단을 통해 계획, 의사 결정 및 추론 능력이 계속 향상되므로 지속적인 사용 중단이 추가 회복을 위한 가장 강력한 경로가 됩니다.\n\n더 넓은 그림\n성인이 시작하고 가벼운 사용의 경우 전망이 더 유리합니다. 6개월이 된 많은 사람들은 더 명확한 사고, 더 안정적인 의사 결정 및 더 강한 자기 방향 감각을 보고합니다. 가장 큰 이점은 사용 중단을 유지하는 것입니다. 특히 과도하게 사용하거나 조기에 사용한 후에는 사용 중단을 유지하는 것이 좋습니다.';

  @override
  String get marijuanaReferenceDay365 =>
      '대마초 없는 1년: 뇌 구조가 회복됩니다\n\n출처: PubMed Central의 \"정기적인 대마초 사용에 따른 해마 손상, 보호 및 회복\", Translational Psychiatry(2016)\n\n대마초의 구조적 변화\n이 뇌 스캔 연구에서는 현재 사용자, 이전 사용자, 비사용자를 대상으로 기억의 중심인 뇌 영역인 해마를 조사했습니다. CBD에 노출되지 않은 현재 사용자는 대조군보다 해마가 약 11% 더 작고 뇌세포 건강 지표가 약 15% 더 낮습니다.\n\n주요 발견: 금욕을 통한 회복\n곡선 맞춤 분석은 \"보호 및 복구\" 모델을 지원했습니다. 결정적으로, 이전 사용자(평균 약 29개월 동안 금욕)는 무결성 측정에서 컨트롤을 사용하지 않는 것과 다르지 않았습니다. 저자는 THC와 관련된 기억 영역 피해가 \"사용 중단 기간을 연장하면 회복될 수 있다\"고 결론지었습니다.\n\n1년 이상에 걸친 뇌 회복\n1년 동안 대마초를 사용하지 않으면 뇌의 기억 시스템이 잘 회복됩니다. 해마 크기와 뇌 세포 건강이 정상으로 돌아가 기억력과 감정 조절을 지원합니다.\n\n회복 신호\n약 29개월 동안 사용을 중단한 이전 사용자는 연구의 해마 건강 측정에서 비사용자와 일치했습니다. 1년이 지나면 메모리 시스템은 이미 문서화된 복구 경로를 따라 정상을 향해 움직이고 있습니다.';

  @override
  String get mdmaReferenceDay1 =>
      'MDMA 이후: 컴다운\n\n출처: Meyer(2013), \"3,4-메틸렌디옥시메탐페타민(MDMA): 현재 관점\", 약물 남용 및 재활\n\n당신이 기분이 좋지 않은 이유\nMDMA는 세로토닌(약간의 도파민 포함)을 대량으로 방출함으로써 작동합니다. 그 후에는 뇌의 세로토닌이 일시적으로 고갈됩니다. 이 리뷰에서는 연구원들이 사용 후 2~5일 동안 초보자와 숙련된 사용자 모두를 대상으로 측정한 기분 저하(소위 \"주중 우울증\")에 대해 설명합니다.\n\n무엇이 도움이 되는가\n• 수분 공급 및 영양가 있는 음식\n• 수면\n• 인내심 - 하락은 영구적인 상태가 아닌 고갈입니다.\n\n1회 사용 후의 증상은 의존성 관련 금단 증상과 다르며, 동일한 리뷰에서는 갈망과 관련이 있지만 심각한 신체적 증상은 없다고 설명합니다.';

  @override
  String get mdmaReferenceDay3 =>
      'MDMA 후 며칠\n\n출처: Meyer(2013), \"3,4-메틸렌디옥시메탐페타민(MDMA): 현재 관점\", 약물 남용 및 재활\n\n주중 블루스\n이는 이 리뷰가 \"주중 우울증\"에 대해 논의할 때 설명하는 대략적인 창입니다. 즉, 초보자와 숙련된 사용자 모두 사용 후 2~5일에 측정된 기분 저하로, 장기적인 변화보다는 단기적인 세로토닌 고갈과 관련이 있습니다.\n\n개선 사항\n• 일반적으로 기분은 현재 가장 낮은 수준에서 상승합니다.\n• 에너지 회수\n• 수면이 정상화되기 시작합니다.';

  @override
  String get mdmaReferenceDay7 =>
      'MDMA 1주일 후\n\n출처: Meyer(2013), \"3,4-메틸렌디옥시메탐페타민(MDMA): 현재 관점\", 약물 남용 및 재활\n\n주중 블루스를 지나\n대부분의 사람들의 경우, 이 리뷰에서 급성 우울증과 관련된 2~5일의 기간이 1주일 지나므로 기분이 정상으로 돌아올 것입니다. 리뷰에서는 과도하게 또는 반복적으로 약물을 사용하는 사람들의 경우 갈망이 의존성 패턴의 일부로 지속될 수 있지만 이것이 심각한 신체적 금단 증상을 수반하는 것으로 설명하지는 않는다고 지적합니다.\n\n도움을 구해야 할 때\n기분이 좋지 않거나, 불안하거나, 수면 문제가 일주일 동안 지속된다면, 이는 단순한 침체 이상의 것일 수 있습니다. 전문가와 상담하는 것이 좋습니다.';

  @override
  String get mdmaReferenceDay14 =>
      'MDMA 2주 쉬기\n\n출처: Meyer(2013), \"3,4-메틸렌디옥시메탐페타민(MDMA): 현재 관점\", 약물 남용 및 재활\n\n복구 일정\n일회용 컴다운의 경우 이 리뷰에 기록된 2~5일 딥보다 2주가 훨씬 지났으므로 기분, 수면 및 집중력이 꾸준해야 합니다. 더 많이 또는 반복적으로 사용한 후에는 회복이 계속되고 금욕 영상 연구에 따르면 지속적인 금욕으로 세로토닌 재활용 능력이 증가하는 것으로 나타났습니다.\n\n이것이 당신에게 의미하는 것\n가끔 사용했다면 최악의 상황을 겪었을 가능성이 높습니다. 빈도가 높거나 심했다면 인내심을 가지십시오. 세로토닌 신호의 완전한 회복은 2주보다 더 긴 과정이며 다음 단계에서 다루겠습니다.';

  @override
  String get mdmaReferenceDay30 =>
      'MDMA 한 달 할인\n\n출처: PubMed의 \"금단 MDMA 사용자의 세로토닌 수송체 가용성, 신경인지 기능 및 이들의 상관 관계\"\n\n한 달이 머무는 곳\n급격한 하락과 철수는 훨씬 뒤에 있으며, 기분과 사고와 기억은 더욱 안정적입니다. 영상 연구에 따르면 MDMA는 세로토닌을 처리하는 뇌의 능력을 감소시키며, 이 능력은 지속적인 금욕을 통해 회복되는 것으로 나타났습니다.\n\n회복 신호\n동일한 연구에서는 지속적인 금욕으로 세로토닌 재활용 능력이 회복되는 것으로 나타났습니다. 기분과 세로토닌 기능이 먼저 개선되는 반면, 기억은 자체 회복 일정에 따라 지속됩니다. 지속적인 금욕은 두 가지 모두를 지원합니다.';

  @override
  String get mdmaReferenceDay90 =>
      'MDMA 3개월 할인\n\n출처: PubMed의 \"금단 MDMA 사용자의 세로토닌 수송체 가용성, 신경인지 기능 및 이들의 상관 관계\"\n\n지속적인 복구\n지속적인 금욕을 통해 뇌의 세로토닌 시스템은 특히 뇌의 더 깊은 영역에서 계속 회복됩니다. 기분과 수면은 일반적으로 이 시점에서 안정적입니다.\n\n회복 신호\n지속적인 금욕은 뇌 영역 전반에 걸쳐 세로토닌 수송체의 지속적인 회복을 촉진하는 동시에 기분과 수면은 안정적으로 유지되고 사고와 기억의 회복이 계속됩니다.';

  @override
  String get mdmaReferenceDay365 =>
      'MDMA 1년 할인\n\n출처: PubMed의 \"금단 MDMA 사용자의 세로토닌 수송체 가용성, 신경인지 기능 및 이들의 상관 관계\"\n\n1년\n1년간의 금욕으로 인해 뇌의 세로토닌 처리가 상당히 회복되었으며 기분이 안정되었습니다.\n\n회복 신호\n1년 동안 금욕하면 세로토닌 시스템의 회복 기간이 길어집니다. 영상 연구에 따르면 금욕에 따라 세로토닌 재활용 능력이 증가하여 상당한 세로토닌 회복이 이 단계에서 가장 명확한 생물학적 신호가 되는 것으로 나타났습니다.';

  @override
  String get methReferenceDay1 =>
      '메스암페타민 금단: 첫 24시간\n\n출처: McGregor et al., \"The nature, time course and severity of methamphetamine withdrawal,\" Addiction (2005), PubMed\n\n크래시\n메스암페타민은 많은 양의 도파민 방출을 일으킵니다. 사용을 중단하면 이 체계가 고갈된 상태가 됩니다. 이 연구는 금단 첫 3주 동안 증상을 매일 추적했고, 마지막 사용 후 24시간 이내에 전체 증상 강도가 가장 높다는 사실을 확인했습니다. 이른바 ‘크래시’로, 극심한 자극 상태에서 신체적·정신적 탈진으로 급격히 전환되는 시기입니다.\n\n첫날 증상\n연구에서 이 시기에 가장 두드러진 것으로 기록된 증상은 다음과 같습니다:\n• 극심한 피로와 수면 증가(과다수면)\n• 식욕 증가(메스암페타민은 식욕을 강하게 억제합니다)\n• 우울한 기분과 즐거움의 감소\n• 강한 사용 욕구\n• 불안과 과민함\n\n신체적 안전\n메스암페타민 금단 자체는 일반적으로 생명을 위협하지 않지만, 연구에서 측정한 우울 관련 증상은 초기에 심할 수 있고 자살 사고가 동반될 수 있습니다. 특히 사용량이 많았던 경우에는 의료적 관찰을 강하게 권합니다.\n\n점차 완화됩니다\n고무적인 점은 증상 강도가 시작 시점에 가장 높고 이후 감소한다는 것입니다. 24시간의 정점 이후 증상은 며칠에 걸쳐 꾸준히 줄어듭니다. 가장 힘든 지점은 시작 부분입니다.';

  @override
  String get methReferenceDay3 =>
      '메스암페타민 금단: 3일차 — 아직 급성기\n\n출처: McGregor et al., \"The nature, time course and severity of methamphetamine withdrawal,\" Addiction (2005), PubMed\n\n정점에서 내려오는 시기\n이 연구에서는 전체 금단 증상 강도가 첫 24시간 안에 정점에 이른 뒤 약 7–10일의 급성기 동안 대체로 선형적으로 감소했습니다. 3일차에는 가장 높은 지점을 지났지만 여전히 급성기에 있으며, 전체 추세가 내려가더라도 증상은 뚜렷할 수 있습니다.\n\n3일차 증상\n연구에서 추적했고 이 시기에도 중요한 증상은 다음과 같습니다:\n• 우울감과 즐거움의 감소\n• 강한 사용 욕구\n• 집중하거나 명확하게 생각하기 어려움\n• 불면과 과다수면이 번갈아 나타나는 수면 장애\n• 지속되는 피로\n\n왜 이렇게 느껴질까\n메스암페타민 금단의 강도는 도파민 체계가 크게 흔들린 정도를 반영합니다. 연구에서 측정한 우울 관련 증상은 초기 며칠 동안 특히 두드러졌습니다. 중요한 점은 전체 금단 강도가 “금단 첫 주가 끝날 무렵 대조군 수준에 가까워졌다”는 결과입니다.\n\n이 시기는 지나갑니다\n가장 힘든 구간은 첫 며칠이며, 데이터는 이후 꾸준한 감소를 보여줍니다. 이를 영구적인 상태가 아니라 뇌와 신경계에 나타나는 일시적인 변화로 이해하는 것이 버티는 데 도움이 될 수 있습니다.';

  @override
  String get methReferenceDay7 =>
      '메스암페타민 없이 1주: 급성기 종료\n\n출처: McGregor et al., \"The nature, time course and severity of methamphetamine withdrawal,\" Addiction (2005), PubMed\n\n급성기의 끝\n연구에서 가장 고무적인 결과 중 하나입니다. 우울 관련 증상을 포함한 전체 금단 강도가 “금단 첫 주가 끝날 무렵 대조군 수준에 가까워졌다”고 보고되어 급성기의 끝을 보여줍니다. 가장 가파른 구간은 이미 지났습니다.\n\n두 단계의 금단\n연구진은 메스암페타민 금단을 다음과 같이 설명했습니다:\n• 약 7–10일의 급성기: 초기 정점에서 증상 강도가 꾸준히 감소\n• 이후 최소 2주 이상 이어지는 아급성기: 더 가볍지만 남아 있는 증상\n\n7일차에 남을 수 있는 것\n아급성기에 들어서면 급성 크래시보다 심리적 어려움이 더 중심이 됩니다:\n• 낮은 기분, 다만 첫 며칠보다는 크게 호전\n• 단서나 상황에 반응해 나타나는 사용 욕구\n• 아직 회복 중인 집중력과 기억력\n• 계속 안정되는 수면\n\n신체 회복 진행 중\n급성기가 지나면 식욕이 돌아오고 에너지가 서서히 늘어납니다. 몸은 메스암페타민이 수면, 영양, 심혈관계에 준 영향에서 계속 회복합니다.';

  @override
  String get methReferenceDay30 =>
      '메스암페타민 없이 한 달: 기분은 안정되고 갈망은 남아 있음\n\n출처: Zorick et al., \"Withdrawal symptoms in abstinent methamphetamine-dependent subjects,\" Addiction (2010), PubMed Central\n\n첫 5주 추적\n이 연구는 메스암페타민 의존 참가자 가운데 최대 5주 동안 사용하지 않은 사람들을 추적하고 건강한 대조군과 비교했습니다. 덕분에 한 달 시점의 상태를 비교적 명확하게 볼 수 있습니다.\n\n한 달 동안 좋아진 점\n• 우울 증상은 “금단 첫 2주 동안 안정적인 낮은 수준으로 크게 감소”했고, 4주가 끝날 무렵에는 아직 통계적으로 완전히 같지는 않았지만 건강한 대조군 수준에 가까워졌습니다\n• 정신과적 증상과 정신병성 양상의 증상은 둘째 주 말까지 낮은 수준에 도달했습니다\n따라서 30일 시점에는 초기 금단의 심한 우울 증상이 상당 부분 가라앉았습니다. 실제로 측정된 개선입니다.\n\n아직 남는 것\n한 가지 증상은 더 오래 지속됐습니다. 사용 욕구는 “금단 5주 동안 감소한 수준으로 계속 남아 있었습니다.” 첫 주보다 약해졌지만 사라지지는 않았기 때문에 한 달 시점에도 지속적인 지원이 중요합니다.\n\n핵심\n한 달이 되면 기분과 관련된 뇌 기능이 충분히 회복되어 초기 금단보다 일상이 훨씬 나아질 수 있습니다. 남아 있는 갈망은 이 단계에서 흔한 현상이며 실패를 뜻하지 않습니다.';

  @override
  String get methReferenceDay90 =>
      '메스암페타민 없이 3개월: 회복은 이미 시작됨 — 서두르지 마세요\n\n출처: Volkow et al., \"Loss of Dopamine Transporters in Methamphetamine Abusers Recovers with Protracted Abstinence,\" Journal of Neuroscience (2001)\n\n이 연구에 대하여\n이 중요한 뇌 영상 연구는 메스암페타민 사용자를 약 3개월 금단 시점과 약 14개월 시점에 다시 검사해 도파민 체계의 회복을 살폈습니다.\n\n3개월의 위치\n3개월이면 초기 금단은 오래전에 지나고 더 깊은 도파민 회복이 진행 중입니다. 같은 연구는 이후 보상·운동 영역에서 도파민을 재흡수하는 단백질이 12–17개월 금단 후 약 16%–19% 증가했다고 보고했습니다.\n\n당신에게 의미하는 것\n90일이면 급성 금단은 한참 뒤에 있고 기분과 수면도 좋아질 수 있으며 치료 참여도 더 생산적으로 느껴질 수 있습니다. 하지만 도파민 체계의 깊은 회복은 다음 해에 걸쳐 이어지는 더 긴 과정입니다. 3개월에도 동기나 즐거움이 무디게 느껴진다면 이 연구의 회복 경로와 맞으며 실패를 뜻하지 않습니다.\n\n기다릴 가치가 있는 이유\n같은 연구에서 금단 기간이 길수록 측정된 도파민 수송체 회복도 더 컸습니다. 3개월은 기반이며 그 이후에도 회복은 이어질 수 있습니다.';

  @override
  String get methReferenceDay180 =>
      '메스암페타민 없이 6개월: 심장은 회복할 수 있음\n\n출처: \"Stopping Drug Abuse Can Reverse Related Heart Damage,\" American College of Cardiology (2017), JACC: Heart Failure 연구 보도\n\n메스암페타민과 심장\n메스암페타민은 심장 독성이 매우 강한 약물 중 하나입니다. 심한 고혈압과 부정맥을 일으킬 수 있고, 시간이 지나면 심장 근육이 약해져 심부전으로 이어질 수 있는 메스암페타민 관련 심근병증을 유발할 수 있습니다.\n\n연구 결과\nAmerican College of Cardiology는 심장 펌프 기능이 크게 떨어진 메스암페타민 관련 심근병증 환자들을 보고했습니다. 핵심적인 희망적 결과는 사용 중단이 “약물이 심장에 가한 손상을 되돌리고 심장 기능을 개선할 수 있다”는 것이었습니다. 사용을 중단한 환자들은 계속 사용한 환자보다 결과가 훨씬 좋았고, 연구진은 조기에 발견하면 “심근병증의 추가 악화를 막을 수 있다”고 강조했습니다.\n\n6개월이 중요한 이유\n메스암페타민을 사용하지 않는 매달은 심장에 가해지는 반복적인 독성 자극을 없애고 심장 근육에 회복할 시간을 줍니다. 6개월이면 심혈관계가 이런 손상에서 상당히 긴 휴식 기간을 갖게 됩니다. 연구에서 개선이 관찰된 조건과 맞닿아 있습니다.\n\n회복 신호\n근거가 보여주는 핵심은 분명합니다. 메스암페타민 사용을 중단하면 관련 심장 손상이 일부 되돌아가고 심장 기능이 개선될 수 있습니다. 반복적인 자극제 노출 없이 6개월을 보내면 심장에는 의미 있는 회복 시간이 생깁니다.';

  @override
  String get methReferenceDay365 =>
      '메스암페타민 없이 1년: 측정 가능한 뇌 회복\n\n출처: Wang et al., \"Partial Recovery of Brain Metabolism in Methamphetamine Abusers After Protracted Abstinence,\" American Journal of Psychiatry (2004), PubMed\n\n영상에서 보이는 변화\n이 뇌 영상 연구는 금단 초기의 메스암페타민 사용자와 12–17개월 후의 상태를 다시 검사했습니다. 일부 영역은 다른 영역보다 빠르게 회복했지만 전반적으로 실제 뇌 회복이 관찰됐습니다.\n\n좋은 소식: 깊은 뇌 영역과 사고 기능의 회복\n뇌 깊은 곳의 중계 중심인 시상은 장기간 금단 후 에너지를 더 정상적으로 사용하기 시작했습니다. 이 회복은 더 나은 운동 기능과 언어 기억 수행과 함께 나타났기 때문에 영상 변화가 실제 기능 개선과 연결됐습니다.\n\n보상 회로는 더 천천히 회복\n12–17개월에는 깊은 뇌 영역의 회복이 뚜렷했고 더 나은 운동 기능과 언어 기억이 동반됐습니다. 보상과 동기 체계도 계속 강화돼 1년 시점의 전반적 그림은 사고와 기억의 큰 회복을 보여줍니다.\n\n1년 시점의 의미\n1년이면 초기 회복 때보다 훨씬 더 잘 생각하고 기억할 수 있습니다. 명확하고 측정 가능한 변화입니다. 동기나 즐거움을 느끼는 능력이 아직 뒤처지는 때가 있더라도 개인의 실패를 뜻하지 않습니다. 연구에서는 보상 회로가 더 천천히 회복하고 일부 차이가 1년을 넘어서도 남을 수 있음을 보여줬습니다.';

  @override
  String get methReferenceDay420 =>
      '메스암페타민 없이 14개월: 도파민 지표 회복\n\n출처: Volkow et al., \"Loss of Dopamine Transporters in Methamphetamine Abusers Recovers with Protracted Abstinence,\" Journal of Neuroscience (2001)\n\n핵심 결과\n이 중요한 뇌 영상 연구는 금단 초기와 약 12–17개월 후의 메스암페타민 사용자를 비교했습니다. 보상·운동 영역에서 도파민을 재흡수하는 단백질이 약 16%–19% 증가했고 건강한 대조군과 더 이상 통계적으로 유의한 차이가 없는 수준에 도달했습니다. 더 긴 금단 기간은 더 큰 회복과 관련됐습니다.\n\nDAT가 중요한 이유\n이 단백질은 분비된 도파민을 다시 흡수합니다. 메스암페타민은 이 단백질을 감소시켜 도파민 체계의 조절을 흐트러뜨립니다. 약 14개월에 다시 증가한 것은 실제로 측정 가능한 회복 신호입니다.\n\n회복 신호\n12–17개월 후 보상·운동 영역의 도파민 재흡수 단백질은 약 16%–19% 증가해 건강한 대조군 수준에 도달했습니다. 도파민 체계가 측정 가능하게 정상 방향으로 회복되는 동안 사고, 기억, 운동 기능도 계속 좋아질 수 있습니다.\n\n14개월 시점의 의미\n도파민 체계가 정상 상태에 가까워지는 모습이 실제 측정으로 확인됩니다. 충분히 낙관할 이유가 있습니다. 다만 기억, 동기, 미세운동 조절 같은 완전한 기능 회복은 영상 변화보다 늦을 수 있고 금단을 유지하는 동안 계속 좋아질 수 있습니다.';

  @override
  String get methReferenceDay730 =>
      '메스암페타민 없이 2년: 사고와 기분이 계속 좋아짐\n\n출처: Iudicello et al., \"Longer Term Improvement in Neurocognitive Functioning and Affective Distress Among Methamphetamine Users Who Achieve Stable Abstinence,\" Journal of Clinical and Experimental Neuropsychology (2010), PubMed Central\n\n1년을 넘어 이어지는 회복\n이 연구는 메스암페타민 사용자를 약 13개월 추적해 안정적으로 사용을 중단한 그룹, 계속 사용한 그룹, 건강한 대조군을 비교했습니다. 안정적인 금단은 전반적인 인지 기능을 향상시키고 정서적 고통을 줄였으며 개선은 1년을 넘어 이어졌습니다.\n\n좋아진 부분\n• 안정적으로 사용을 중단한 그룹의 전반적 인지 기능은 건강한 대조군 수준에 도달했지만 계속 사용한 그룹은 유의한 손상이 남았습니다\n• 가장 큰 개선은 처리 속도와 운동 능력에서 나타났고, 시작 시 손상이 큰 사람일수록 두드러졌습니다\n• 기분도 뚜렷하게 좋아졌습니다. 우울과 전반적 기분에서 유의한 개선을 보인 것은 안정적으로 사용을 중단한 그룹이었습니다\n\n회복 신호\n안정적으로 사용을 중단한 그룹은 전반적 인지 기능에서 건강한 대조군 수준에 도달했고 정서적 고통도 더 적게 보고했습니다. 언어 학습, 작업 기억, 계획, 집중력은 첫해 이후에도 계속 좋아질 수 있어 회복 추세가 두 번째 해로 이어질 수 있습니다.\n\n2년 시점\n근거가 전하는 메시지는 명확합니다. 장기간 사용을 중단하는 것은 첫해를 훨씬 지나서도 더 선명한 사고, 더 나은 기분, 꾸준한 기능 개선과 연결됩니다. 일부 영역은 회복에 더 오래 걸릴 수 있습니다.';

  @override
  String get methMilestone1095Title => '3년 - 회복이 이어집니다';

  @override
  String get methMilestone1095Description =>
      '메스암페타민 없이 3년을 보냈다는 것은 몇 주가 아니라 몇 년으로 측정되는 지속적인 변화입니다. 성취의 핵심은 그 지속성 자체입니다. 회복 습관과 지지 기반이 뿌리내릴 시간을 한 해 더 쌓았습니다.';

  @override
  String get methReferenceDay1095 =>
      '3년 - 회복이 이어집니다\n\n출처: Cao et al., \"Magnitude and Abstinence Trajectories of Neurocognitive Deficits in Methamphetamine Use Disorder: A Systematic Review and Meta-analysis,\" Journal of Addiction Medicine (2026), PubMed\n\n2026년 체계적 문헌고찰 및 메타분석은 9,045명이 참여한 68개 독립 연구를 종합했습니다. 사용 중단 기간에 따른 변화 분석은 최대 280일까지의 자료만 다뤘고, 영역별 근거 확실성은 매우 낮게 평가됐습니다. 따라서 이 근거로 특정 기념일을 생물학적 회복의 완료 시점으로 정할 수 없습니다.\n\n메스암페타민 없이 3년을 보냈다는 것은 몇 주가 아니라 몇 년으로 측정되는 지속적인 변화입니다. 성취의 핵심은 그 지속성 자체입니다. 회복 습관과 지지 기반이 뿌리내릴 시간을 한 해 더 쌓았습니다.';

  @override
  String get methMilestone1460Title => '4년 - 단단한 기반';

  @override
  String get methMilestone1460Description =>
      '4년은 변화가 단단히 이어진 시간입니다. 연구는 4년에 뇌 회복이 끝난다는 기준을 제시하지 않습니다. 이 이정표는 지금까지 만든 기반을 또 한 해 지켜낸 것을 기념합니다.';

  @override
  String get methReferenceDay1460 =>
      '4년 - 단단한 기반\n\n출처: Cao et al., \"Magnitude and Abstinence Trajectories of Neurocognitive Deficits in Methamphetamine Use Disorder: A Systematic Review and Meta-analysis,\" Journal of Addiction Medicine (2026), PubMed\n\n2026년 체계적 문헌고찰 및 메타분석은 9,045명이 참여한 68개 독립 연구를 종합했습니다. 사용 중단 기간에 따른 변화 분석은 최대 280일까지의 자료만 다뤘고, 영역별 근거 확실성은 매우 낮게 평가됐습니다. 따라서 이 근거로 특정 기념일을 생물학적 회복의 완료 시점으로 정할 수 없습니다.\n\n4년은 변화가 단단히 이어진 시간입니다. 연구는 4년에 뇌 회복이 끝난다는 기준을 제시하지 않습니다. 이 이정표는 지금까지 만든 기반을 또 한 해 지켜낸 것을 기념합니다.';

  @override
  String get methMilestone1825Title => '5년 - 지속되는 변화';

  @override
  String get methMilestone1825Description =>
      '메스암페타민 없이 5년은 큰 장기 이정표입니다. 과학은 5년에 생물학적 회복이 끝난다고 약속할 수 없습니다. 분명한 것은 5년 동안 지속한 변화 자체가 축하할 가치가 있다는 점입니다.';

  @override
  String get methReferenceDay1825 =>
      '5년 - 지속되는 변화\n\n출처: Cao et al., \"Magnitude and Abstinence Trajectories of Neurocognitive Deficits in Methamphetamine Use Disorder: A Systematic Review and Meta-analysis,\" Journal of Addiction Medicine (2026), PubMed\n\n2026년 체계적 문헌고찰 및 메타분석은 9,045명이 참여한 68개 독립 연구를 종합했습니다. 사용 중단 기간에 따른 변화 분석은 최대 280일까지의 자료만 다뤘고, 영역별 근거 확실성은 매우 낮게 평가됐습니다. 따라서 이 근거로 특정 기념일을 생물학적 회복의 완료 시점으로 정할 수 없습니다.\n\n메스암페타민 없이 5년은 큰 장기 이정표입니다. 과학은 5년에 생물학적 회복이 끝난다고 약속할 수 없습니다. 분명한 것은 5년 동안 지속한 변화 자체가 축하할 가치가 있다는 점입니다.';

  @override
  String get nitrousOxideReferenceDay1 =>
      '첫날: 가스는 사라졌지만 B12는 확인해야 합니다\n\n출처: Knuf & Maani, “Nitrous Oxide,” StatPearls (NCBI Bookshelf)\n\n얼마나 빨리 빠져나가나\n아산화질소는 2~5분 안에 빠르게 작용하며, 흡입을 중단하면 몸에서도 빠르게 제거됩니다. 오늘쯤이면 가스 자체는 체내에 남아 있지 않습니다.\n\n진짜 위험은 남아 있는 가스가 아닙니다\n중단 후 중요한 것은 반복 노출로 이미 생겼을 수 있는 영향입니다. 아산화질소는 비타민 B12에 의존하는 효소인 메티오닌 합성효소를 비활성화합니다. StatPearls는 직업적이든 기분전환 목적이든 반복 노출이 거대적아구성 빈혈과 뇌·신경 기능 장애를 일으킬 수 있고, 드물게는 척수 변성을 초래할 수 있다고 설명합니다.\n\n많이 또는 자주 사용했다면\n아산화질소는 오피오이드나 알코올처럼 신체적 금단 증후군을 일으키는 것으로 보고되지 않았습니다. 첫날의 핵심은 몸이 약물을 요구하는 것이 아니라, 다음 몇 단계에서 다룰 B12 관련 증상에 주의를 기울이고 증상이 생기면 검사를 받는 것입니다.';

  @override
  String get nitrousOxideReferenceDay3 =>
      '72시간: 신체적 금단은 없지만 신경 증상은 주의하세요\n\n출처: Knuf & Maani, StatPearls; Tikaria et al. (2026), Cureus\n\n오피오이드나 알코올과 달리 아산화질소는 신체적 금단 증후군을 일으키는 것으로 보고되지 않았습니다. 이 시기의 충동은 습관과 갈망에서 비롯되며, 몸이 정상적으로 기능하려고 약물을 요구하는 것은 아닙니다.\n\n이런 증상을 살펴보세요\n기분전환용 아산화질소 사용 1,809건을 검토한 체계적 문헌고찰(Tikaria et al., 2026)에서는 저림이나 무감각(감각 이상) 같은 뇌·신경 증상이 B12 관련 손상의 가장 흔한 징후였습니다. 표준 혈액검사가 정상으로 보여도 이런 증상이 나타나는 경우가 있었고, 보행 문제와 근력 저하도 보고됐습니다.\n\n이런 증상이 있다면\n의료진의 평가를 받으세요. 같은 문헌고찰에서는 헤모글로빈과 혈청 B12 같은 표준 혈액검사가 영향을 받은 환자의 상당수를 놓쳤습니다. 메틸말론산(MMA)과 호모시스테인은 더 민감한 지표이므로 아산화질소 사용 사실을 알리고 구체적으로 검사를 요청하는 것이 좋습니다.';

  @override
  String get nitrousOxideReferenceDay7 =>
      '1주: 많이 사용했다면 검사를 받으세요\n\n출처: Tikaria et al. (2026), “The Toxic Legacy of Recreational Nitrous Oxide Use,” Cureus\n\n근거가 보여주는 것\n이 체계적 문헌고찰에서는 아산화질소로 인한 비타민 B12 결핍이 흔히 ‘기능적’이라는 점을 확인했습니다. 실제 뇌·신경 손상이 있어도 영향을 받은 환자의 약 절반에서 혈청 B12 수치가 정상처럼 보였습니다. 반면 호모시스테인과 MMA는 검사 대상자의 각각 84%, 73%에서 비정상이었고 더 신뢰할 만한 지표였습니다.\n\n무엇을 할 수 있나\n사용량이 많거나 빈번했다면, 사용을 멈춘 지 일주일쯤 됐을 때 의사를 만나 표준 B12 검사뿐 아니라 호모시스테인과 MMA 검사를 구체적으로 요청하는 것이 합리적입니다. 특히 저림, 무감각, 균형 문제, 설명하기 어려운 근력 저하가 있다면 더 중요합니다.\n\n아산화질소 사용을 중단하고 비타민 B12 치료를 받은 뒤 신경학적 호전은 흔히 보고됩니다. 대규모 임상 사례군에서는 추적된 환자의 대부분에서 부분적 또는 완전한 호전이 나타났고, 회복은 치료 후 첫 몇 달 동안 계속될 수 있었습니다.';

  @override
  String get nitrousOxideReferenceDay14 =>
      '2주: 뇌·신경 증상은 계속 확인해야 합니다\n\n출처: Tikaria et al. (2026), Cureus; Knuf & Maani, StatPearls\n\n보고된 내용\nTikaria et al.이 검토한 사례 보고와 사례군에서는 아산화질소 관련 신경 손상이 감각 저하, 보행 실조, 때로는 걷기에 영향을 주는 근력 저하로 나타났습니다. 이런 소견은 다른 신경계 질환과 비슷할 수 있어 아산화질소 사용 사실을 의료진에게 알리지 않으면 놓칠 수 있습니다.\n\n회복 시점에 대해 알려진 것\n두 자료 모두 사용 중단과 결핍 치료 뒤 회복에 보통 얼마나 걸리는지 제시하지 않습니다. 사례 보고에서는 완전 회복부터 지속되는 후유증까지 결과가 매우 다양하며, 진단 전에 어느 정도 손상이 생겼는지가 큰 영향을 줍니다. 문헌 전반에서 일관된 점은 치료가 빠를수록 결과가 더 좋다는 것입니다.\n\n아직 검사를 받지 않았다면\n증상이 없어도 2주쯤에는 혈액검사를 고려할 만합니다. 혈청 B12만 보는 것보다 호모시스테인과 MMA를 함께 확인하는 것이 특히 중요합니다.';

  @override
  String get nitrousOxideReferenceDay30 =>
      '1개월: 신체적 의존이 아니라 습관과 갈망\n\n출처: Knuf & Maani, “Nitrous Oxide,” StatPearls (NCBI Bookshelf)\n\n현재 상태\nStatPearls는 아산화질소가 신체적 의존 증후군을 일으킨다고 설명하지 않습니다. 한 달이 지난 뒤에도 남는 충동은 몸이 약물 부재에 적응하는 과정이라기보다 습관, 사회적 상황, 지루함과 관련될 가능성이 큽니다.\n\nB12 확인\nB12 결핍을 검사하고 치료받았다면 한 달은 수치와 증상이 치료에 반응했는지 의사와 확인하기에 적절한 시점입니다. 많이 사용했는데 아직 검사를 받지 않았다면 지금이라도 문의할 가치가 있습니다.\n\n보호되는 것\n사용하지 않는 매달은 메티오닌 합성효소 비활성화와 그에 따른 뇌·신경 위험을 추가로 늘리지 않는 한 달입니다.';

  @override
  String get nitrousOxideReferenceDay90 =>
      '3개월: 아직 안 했다면 다시 점검할 때\n\n출처: Tikaria et al. (2026), “The Toxic Legacy of Recreational Nitrous Oxide Use,” Cureus\n\n알려진 것과 알려지지 않은 것\n근거는 통제된 회복 연구가 아니라 사례 보고와 사례군에 기반하므로, 특히 3개월 시점에 증상이 어떻게 호전되는지 보여주는 신뢰할 만한 표준 일정은 없습니다. 결과는 크게 다릅니다. 가볍고 일찍 발견된 결핍은 완전히 회복되는 경우가 있지만, 진단이 늦거나 신경 손상이 심하면 후유증이 남을 수 있습니다.\n\n지금 할 수 있는 일\n뇌·신경 증상이 있었는데 추적 혈액검사나 전문의 진료를 받지 않았다면, 사용 중단 3개월은 이를 확인하기에 합리적인 시점입니다. 치료 후 호전 중이라면 담당 의사와 그 추세가 이어지는지 점검할 수 있습니다.\n\n계속 사용하지 않는 것이 가장 중요합니다\n문헌고찰이 분명히 보여주는 한 가지는 지속적인 노출이 계속 B12를 비활성화하고 위험을 더한다는 점입니다. 사용하지 않는 것이 가장 큰 보호 요인입니다.';

  @override
  String get nitrousOxideReferenceDay365 =>
      '1년: 가장 좋은 보호는 계속 사용하지 않는 것\n\n출처: Knuf & Maani, StatPearls; Tikaria et al. (2026), Cureus\n\n근거가 실제로 말해주는 범위\n두 자료 모두 특정 회복 시점을 약속하지 않습니다. 아산화질소와 B12 결핍에 관한 문헌은 장기 추적 연구보다 개별 사례 보고에 거의 전적으로 의존합니다. 확실히 알려진 기전은 아산화질소가 사용할 때마다 비타민 B12를 비활성화하고, 사용을 중단하면 그 지속적인 노출이 사라진다는 점입니다.\n\n결핍 관련 증상이 있었다면\n사례 보고는 완전 회복부터 지속되는 신경 증상까지 매우 다양한 결과를 보여주며, 손상의 정도와 치료 시작 시점이 큰 영향을 줍니다. 1년이 지나도 증상이 남아 있다면 신경과 진료를 계속할 이유가 됩니다. 아무것도 더 할 수 없다는 뜻은 아니며, 신경 회복은 오랜 기간 이어질 수 있습니다.\n\n확실한 점\n아산화질소 없이 보낸 1년은 메티오닌 합성효소가 추가로 비활성화되지 않은 1년입니다. 두 자료가 뒷받침하는 가장 확실한 부분입니다.';

  @override
  String get opioidReferenceDay1 =>
      '아편유사제 금단: 1일차\n\n출처: \"폐쇄 환경에서의 금단 관리 및 약물 의존 치료에 대한 임상 지침\", 세계보건기구(2009), NCBI 책장\n\n⚠ 안전 참고 사항\n아편유사제 금단은 건강한 개인에게 치명적인 경우는 거의 없으나, 심각한 신체적 고통을 초래하고 재발 위험이 높습니다. 사용 중단 기간 후 재발하는 것은 내성이 급격히 떨어지기 때문에 특히 위험합니다. 사용 중단 전과 동일한 용량을 사용하면 치명적인 과다 복용이 발생할 수 있습니다. 의학적 감독과 오피오이드 작용제 치료가 강력히 권장됩니다.\n\n인출이 시작되는 경우\nWHO 철회 시간표는 오피오이드 유형별로 시기를 설정합니다.\n• 단기 작용 아편유사제(헤로인, 옥시코돈): 마지막 사용 후 8~24시간에 발병하고 지속 기간은 4~10일입니다.\n• 지속성 아편유사제(메타돈): 개시 시간은 12~48시간, 지속 시간은 10~20일입니다.\n\n첫날 증상\nWHO 지침에는 오피오이드 금단의 초기 특징이 나열되어 있습니다.\n• 불안과 동요\n• 근육 경련 및 통증\n• 눈과 코에서 분비물이 나옵니다.\n• 하품과 땀흘림\n• 불면증, 뜨겁고 차가운 홍조를 동반함\n• 조기 메스꺼움\n\n기분이 나쁜 이유\n오피오이드 시스템은 통증, 스트레스, 정서적 안녕 및 기본적인 편안함을 조절합니다. 장기간 아편유사제를 사용하면 신체 자체의 아편유사제 생산(엔돌핀)이 억제됩니다. 오피오이드를 제거하면 신체는 정상적인 편안함 시스템 없이 남겨지며, 억압의 깊이를 반영하는 수준의 통증, 불안 및 괴로움을 경험하게 됩니다. WHO 지침에서는 하루에 2~3리터의 물을 마시고 매일 3~4회 모니터링하는 등의 지지요법을 권장합니다.';

  @override
  String get opioidReferenceDay7 =>
      '오피오이드 일주일 쉬기: 최고 증상 감소\n\n출처: \"폐쇄 환경에서의 금단 관리 및 약물 의존 치료에 대한 임상 지침\", 세계보건기구(2009), NCBI 책장\n\n정점과 하락\nWHO 시간표에 따르면 단기간 작용하는 오피오이드 금단 기간은 4~10일이며, 증상은 조기에 발생했다가 해당 기간에 걸쳐 완화됩니다. 첫 주가 끝날 때까지:\n• 구토, 설사가 대부분 해소됨\n• 근육경련이 덜 심함\n• 신체적 고통이 의미 있게 감소됩니다.\n\n7일차에 남은 것\n급성 신체 증상이 호전되는 동안에도 다음과 같은 심각한 문제가 지속됩니다.\n• 불면증 — 수면 방해는 가장 지속적인 아편유사제 금단 증상 중 하나입니다.\n• 우울한 기분과 감정의 무미건조함\n• 피로와 약점\n• 갈망\n• 불안\n\n급성후 금단\n첫 번째 금단 기간 이후에는 수면 문제, 기분 변화, 갈망의 물결이 몇 주 또는 몇 달 동안 지속될 수 있습니다. 이 긴 복구 단계에서는 지속적인 지원이 가장 중요합니다.\n\n오피오이드 작용제 치료\nWHO 지침에서는 메타돈과 부프레노르핀을 금단 증상의 심각도를 줄이고 회복을 지원하는 효과적인 치료법으로 설명합니다. 이러한 약물은 또한 오피오이드 사용 장애로 인한 사망률을 감소시키며, 성공적인 장기 회복에 성공한 많은 사람들은 초기 회복 단계 전반에 걸쳐 이 약물을 사용합니다.';

  @override
  String get opioidReferenceDay14 =>
      '오피오이드 2주 쉬기: 수면 패턴이 개선되기 시작함\n\n출처: 오피오이드 및 수면에 관한 동료 검토 약리학 연구\n\n오피오이드-수면 연결\n이 연구 논문은 오피오이드 사용과 수면 방해 사이의 양방향 관계를 조사합니다. 연구 결과에 따르면 오피오이드가 여러 메커니즘을 통해 정상적인 수면 구조를 심각하게 방해한다는 사실이 입증되었습니다.\n• 서파(깊은) 수면 억제\n• REM 수면 방해\n• 수면 장애 호흡 유발(중추성 수면 무호흡증)\n• 일주기 리듬 조절을 방해합니다.\n\n악순환\n연구는 문제의 양방향 특성을 강조합니다. 오피오이드 사용은 수면을 방해하고, 수면 부족은 통증 민감도와 갈망 강도를 증가시켜 오피오이드 사용을 더욱 촉진합니다. 오피오이드 의존성을 깨는 것은 또한 이러한 수면 방해 주기를 깨는 것을 의미합니다.\n\n2주 동안 잠을 잔다\n아편유사제 금단 14일이 지나면 수면이 정상화되기 시작합니다.\n• 중추성 수면 무호흡증(있는 경우)은 며칠 내에 해결됩니다.\n• 깊은 서파수면이 회복되기 시작했습니다.\n• REM 수면이 정상 비율로 돌아오고 있습니다.\n• 수면 시작이 점점 더 확실해지고 있습니다.\n\n수면은 2주차에도 많은 사람들에게 여전히 중요한 과제로 남아 있지만, 궤도는 확실히 개선되고 있습니다. 더 나은 수면은 직접적으로 기분을 개선하고 갈망을 줄이며 회복에 필요한 명확한 사고를 지원합니다.';

  @override
  String get opioidReferenceDay30 =>
      '오피오이드 한 달 사용 중단: 사고와 기억이 회복되기 시작합니다.\n\n출처: 메이요클리닉\n\n오피오이드 사용 장애 이해\nMayo Clinic은 오피오이드가 뇌와 신체 전체의 수용체에 부착되어 통증 완화, 행복감 및 졸음을 유발한다고 설명합니다. 반복적으로 사용하면 뇌의 반응이 덜 강해지고 자체적으로 생성되는 오피오이드 유사 화학물질도 줄어듭니다. 그것은 신체적 의존성을 만듭니다.\n\n한 달의 사고와 기억\n30일째에는 사고와 기억의 의미 있는 회복이 이루어졌습니다. 최악의 뇌 안개가 걷히고 계획과 자제력을 담당하는 뇌의 앞부분이 회복되고 있습니다.\n• 의사결정이 개선되고 있습니다.\n• 작업 기억이 회복되고 있습니다.\n• 처리 속도 증가\n• 더욱 안정적인 집중력\n\n엔돌핀 시스템\n한 달이 지나면 뇌의 천연 엔돌핀 시스템이 활발하게 회복됩니다. 즉, 자체적으로 오피오이드 유사 화학물질을 더 많이 생산하고 다시 더 정상적으로 반응하게 됩니다. 회복이 계속됨에 따라 감정적 평탄함과 낮은 통증 내성이 계속 개선됩니다.\n\n재발 예방\n메이요 클리닉(Mayo Clinic)은 한 달 동안 오피오이드 사용을 중단했다고 해서 재발 위험이 사라진 것이 아니라 여전히 높은 상태로 유지된다는 점을 강조합니다. 내성이 크게 감소했습니다. 이는 이전 용량을 사용한 재발이 심각한 과다복용 위험을 수반한다는 것을 의미합니다.';

  @override
  String get opioidReferenceDay60 =>
      '오피오이드 복용을 2개월 중단하면 뇌의 스트레스 회로가 안정되기 시작합니다.\n\n출처: \"오피오이드 금단 및 장기간의 오피오이드 금단에서 확장된 편도체의 신경가소성\", Frontiers in Pharmacology(2023)\n\n부정적인 감정은 어디서 오는가\n이 리뷰에서는 장기간의 오피오이드 사용이 뇌의 스트레스와 공포 회로를 어떻게 변화시키는지 보여줍니다. 금단 증상이 나타나면 보상 회로의 도파민 신호 전달이 저하되는 동안 이러한 회로가 과도하게 활성화됩니다. 이러한 조합은 초기 회복 과정에서 불안, 기분 저하, 갈망을 설명하는 데 도움이 됩니다.\n\n두 달이 안도감을 주는 이유\n결정적으로, 검토 문서에서는 이러한 변경 사항 중 일부가 되돌릴 수 있음을 문서화했습니다. 동물 모델에서 측두근 껍질의 척추 밀도 손실은 \'지속적이지만 가역적인 감소\'로 설명되며, 몇 주에 걸쳐 약물 투여 전 값으로 돌아갑니다. 이러한 스트레스 및 보상 회로가 재조정됨에 따라 조기 회복 감정적 혼란의 기계적 기반이 완화됩니다. 이는 많은 사람들이 약 2개월 정도 보고하는 감소된 반응성 및 안정된 기분과 일치합니다.\n\n회복 신호\n이 문헌에 기록된 가역적 척추 밀도 및 스트레스 회로 변화는 실제 생물학적 회복 과정을 보여줍니다. 의존이라는 부정적인 감정 상태를 구동하는 회로는 금욕 중에 약물 사용 전 상태로 되돌아갑니다.';

  @override
  String get opioidReferenceDay90 =>
      '오피오이드 3개월 사용 중단: 회복되기 시작하는 보상 화학\n\n출처: PubMed Central의 \"사용 중단 기간의 약물 사용 장애가 있는 개인의 구조적 및 기능적 뇌 회복: 종단적 신경 영상 연구 검토\", 약물 및 알코올 의존(2022)\n\n도파민과 오피오이드\n오피오이드는 뇌의 보상 시스템에서 도파민 방출을 유도합니다. 장기간 사용하면 시스템이 고갈됩니다. 한 뇌 스캔 연구에서 도파민을 재활용하는 단백질은 처음에 건강한 수준보다 약 30% 낮았습니다. 이는 오피오이드 사용 장애와 조기 회복에서 나타나는 즐거움의 상실을 설명하는 데 도움이 됩니다.\n\n회복은 점진적이다\n이 검토에서는 사용 중단 기간에 동일한 사람들을 다시 조사한 종단적 연구를 수집했습니다. 도파민-수송체 결핍은 사용 중단 6~12개월 동안 약 20% 정도 회복되었으며, 조기 금단 시 나타난 일부 전두엽 회백질 및 백질 이상은 약 한 달 후에는 더 이상 감지되지 않았습니다. 3개월이 되면 회복 곡선의 초기 단계입니다. 보상 시스템과 전두엽 시스템이 눈에 띄게 개선되고 있지만 아직 끝나지 않았습니다.\n\n사람들이 경험하는 것\n이러한 회로가 회복되면서 약 90일이 지나면 많은 사람들이 다음을 발견합니다.\n• 활동, 음식, 인간관계를 더욱 진정으로 즐기기\n• 조기 회복에 비해 갈망 감소\n• 더 명확해진 사고와 더 나은 의사결정\n\n회복 신호\n종방향 인간 영상에서는 6~12개월의 사용 중단 기간 동안 도파민 수송체 가용성이 증가하는 반면, 전두엽 회색질 및 백색질 이상은 훨씬 일찍 정상화되기 시작하는 것으로 나타났습니다. 90일이 되면 측정 가능한 뇌 회복이 이미 확립되었습니다.';

  @override
  String get opioidReferenceDay180 =>
      '오피오이드 6개월 사용 중단: 면역 체계가 회복되기 시작합니다\n\n출처: \"오피오이드 내성 및 금단이 면역체계에 미치는 영향\", Journal of Neuroimmune Pharmacology(2006), PubMed\n\n오피오이드와 면역체계\n이 검토에서는 장기간 오피오이드 사용이 여러 가지 방법으로 면역체계를 약화시키는 것으로 나타났습니다.\n• 면역 세포(T 세포, NK 세포, 대식세포)에 대한 직접적인 오피오이드 작용\n• 면역 신호를 전달하는 화학 물질을 방해합니다.\n• 시상하부-뇌하수체-부신(HPA) 축의 장애\n• 감염에 대한 민감성 증가\n\n회복 신호\n장기간의 아편유사제는 면역 체계의 여러 부분을 억제합니다. 오피오이드를 6개월 중단하면 지속적인 억제가 반년 동안 사라지고 면역 기능이 적극적으로 정상을 향해 재건됩니다.\n\n6개월의 의미\n오피오이드 없이 6개월간 면역 세포, 면역 신호 전달 및 신체의 스트레스 시스템이 정상으로 회복될 수 있는 지속 시간을 제공합니다.\n\n이것이 여전히 중요한 이유\n이는 HIV 및 C형 간염과 같은 추가 감염 위험에 직면한 아편유사제를 주사한 사람들에게 특히 관련이 있습니다. 아편유사제를 제거하고, 영양을 개선하고, 오피오이드 사용 중단을 유지하면 면역체계가 계속 회복하는 데 필요한 조건을 제공합니다.';

  @override
  String get opioidReferenceDay365 =>
      '오피오이드 1년 중단: 뇌 구조 및 화학 회복\n\n출처: PubMed Central의 \"사용 중단 기간의 약물 사용 장애가 있는 개인의 구조적 및 기능적 뇌 회복: 종단적 신경 영상 연구 검토\", 약물 및 알코올 의존(2022)\n\n휴먼 이미징이 보여주는 것\n이 검토에서는 오피오이드 사용 장애가 있는 동일한 사람들을 사용 중단 기간에 두 번 이상 스캔한 연구를 수집했습니다. 연구 결과는 일관되게 회복 방향을 가리키고 있습니다.\n• 보상 및 운동 영역의 도파민 재활용 단백질은 처음에는 정상보다 약 30% 낮았으나 아편유사제 사용을 중단한 후 6~12개월 동안 약 20% 증가했습니다.\n• 조기 금단 시 나타나는 전두엽 회백질 이상은 사용 중단 약 한 달 후에는 더 이상 감지되지 않습니다.\n• 백질(전두엽 및 띠) 및 휴면 상태의 전두엽 활동도 첫 달 이내에 다시 정상화되기 시작했습니다.\n\n1년이 머무는 곳\n12개월이 되면 이 연구에서 측정한 가장 긴 기간에 도달하거나 그 기간을 넘게 됩니다. 도파민 시스템은 회복하는 데 가장 많은 시간이 걸렸으며 자제력과 판단을 지원하는 전두엽 회로는 수개월 동안 개선되었습니다. 이는 사람들이 1년에 묘사하는 더 명확한 사고, 더 약한 갈망, 더 안정된 기분에 대한 생물학적 대응입니다.\n\n회복 신호\n1년이 지나면 인간의 영상 신호는 회복 지향적입니다. 도파민 수송체 가용성은 6~12개월 동안 증가한 반면 전두엽의 구조적 및 기능적 이상은 정상화되는 데 수개월이 걸렸습니다.';

  @override
  String get opioidReferenceDay730 =>
      '오피오이드 2년 사용 중단: 안정적인 기반\n\n출처: \"오피오이드 사용 장애 치료\", 질병 통제 예방 센터(CDC)\n\n만성 질환, 잘 관리됨\nCDC는 오피오이드 사용 장애를 \'누구에게나 영향을 미칠 수 있는 만성 질환\', 즉 \'도덕적 결함이 아닌 의학적 상태\'라고 설명합니다. 2년간의 지속적인 회복에 도달했다는 것은 가장 취약한 기간 중 하나를 통해 해당 상태를 성공적으로 관리해 왔다는 것을 의미합니다.\n\nCDC가 효과가 있다고 말하는 것\nCDC 지침은 장기적으로 회복을 안정적으로 유지하는 치료법에 중점을 두고 있습니다.\n• 오피오이드 사용 장애에 대한 약물(부프레노르핀, 메타돈, 날트렉손)은 특히 효과적이라고 합니다.\n• 약물 치료와 행동 치료 및 상담을 병행합니다.\n• 개인에 맞춰 다양한 기간 동안 지속되는 치료\nCDC는 이러한 약물이 \'뇌 화학을 정상화\'하고 갈망을 완화하는 데 도움이 된다고 지적합니다. 활성 중독에서 납치된 느낌이 들었던 화학이 다시 작용합니다.\n\n안전 유지\nCDC는 회복 중인 사람들에게 다시 사용하거나 과다복용할 위험에 대해 의사에게 문의하고 날록손을 항상 준비할 것을 촉구합니다. 사용 중단 중에는 내성이 떨어지기 때문에 오랫동안 오피오이드를 다시 사용하는 것은 특히 위험합니다. 이것이 여러분이 구축한 것을 보호하는 것의 일부라는 것을 알기 때문입니다.\n\n2년 후\nCDC는 회복이 결승선이 아닌 장기적인 과정인 경우가 많다는 점을 분명히 밝혔습니다. 2년은 여정의 끝이 아닙니다. 이는 안정적이고 건전한 기초이며 귀하가 사용하는 접근 방식이 효과가 있다는 강력한 증거입니다.';

  @override
