      '3년 - 이어지는 회복\n\n출처: 미국 질병통제예방센터(CDC), 「오피오이드 사용장애 치료」\n\nCDC는 오피오이드 사용장애를 치료 가능한 만성 질환으로 설명합니다. 치료 형태와 기간은 사람마다 다를 수 있으며 약물치료도 근거가 있는 선택지입니다.\n\nCDC는 3년을 생물학적 회복의 끝으로 정하지 않습니다. 이 이정표는 1,095일 동안 이어온 회복을 축하합니다.';

  @override
