  @override
  String get pornographyReferenceDay1 =>
      '첫째 날: 통제권 되찾기\n\n출처: Kraus 등, ICD-11의 강박성 성적 행동 장애, 세계 정신의학(2018).\n\n임상적으로 중요한 문제는 음란물 사용 자체가 아닙니다. 강박성 성적 행동 장애는 반복적인 성적 행동을 통제하는 데 어려움을 겪는 패턴이 심각한 고통이나 장애를 야기하는 경우를 중심으로 정의됩니다. 문제가 있는 음란물 사용은 더 광범위한 문제를 나타내는 한 가지일 수 있습니다.\n\n그것은 첫날을 신비롭게 여기기보다는 구체적으로 만듭니다. 당신은 통제할 수 없다고 판단한 행동을 중단했습니다. 하루를 완료했다고 해서 뇌와 신경이 재설정되는 것은 아니지만 언제 충동이 나타나는지, 어떤 상황이 충동을 유발하는지, 대신 무엇을 할 수 있는지에 대한 최초의 실제 관찰을 제공합니다.\n\n귀하의 사용이 고통스럽거나 손상되거나 통제하기 어렵지 않은 경우 임상 CSBD 프레임워크가 귀하에게 적용되지 않을 수 있습니다. 이러한 이정표는 문제가 있거나 강박적인 사용을 의도적으로 변경하는 사람들을 대상으로 합니다.';

  @override
  String get pornographyReferenceDay3 =>
      '셋째 날: 충동이 어떤 모습인지 알아보세요\n\n출처: Lewczuk et al., 강박적인 성적 행동 장애 및 문제가 있는 음란물 사용과 관련된 금단 및 관용, Journal of Behavioral Addictions(2022).\n\n사전 등록된 전국 대표 폴란드 성인 1,541명 표본에서, 자가 보고된 금단 증상이 강할수록 CSBD 및 음란물 사용 심각도가 더 높은 것과 관련이 있었습니다. 음란물 사용에 문제가 있는 참가자들 사이에서 일반적으로 보고된 경험에는 멈추기 어려운 성적인 생각, 통제하기 어려운 욕망, 흥분 증가, 과민성, 기분 변화 및 수면 문제가 포함되었습니다.\n\n안절부절 못함, 거슬리는 성적인 생각, 강한 충동, 과민 반응은 보다 심각한 문제적 사용을 하는 사람들에게서 기록됩니다. 3일 쯤에 나타나면 실제 금단 증상과 유사한 패턴으로 간주하고 유발 요인을 관리하세요.\n\n실제로 어떤 충동이 일어나고 있는지, 그 전에 무엇이 있었는지, 어떤 반응이 도움이 되었는지 적어보세요. 신비한 뇌 사건으로 취급되기보다는 방아쇠의 이름이 지정되면 회복이 더 쉬워집니다.';

  @override
  String get pornographyReferenceDay7 =>
      '일주일: 무작위 금욕 연구에서 발견된 사실\n\n출처: 일반 포르노 사용자의 금단 관련 증상에 대한 7일 포르노 금욕 기간의 영향, 성행위 기록 보관소(2023).\n\n연구자들은 176명의 일반 음란물 사용자를 무작위로 선정하여 7일간 금욕을 시도하거나 평소대로 계속하도록 했습니다. 전체 표본에서 금욕은 갈망, 부정적인 기분 또는 금단 증상의 전반적인 증가를 가져오지 않았습니다.\n\n탐색적 분석에 따르면 연구 전 높은 문제 사용 점수와 일일 음란물 사용을 결합한 사람들 사이에서 갈망이 증가한 것으로 나타났습니다. 그 결과는 복제가 필요하지만 유용합니다. 문제가 많은 사용자에게는 어려운 첫 주가 현실이 될 수 있지만 보편적인 음란물 금단 증후군은 이 시험에서 지원되지 않습니다.\n\n일주일을 버텼다면 이제 일반적인 인터넷 타임라인이 제공할 수 있는 것보다 자신의 패턴에 대한 더 나은 증거를 갖게 됩니다.';

  @override
  String get pornographyReferenceDay14 =>
      '2주: 실제로 중요한 트리거 매핑\n\n출처: 문제가 있는 음란물 사용의 생물심리사회적 결정 요인: 체계적 검토(2023).\n\n이 검토에서는 66개의 연구를 종합하여 문제가 있는 음란물 사용이 하나의 단순한 도파민 메커니즘이 아닌 여러 요인의 혼합과 관련되어 있음을 발견했습니다. 반복적으로 확인된 심리적, 사회적 요인에는 갈망, 스트레스, 회피, 외로움, 자존감, 부정적인 신념 및 대처 스타일이 포함되었습니다.\n\n2주는 주중, 주말, 지루함, 스트레스, 개인 정보 보호, 장치 및 이전 행동의 신호가 될 수 있는 기타 상황에 반복적으로 노출됩니다. 해당 데이터를 사용하세요. 스트레스가 유발인 경우 스트레스 반응을 설계하십시오. 외로움이 원인이라면 접촉을 추가하세요. 쉬운 접근이 원인이라면 환경을 바꿔보세요.\n\n증거는 문제가 있는 사용의 동인에 대한 작업을 뒷받침합니다. 모든 사람이 동일한 생물학적 카운트다운을 따르는 척할 필요는 없습니다.';

  @override
  String get pornographyReferenceDay30 =>
      '한 달: 단순한 빈도수 계산보다 제어가 더 중요합니다\n\n출처: Böthe et al., 성기능 문제는 빈번한 음란물 사용 및/또는 문제가 있는 음란물 사용과 관련이 있습니까?, 중독성 행동(2021).\n\n14,581명의 성인으로 구성된 커뮤니티 표본에서 문제가 있는 음란물 사용은 남성과 여성 모두에서 성기능 문제와 중간 정도의 긍정적인 연관성을 보였습니다. 음란물 사용 빈도 자체는 이러한 문제와 약한 부정적 연관성을 보여주었습니다.\n\n그 구별이 중요합니다. 증거는 모든 음란물 사용자가 시청 빈도만으로 성기능에 손상을 입는다고 말하는 것을 뒷받침하지 않습니다. 임상적으로 더 관련성이 높은 목표는 통제력 상실과 해당 패턴을 둘러싼 문제입니다.\n\n한 달이 지나면, 시작했을 때와 지금의 삶을 비교해 보세요: 몰두, 잃어버린 시간, 멈출 수 있는 능력, 성기능, 관계 갈등, 고통. 이러한 변화는 신화적인 30일 두뇌 재설정을 기다리는 것보다 더 중요합니다.';

  @override
  String get pornographyReferenceDay90 =>
      '3개월: 지속 가능한 변화가 가능합니다\n\n출처: Crosby & Twohig, 문제가 있는 인터넷 음란물 사용에 대한 수용 및 헌신 치료: 무작위 시험, 행동 치료(2016).\n\n이 소규모 무작위 시험에서는 12개 세션으로 구성된 ACT 프로그램과 28명의 성인 남성을 대상으로 대기자 명단을 비교했습니다. 음란물 시청은 치료 종료 시 ACT 그룹에서 훨씬 더 많이 감소했으며 3개월 후속 조치에서도 상당한 감소가 유지되었습니다.\n\n이 연구는 90일 금욕만으로는 동일한 결과가 발생한다는 것을 증명하지 않았으며, 표본도 작고 인구통계학적으로도 좁았습니다. 그것이 보여주는 것은 중요합니다. 문제가 있는 음란물 사용은 수정 가능하며 구조화된 기술은 즉각적인 치료 기간 이후에도 지속되는 변화를 가져올 수 있습니다.\n\n귀하의 진전이 여전히 대부분의 의지에 달려 있다면 3개월은 주변 시스템을 강화하는 좋은 시점입니다. 즉, 트리거 계획, 행동하지 않고 충동 수용, 환경적 마찰, 책임, 필요할 때 치료 등이 있습니다.';

  @override
  String get pornographyReferenceDay180 =>
      '6개월: 장기적인 증상 통제가 가능합니다.\n\n출처: Hallberg 등, 남성의 성과다 장애에 대한 그룹 관리 인지 행동 치료에 대한 무작위 대조 연구, 성의학 저널(2019).\n\n통제할 수 없는 성적 행동을 보이는 남성 137명을 대상으로 7주간의 그룹 CBT를 실시한 결과 대기자 명단에 오른 경우보다 성과민 증상과 성적 강박성이 크게 감소했으며 정신과적 건강도 향상되었습니다. 치료 효과는 3개월 및 6개월 추적 기간 모두에서 안정적으로 유지되었습니다.\n\n이 연구는 음란물 금욕만을 다루기보다는 성과잉 장애를 더 광범위하게 다루었으므로 모든 사람이 6개월이 지나면 생물학적으로 회복된다는 주장으로 전환되어서는 안 됩니다. 이는 더 강력하고 더 유용한 진술을 뒷받침합니다. 강박적인 성적 행동의 지속적인 개선은 이 기간 동안 안정적으로 유지될 수 있습니다.\n\n따라서 6개월은 유지 관리 기간입니다. 날짜를 해체 허가로 간주하는 대신 제어를 더 쉽게 만드는 루틴을 유지하십시오.';

  @override
  String get pornographyReferenceDay365 =>
      '1년: 지속적인 행동 변화에 대한 증거\n\n출처: 성과다증에 대한 수용 기반 치료의 1년 후속 효과(2026).\n\n1년의 추적 조사에서, 이 수용 기반 치료 연구의 참가자들은 치료 전 수준의 성욕 과잉으로 돌아가지 않았습니다. 저자는 이번 연구 결과를 시간이 지남에 따라 진행되는 과정 중 갈망에 대한 인지된 통제와 함께 지속적이고 임상적으로 의미 있는 이점에 대한 예비 증거라고 설명했습니다.\n\n이는 치료 추적 관찰 증거이지 1년 간의 뇌 재설정 증거가 아닙니다. 어쨌든 의미 있는 주장이 더 좋습니다. 임상적으로 관련된 통제는 초기 개입이 끝나자마자 사라지는 것이 아니라 1년 동안 지속될 수 있습니다.\n\n1년 동안 직접 관리한 변경 사항은 대규모 개인 데이터 세트이기도 합니다. 현재 통제, 고통, 기능, 관계 및 시간 사용을 시작한 곳과 비교하십시오. 이것이 임상적으로 중요한 결과입니다.';

  @override
  String get pornographyReferenceDay730 =>
      '2년: 안정된 통제\n\n출처: Ince 외(2026)의 CSBD 및 문제적 음란물 이용 종설.\n\n연구는 이러한 문제를 통제력, 고통, 기능, 맥락이 얽힌 복잡하고 개인차가 큰 문제로 봅니다. 2년에 생물학적 회복이 일괄적으로 완료된다는 기준은 제시하지 않습니다.\n\n따라서 2년은 행동 변화가 오래 유지되었다는 뜻입니다. 지속적인 통제력과 기능 향상 자체가 의미 있는 결과입니다.';

  @override
  String get pornographyReferenceDay1095 =>
      '3년: 단단해진 변화\n\n출처: Ince 외(2026)의 CSBD 및 문제적 음란물 이용 종설.\n\n현재 근거는 3년이라는 생물학적 종점을 정하지 않습니다. 임상적으로는 통제력, 고통, 기능 저하, 맥락, 일상 기능을 계속 살핍니다.\n\n3년은 변화의 지속성을 보여줍니다. 일상과 상황이 바뀌어도 유지된 변화는 계속 지킬 가치가 있습니다.';

  @override
  String get pornographyReferenceDay1460 =>
      '4년: 오래가는 변화\n\n출처: Ince 외(2026)의 CSBD 및 문제적 음란물 이용 종설.\n\n근거는 개인차와 맥락을 강조하며 4년에 모두의 생물학적 회복이 완료된다는 보편적 기준을 지지하지 않습니다.\n\n그래도 4년은 깊은 유지 상태를 보여줄 수 있습니다. 이전 패턴이 선택을 지배하지 않고 관계나 기능을 방해하지 않는다면 그것은 실질적인 장기 성과입니다.';

  @override
  String get pornographyReferenceDay1825 =>
      '5년: 장기적인 통제가 중요한 결과입니다\n\n출처: Compulsive sexual behavior disorder and problematic pornography use: a comprehensive interdisciplinary expert-informed review (2026).\n\n현대의 종설은 CSBD와 문제적 음란물 이용을 통제력, 고통, 기능, 맥락, 개인차가 함께 작용하는 복잡한 문제로 봅니다. 5년이 되면 뇌와 신경계가 “재설정”된다는 검증된 기준은 없습니다.\n\n하지만 5년은 빈 이정표가 아닙니다. 자신이 선택한 행동 방향을 1,825일 동안 유지해 온 것입니다. 임상적 문제의 핵심이 고통이나 기능 저하를 동반한 지속적인 통제 상실인 만큼, 여러 해 동안 통제력을 유지하고 기능을 회복한 것 자체가 의미 있는 결과입니다.\n\n이 단계에서 중요한 질문은 뇌가 가상의 “재배선 비율”에 도달했는지가 아닙니다. 예전 패턴이 여전히 선택을 지배하거나 원하는 삶을 방해하는지가 중요합니다. 그렇지 않다면 그것은 분명한 장기적 성과입니다.';

  @override
  String get smokingReferenceDay1 =>
      '첫째 날: 혜택은 지금 시작됩니다\n\n출처: NHS Better Health\n\n혜택은 며칠이 아니라 몇 분 안에 시작됩니다. 담배 연기가 멈추는 순간부터 몸은 정상 상태로 돌아가기 시작합니다.\n\n오늘 일어나는 변화\n• 20분: 맥박이 정상으로 돌아오기 시작합니다\n• 8시간: 혈액 속 일산화탄소가 절반으로 줄고 산소 수치가 회복되기 시작합니다\n• 48시간: 일산화탄소가 비흡연자 수준으로 내려갑니다\n\n일산화탄소는 산소보다 적혈구에 더 강하게 결합해 혈액에서 산소를 밀어냅니다. 모든 장기가 필요한 양보다 적은 산소를 받고 있었습니다. 이 변화는 이틀 안에 되돌아가기 시작합니다.\n\n금단은 첫날부터 시작됩니다\n• 흡연 욕구 — 한 번의 욕구는 보통 3~5분 지속됩니다\n• 짜증과 집중력 저하\n• 식욕 증가\n\n이 증상은 일시적이며 관리할 수 있습니다. NHS Better Health는 앱과 약사 상담을 포함한 무료 지원을 제공합니다.';

  @override
  String get smokingReferenceDay3 =>
      '3일차: 니코틴 금단의 정점\n\n출처: McLaughlin, Dani 및 De Biasi\n\n72시간이 지나면 니코틴은 몸에서 빠져나갑니다. 흡연 기간 동안 뇌에는 니코틴 수용체가 더 많이 생겼고, 이제 이 수용체의 자극이 줄어 금단 증후군이 나타납니다.\n\n가장 강한 증상\n• 흡연 욕구 — 지금 가장 강하게 느껴질 수 있습니다\n• 짜증, 좌절감, 초조함\n• 집중하기 어려움\n• 불안\n• 두통\n• 식욕 증가\n• 기침(기도가 스스로 청소되는 과정 — 좋은 신호)\n\n가장 힘든 날로 느껴질 수 있습니다. 이후에는 뇌가 다시 적응하면서 증상이 점차 완화됩니다.\n\n니코틴 대체요법(NRT), 바레니클린, 부프로피온은 이 단계의 금단 증상 강도를 크게 줄일 수 있습니다.';

  @override
  String get smokingReferenceDay7 =>
      '일주일: 미각과 후각이 돌아옵니다.\n\n출처: NHS Better Health\n\n일주일간 금연을 달성하는 것은 장기적인 성공을 강력하게 예측하는 지표입니다. 첫 주를 금연한 사람들은 영원히 금연할 가능성이 훨씬 더 높습니다.\n\n복구된 내용\n• 음식 맛이 더 맛있습니다.\n• 냄새가 더 생생해졌습니다.\n• 호흡이 더 쉬워집니다. 기도가 깨끗해집니다.\n• 순환이 개선되고 있습니다\n• 피부에 수분이 더 잘 공급됩니다.\n\n흡연은 미각과 후각 수용체를 직접적으로 손상시킵니다. 중단 후 며칠 내에 회복되기 시작합니다.\n\n급성 니코틴 금단 현상이 완화되고 있습니다. 육체적 갈망은 더 짧고 덜 빈번합니다. 유발 요인에 따른 갈망이 여전히 존재할 수 있지만 최악의 신체적 긴급 상황은 이미 지나갔습니다.';

  @override
  String get smokingReferenceDay14 =>
      '2주: 순환이 개선됩니다\n\n출처: NHS Better Health\n\n중단 후 2~12주 이내에 혈액 순환이 개선됩니다. 니코틴은 담배를 피울 때마다 혈관을 좁힙니다. 그렇지 않으면 혈관이 이완되고 혈액이 더 자유롭게 흐릅니다.\n\n이것이 의미하는 바\n• 손, 발, 말초 조직으로의 혈류가 개선됩니다.\n• 많은 사람들이 손과 발이 따뜻해지는 것을 느낍니다.\n• 걷기와 계단 오르기가 더 쉬워지기 시작합니다.\n\n첫날에 이미 혈액에서 일산화탄소가 제거되고 이제 혈액 순환이 개선되어 산소가 근육에 더 효과적으로 도달합니다.\n\n기도를 감싸고 있는 섬모가 회복되어 축적된 점액을 밀어냅니다. 평소보다 기침이 더 많이 난다면 이는 후퇴가 아니라 회복의 신호입니다.';

  @override
  String get smokingReferenceDay30 =>
      '한 달: 폐 기능 상승\n\n출처: NHS Better Health\n\n호흡이 더 쉬워지고 폐 기능이 향상되어 3~9개월 동안 최대 10%까지 향상됩니다. 한 달이 지나면 회복 곡선에 진입하게 됩니다.\n\n폐에서 무슨 일이 일어나고 있나요?\n• 섬모가 다시 자라서 점액을 더 효과적으로 제거하고 있습니다.\n• 기도 염증이 가라앉고 있습니다.\n• 지속적으로 흡연하는 사람의 기침이 잦아듭니다.\n• 운동 내성이 향상되고 있습니다.\n\n폐 기능이 증가하면 기침, 천명음 및 호흡 문제가 개선됩니다. 한 달은 회복 곡선에서 의미 있는 지점입니다.';

  @override
  String get smokingReferenceDay90 =>
      '3개월: 심장마비 위험 감소\n\n출처: PMC — 흡연 및 금연의 심혈관 효과(2024)\n\n흡연은 다양한 방식으로 심장과 동맥을 손상시킵니다. 즉, 동맥 플라크 형성을 가속화하고 혈액 응고를 촉진하며 혈압을 높이고 동맥 내벽을 손상시킵니다. 응고 촉진, 혈전 촉진 효과는 중단 후 며칠 내에 역전되며, 본 리뷰에서는 중단 후 첫 1년 이내에 심장마비와 뇌졸중이 눈에 띄게 감소했다고 보고합니다.\n\n지금까지 개선된 점\n• 혈액 응고 인자가 정상화되고 있습니다.\n• 혈압과 심박수가 안정되고 있습니다.\n• 급성 심혈관계 질환 위험이 조기에 급격히 감소하는 추세가 이미 진행 중입니다.\n\n느리게 작용하는 이점(수년간의 동맥 플라크 축적을 역전시키는 것)은 더 오래 걸리며 이후 단계에서 다룹니다. 담배를 피우지 않는 달마다 회복량이 늘어납니다.';

  @override
  String get smokingReferenceDay180 =>
      '6개월: 폐 면역세포가 다시 힘을 냅니다\n\n출처: Smoke-free period and recovery of alveolar immune-cell function (PubMed)\n\n흡연은 폐 깊은 곳에서 세균을 삼키고 죽이는 면역세포인 폐포 대식세포의 기능을 억제할 수 있습니다.\n\n연구에서 측정한 것\n연구진은 전신마취를 받은 비흡연자 15명, 현재 흡연자 15명, 그리고 금연 기간이 2개월, 3~5개월, 6~12개월인 과거 흡연자 41명을 비교했습니다.\n\n구체적인 회복 신호\n마취 중 폐포 대식세포의 식균작용과 세균 살해 활동 감소는 현재 흡연자와 금연 2개월군에서 비흡연자보다 1.5~3배 더 컸습니다. 금연 3~12개월군의 항균 반응은 2개월군보다 비흡연자 패턴에 더 가까웠습니다.\n\n염증 신호는 더 느린 속도로 회복되어 사이토카인 반응 차이가 6개월까지 관찰됐습니다. 6개월은 폐 면역 회복의 분명한 이정표이며 회복은 계속됩니다.';

  @override
  String get smokingReferenceDay365 =>
      '1년: 심장마비 위험이 급격히 감소\n\n출처: PMC — 흡연 중단 및 뇌졸중 결과; CDC, 금연의 이점\n\n흡연은 동맥 플라크 축적을 촉진하고 혈액 응고를 증가시키며 혈압을 높이고 뇌혈관을 손상시켜 뇌졸중 위험을 대략 두 배로 증가시킵니다. CDC의 금연 혜택 타임라인에 따르면 1~2년 내에 심장마비 위험이 급격히 감소합니다. 귀하는 그 기간의 최전선에 있습니다.\n\n복구 일정\n전체 뇌졸중 위험 정상화에는 더 오랜 시간이 걸립니다. 인용된 뇌졸중 연구에서는 금연자를 중앙값 거의 5년 동안 추적한 결과 계속 흡연하는 사람보다 뇌졸중 발생률이 유의미하게 낮은 것으로 나타났습니다. CDC 데이터에 따르면 관상동맥 심장 질환 위험은 3~6년에 절반으로 줄어들고 뇌졸중 위험은 5~10년에 걸쳐 감소합니다.\n\n1년은 여전히 ​​진정한 의학적 이정표입니다. 장기적인 심혈관 및 암 혜택이 수년간 계속 축적되더라도 급성 위험 감소의 가장 가파른 부분은 뒤에 있습니다.';

  @override
  String get smokingReferenceDay730 =>
      '2년: 심혈관 이점이 계속됩니다\n\n출처: CDC, 금연의 건강상 이점\n\nCDC에 따르면 심근경색 위험은 금연 후 1~2년 사이에 크게 감소합니다. 2년은 그 근거가 제시하는 범위의 끝이지, 특정 하루에 갑자기 바뀐다는 뜻은 아닙니다.\n\n장기적인 흐름도 이어집니다. 관상동맥질환의 추가 위험은 계속 낮아지고 3~6년 사이에 절반으로 감소합니다. 정확한 생물학적 날짜를 만들지 않아도 금연 2년은 충분히 큰 성과입니다.';

  @override
  String get smokingReferenceDay1095 =>
      '3년: 심장 개선 구간이 시작됩니다\n\n출처: CDC, 금연의 건강상 이점\n\nCDC는 관상동맥질환의 추가 위험이 절반으로 줄어드는 시기를 금연 후 3~6년으로 제시합니다. 3년은 그 범위의 시작입니다.\n\n근거는 하나의 기간을 설명하며 즉각적인 경계선을 뜻하지 않습니다. 3년이 되면 장기적인 심혈관 위험 감소가 이미 뚜렷하게 진행 중이며 이점은 계속 쌓입니다.';

  @override
  String get smokingReferenceDay1460 =>
      '4년: 심장 건강 이점이 계속됩니다\n\n출처: CDC, 금연의 건강상 이점\n\n금연 4년은 CDC가 제시한 3~6년 구간 안에 있으며, 계속 흡연하는 경우와 비교해 관상동맥질환의 추가 위험이 절반으로 줄어드는 시기입니다.\n\n이 범위는 4년이라는 정확한 날짜에 생물학적 전환이 일어난다고 주장하지 않으면서도, 의학적 근거가 있는 큰 심혈관 개선 시기를 제대로 인정하게 해 줍니다.';

  @override
  String get smokingReferenceDay1825 =>
      '5년: 암 위험이 크게 줄기 시작합니다\n\n출처: CDC, 금연의 이점\n\n5년은 중요한 위험 감소 구간의 시작점입니다.\n\n5~10년의 이정표\n• 구강암, 인후암, 후두암의 추가 위험: 절반으로 감소\n• 뇌졸중 위험: 감소\n\n앞으로도 계속되는 변화\n• 약 10년: 방광암, 식도암, 신장암 위험 감소\n• 10~15년: 폐암의 추가 위험이 절반으로 감소\n• 15년: 관상동맥질환 위험이 비흡연자에 가까워짐\n• 20년: 구강암, 인후암, 후두암 위험이 비흡연자에 가까워지고 자궁경부암의 추가 위험은 약 절반으로 감소\n\n금연 5년은 큰 이정표입니다. 암과 뇌졸중 위험이 크게 낮아지는 구간에 들어섰고, 앞으로도 중요한 이점이 계속 쌓입니다.';

  @override
  String get snriReferenceDay3 =>
      'SNRI 중단: 첫 며칠\n\n출처: Harvard Health Publishing\n\n중요한 안전 안내\nSNRI는 의료진의 감독 아래 서서히 감량한 뒤 중단해야 합니다. 특히 벤라팍신(Effexor)은 반감기가 약 5시간으로 매우 짧아 약물이 몸에서 빠르게 빠져나가며 중단 증상이 갑작스럽고 심하게 나타날 수 있습니다.\n\nSNRI가 SSRI보다 중단하기 어려울 수 있는 이유\nSNRI는 기분 조절에 관여하는 두 신경전달물질인 세로토닌과 노르아드레날린에 영향을 주므로, 중단하면 두 체계가 함께 다시 적응해야 합니다. 중단 증상은 SSRI보다 SNRI에서 더 강한 경우가 많습니다.\n• 독감과 비슷한 증상(피로, 발한, 근육통)\n• 불면 및 수면 장애\n• 메스꺼움 — SSRI보다 더 두드러질 수 있음\n• 균형 이상과 어지럼\n• 감각 이상 — 벤라팍신에서는 이른바 ‘브레인 잽’이 매우 강할 수 있음\n• 과각성, 과민성, 불안\n\nSNRI 비교\n벤라팍신은 반감기가 짧아 중단이 특히 어려운 편입니다. 둘록세틴(Cymbalta)은 반감기가 약 12시간으로 더 길어 다소 수월한 편이며, 데스벤라팍신은 그 중간에 있습니다.';

  @override
  String get snriReferenceDay7 =>
      'SNRI 중단 1주: 두 신경전달물질 체계의 적응\n\n출처: NHS — 항우울제 중단 안내(일반적인 항우울제 지침이며, 아래의 노르아드레날린 관련 설명은 NHS 페이지의 SNRI 특이 정보가 아니라 일반적인 SNRI 약리학을 반영합니다)\n\n두 체계의 동시 적응\n많은 항우울제와 달리 SNRI는 세로토닌과 노르아드레날린 모두에 영향을 줍니다. 1주가 되면 두 체계가 동시에 적응 중입니다.\n\n노르아드레날린 체계의 영향\n노르아드레날린은 투쟁-도피 반응, 혈압 조절, 에너지 수준에 관여합니다. 다시 적응하는 동안:\n• 혈압이 변동할 수 있습니다\n• 불안이 두근거림이나 발한처럼 더 신체적으로 느껴질 수 있습니다\n• 에너지 수준이 들쭉날쭉할 수 있습니다\n\n세로토닌 체계의 영향\n동시에 세로토닌 체계도 적응하며 항우울제 중단에서 흔한 금단 증상을 만들 수 있습니다. 두 체계가 함께 적응하므로 첫 주가 특히 힘들 수 있습니다.\n\n신체적으로는 혈압이 더 안정되고 일어설 때 어지럼이 줄어드는 모습이 흔합니다. 감정적으로는 30일 시점보다 변동이 크지만, 더 이상 급격히 무너지는 상태는 아닙니다.';

  @override
  String get snriReferenceDay14 =>
      'SNRI 중단 2주: 신체 증상 완화\n\n출처: Davies & Read (2019), Addictive Behaviors\n\n2주 시점\n적절히 감량한 대부분의 사람은 2주가 되면 급성 신체 증상이 상당 부분 가라앉습니다.\n• 브레인 잽이 크게 줄거나 사라짐\n• 메스꺼움과 독감 유사 증상 완화\n• 어지럼과 균형 문제 호전\n• 노르아드레날린이 재조정되면서 혈압과 심박수 안정\n\n남을 수 있는 증상\n• 정서적 민감성과 기분 변동\n• 불안 — 노르아드레날린 체계의 영향을 특히 받음\n• 피로 — 노르아드레날린은 각성과 에너지에 관여함\n\n연구 맥락\nDavies & Read (2019)의 Addictive Behaviors 체계적 문헌고찰은 SNRI 중단 효과가 항우울제 계열 중 비교적 심한 편이며, 벤라팍신에서 의미 있는 금단 증상이 특히 자주 보고된다고 확인했습니다.';

  @override
  String get snriReferenceDay30 =>
      'SNRI 중단 1개월: 두 체계의 안정화\n\n출처: Davies & Read (2019), Addictive Behaviors — 항우울제 금단의 발생률, 중증도, 기간에 대한 체계적 문헌고찰\n\n안정화 단계\n1개월은 세로토닌과 노르아드레날린의 적응에서 중요한 시점입니다. 이 문헌고찰은 적지 않은 사람이 몇 주 넘게 금단 증상을 겪지만, 대부분은 이때 급성이고 가장 심한 신체 중단 증상 구간을 지나 있다고 보고합니다.\n\n1개월 무렵 흔히 좋아지는 점\n• 브레인 잽, 메스꺼움, 어지럼 같은 신체 중단 증상이 대부분 완화됨\n• 혈압이 원래 수준으로 돌아가는 방향으로 안정됨\n• 수면의 질이 좋아지고 REM 수면 패턴이 다시 자리 잡음\n• 노르아드레날린 조절이 정상화되면서 에너지 수준이 안정되기 시작함\n\n감정 둔화의 완화\n이 시기에 흔히 보고되는 변화 중 하나는 감정 둔화가 풀리는 것입니다. SNRI를 복용할 때 감정 범위가 ‘평평해졌다’고 느낀 사람도 약물이 빠지고 뇌가 적응하면서 감정의 폭과 민감성이 대체로 돌아옵니다.';

  @override
  String get snriReferenceDay90 =>
      'SNRI 중단 3개월: 일반적인 금단 기간을 지남\n\n출처: Fava 등(2018), \"Withdrawal Symptoms after Serotonin-Noradrenaline Reuptake Inhibitor Discontinuation: Systematic Review\", Psychotherapy and Psychosomatics\n\nSNRI 금단의 일반적인 경과\n61개 보고서 — 이중 22개는 이중맹검 무작위 대조시험 — 에서 연구된 모든 SNRI 유형에서 금단 증상이 보고되었습니다. 증상은 보통 중단 후 며칠 안에 시작해 점진적으로 감량한 경우에도 몇 주간 지속되었습니다. 보고 전반에서 벤라팍신은 금단 증상 빈도가 더 높았습니다.\n\n90일째가 중요한 이유\n90일은 이 일반적인 수 주 경과를 훨씬 넘어선 시점입니다. 3개월에 도달했다는 것은 보통의 SNRI 금단 기간이 뒤에 있다는 뜻입니다.\n\n더 오래 지속되는 경우도 있습니다\n검토에서는 늦게 시작되거나 더 오래 지속되는 증상도 확인됐습니다. 3개월에도 중요한 증상이 계속되면 처방한 의료진과 상의하세요.';

  @override
  String get snriReferenceDay180 =>
      'SNRI 후 6개월: 뇌 및 신경 회복\n\n6개월 데이터의 회복 신호\n의학적으로 감독된 테이퍼를 완료한 후 6개월이 지나면 심각한 초기 SNRI 중단 기간이 훨씬 뒤쳐집니다. 기분, 수면, 성기능 및 명확한 사고는 회복하는 데 몇 달이 걸렸습니다.\n• 세로토닌 경로: 실질적으로 회복됨\n• 노르아드레날린 경로: 정상화되었으며 스트레스 반응 시스템도 안정되었습니다.\n• 수면 아키텍처: 완전히 복원될 것으로 예상됨\n• 성기능: 대부분의 사람들에게 대부분 회복됨(성기능 장애는 일반적인 SNRI 부작용이지만 일부의 경우 지속될 수 있으므로 처방자와 논의할 가치가 있음)\n\n스트레스에 대한 회복력\n6개월이 된 많은 사람들은 각성 및 스트레스 반응에서 노르아드레날린 시스템의 역할(SNRI가 강력하게 조절함)이 자연 수준으로 돌아오면서 일상적인 스트레스 요인에 대한 회복력이 눈에 띄게 향상되었다고 보고합니다.';

  @override
  String get snriReferenceDay365 =>
      'SNRI 중단 1년: 회복 달성\n\n1년: 두 체계의 장기 적응\nSNRI 감량을 마친 뒤 1년 동안 세로토닌과 노르아드레날린 체계는 적응하고 안정될 충분한 시간을 가졌습니다.\n\n1년 시점에서 실제 근거가 말하는 것\nTherapeutics Letter 검토는 기록된 금단 증상이 ‘중단 후 며칠 안에 나타나는 경우가 보통’이며 대부분 약 2주 안에 가라앉는다고 설명합니다. SNRI 중단 후 정확히 1년 된 사람을 추적한 대조 연구는 없습니다. 더 넓은 임상적 맥락에서 이 시점에 뒷받침되는 내용은 다음과 같습니다.\n• 적절히 감량하고 심리적 지원을 받은 사람의 대다수는 안정적인 상태를 유지함\n• SNRI 사용과 관련된 감정 둔화와 성기능 장애는 대부분의 사람에서 해소됨\n• 집중력을 포함한 명료한 사고는 약물 없이 자연스러운 뇌 기능으로 유지됨\n\n이 이정표의 의미\n특히 벤라팍신 같은 SNRI를 성공적으로 중단하는 것은 큰 성취입니다. 중단 과정의 강도와 의료진 감독 아래 이를 관리하는 데 필요한 노력은 상당한 회복력을 보여 줍니다.';

  @override
  String get socialMediaReferenceDay1 =>
      '소셜 미디어에서 물러나기: 첫째 날\n\n출처: Lambert 외, PubMed의 \"소셜 미디어에서 1주 휴식을 취하면 웰빙, 우울증 및 불안이 향상됩니다: 무작위 대조 시험\", 사이버 심리학, 행동 및 소셜 네트워킹(2022)\n\n증거가 보여주는 것\n이 강력하게 통제된 연구에서 사람들은 무작위로 Facebook, Instagram, Twitter, TikTok을 일주일 동안 사용하지 않거나 평소처럼 계속 사용하도록 배정되었습니다. 휴식 그룹은 웰빙이 크게 향상되고 우울증과 불안이 감소한 것으로 나타났습니다. 이는 뒤로 물러나는 것이 도움이 된다는 실제적이고 통제된 증거입니다.\n\n증거가 보여주는 것\n강박적인 소셜 미디어 사용은 기분 저하 및 불안 증가와 밀접한 관련이 있으며, 무작위 시험에서는 의도적으로 소셜 미디어 사용을 줄이는 것이 일주일 이내에 우울증과 불안을 줄이는 동시에 웰빙을 향상시킬 수 있음을 보여줍니다.\n\n첫째 날: 기대할 사항\n• 안절부절 못함과 확인하고 싶은 충동\n• \'유령\' 알림 — 발생하지 않은 윙윙거리는 느낌\n• 덜 지속적인 자극에 적응하면서 지루함\n이는 습관과 관련된 정상적인 감각이며 일시적입니다. 패턴을 인식하는 것이 패턴을 바꾸는 첫 번째 단계입니다.';

  @override
  String get socialMediaReferenceDay3 =>
      '소셜 미디어 없는 3일: 불안과 기분\n\n출처: Lambert 외, PubMed의 \"소셜 미디어에서 1주 휴식을 취하면 웰빙, 우울증 및 불안이 향상됩니다: 무작위 대조 시험\", 사이버 심리학, 행동 및 소셜 네트워킹(2022)\n\n휴식이 기분에 도움이 되는 이유\n이 대조 실험에서 무작위로 일주일 동안 소셜 미디어를 사용하지 않도록 배정된 사람들은 스크롤을 계속한 사람들보다 불안감과 우울증이 더 낮고 웰빙이 더 높은 것으로 한 주를 마무리했습니다. 과도한 사용으로 인한 일상적인 고통의 대부분은 사회적 비교(다른 사람이 선별한 하이라이트 릴과 실제 생활을 비교)와 누락에 대한 낮은 수준의 두려움에서 비롯됩니다.\n\n72시간 정도 지나면 무슨 일이 일어날까요?\n휴식 시간 초반에도 습관은 여전히 시끄럽습니다.\n• 확인하고 싶은 강한 충동, 종종 일상적인 순간(깨어나기, 줄 서서 기다리기)으로 인해 유발됨\n• 약간의 과민성과 안절부절함\n• 일부 사람들에게는 비교로 인한 불안이 처음으로 완화되었습니다.\n• 잠들기 전 스크롤 습관이 풀리기 시작함\n\n비교의 함정이 풀린다\n다른 사람들의 하이라이트를 지속적으로 제공하지 않으면 소셜 미디어에 대한 불안감을 증폭시키는 비교는 연료가 부족합니다. 실험 결과에 따르면 첫 주가 끝날 때까지 이러한 초기 교대근무가 기분에 측정 가능한 개선을 가져옵니다. 따라서 3일 동안의 불편함은 성과를 거두는 변화의 어려운 부분입니다.';

  @override
  String get socialMediaReferenceDay7 =>
      '소셜 미디어 없는 일주일: 측정된 성과\n\n출처: Lambert 외, PubMed의 \"소셜 미디어에서 1주 휴식을 취하면 웰빙, 우울증 및 불안이 향상됩니다: 무작위 대조 시험\", 사이버 심리학, 행동 및 소셜 네트워킹(2022)\n\n정확히 일주일 — 효과가 있었습니다\n이것은 연구가 가장 직접적으로 말하는 이정표입니다. 연구의 중재는 1주일의 휴식이었습니다. 소셜 미디어를 계속 사용하는 사람들과 비교했을 때, 휴식 그룹은 단 7일 만에 웰빙이 훨씬 더 높았고 우울증과 불안이 현저히 감소한 것으로 나타났습니다. 일주일을 채운 것은 통제 연구에서 실제 이점이 관찰된 시점에 도달한 것입니다.\n\n사람들이 흔히 주목하는 것\n측정된 기분 향상과 함께 사람들은 종종 다음과 같이 보고합니다.\n• 더 많은 시간 확보 - 많은 사람들이 자신이 얼마나 많은 시간을 소비했는지에 놀랐습니다.\n• 지속적으로 주의를 전환하는 습관이 느슨해지기 때문에 집중이 더 쉬워집니다.\n• 잠자리에 들기 전 스크롤이 없어 저녁에는 더 차분하고 잠이 더 편해집니다.\n이러한 이득은 임상시험에서 측정된 웰빙의 광범위한 개선에 적합합니다.\n\n계속해서\n일주일은 증거로 뒷받침되는 진정한 이정표입니다. 기분, 시간 및 주의 집중 혜택은 더 건강한 패턴이 오래 유지될수록 심화되는 경향이 있습니다.';

  @override
  String get socialMediaReferenceDay14 =>
      '소셜 미디어 없이 2주: 2주 이익\n\n출처: Coyne & Woodruff, PubMed Central의 \"휴식: 청소년 사이에서 2주간의 소셜 미디어 디지털 해독에 참여하는 효과...\" 행동 과학(2023)\n\n이 연구에 대하여\n젊은 성인들은 2주 동안 소셜 미디어 사용을 하루 30분 정도로 제한했으며, 사용량은 휴대폰을 통해 객관적으로 추적되었습니다(약 78% 감소). 참가자들은 소셜 미디어 사용을 약 78% 줄였으며, 이 이정표를 통해 2주 동안 사용이 급격히 줄어들면 어떤 일이 발생하는지 직접적으로 실제 테스트할 수 있습니다.\n\n개선된 점\n2주 동안 참가자들은 다음과 같은 개선을 보였습니다.\n• 수면 - 지속 시간과 질 모두\n• 삶의 만족도\n• 스트레스\n• 인지된 웰빙\n• 스마트폰 및 소셜 미디어 중독 척도 점수\n측정된 이득은 구체적이었습니다: 더 길고 더 나은 수면, 더 낮은 스트레스, 더 높은 삶의 만족도 및 인지된 건강, 더 낮은 스마트폰/소셜 미디어 중독 점수.\n\n뒤로 미끄러지는 것을 조심하세요\n연구자들은 또한 이후에 사용이 이전 수준으로 되돌아가는 것을 발견했습니다. 2주는 실질적인 이득이지만 단지 일시적인 휴식이 아닌 의도적인 계획이 왜 이점을 유지하는지를 강조합니다.';

  @override
  String get socialMediaReferenceDay30 =>
      '소셜 미디어가 없는 한 달: 진정한 연결이 깊어집니다\n\n출처: Coyne & Woodruff, PubMed Central의 \"휴식: 청소년 사이에서 2주간의 소셜 미디어 디지털 해독에 참여하는 효과...\" 행동 과학(2023)\n\n뒤로 물러나면 연결이 향상될 수 있습니다\n역설적으로 들리겠지만, 이 연구에서는 소셜 미디어를 바로 중단하는 것이 삶의 만족도 향상 및 스트레스 감소와 함께 지지적 관계 개선과 관련이 있었습니다. 피드에 쏟은 시간과 관심은 실제로 당신의 삶에 있는 사람들에게 제공되었습니다.\n\n한 달이 가져오는 경향\n30일이 지나면 자동으로 확인하려는 충동이 훨씬 약해지면서 많은 사람들이 다음을 발견합니다.\n• 대화에 더 적극적이고 방해가 적습니다.\n• 실제 활동과 취미에 더 많은 관심\n• 좋아요, 댓글, 팔로어 수에 덜 의존하는 자아 이미지\n\n변화의 신호\n한 달이 지나면 연구 개입 기간의 두 배에 해당하는 더 건강한 패턴이 유지됩니다. 2주에 측정된 수면, 스트레스, 삶의 만족도, 웰빙과 관계의 변화가 새로운 일상에 자리 잡을 시간을 더 얻었습니다.\n\n시간을 중요하게 여기세요\n단순히 한 화면을 다른 화면으로 바꾸는 것이 아니라 진정한 유대감과 성취감을 구축하는 활동으로 여유 시간을 채우는 것을 목표로 하세요.';

  @override
  String get socialMediaReferenceDay60 =>
      '소셜 미디어가 없는 두 달: 증거가 뒷받침하는 것\n\n출처: Ramadhan et al., \"정신 건강에 대한 디지털 소셜 미디어 해독의 영향: 체계적인 검토 및 메타 분석\", Narra J(2024), PubMed Central\n\n가장 신뢰할 수 있는 전체 그림\n연구자들은 7개의 대조 시험을 포함하여 10개 연구의 결과를 결합했습니다. 가장 분명한 결과는 사람들이 소셜 미디어에서 물러난 후 우울증 증상이 의미 있게 감소했다는 것입니다.\n\n가장 강력한 결과\n결합된 연구에서는 우울증 증상이 확실히 감소한 것으로 나타났습니다. 2개월이 지나면 정신 건강에 도움이 되는 것과 동일한 수준의 낮은 디지털 노출을 유지하게 됩니다.\n\n두 달의 모습\n일일 비교가 적고 피드 기반 강화가 적기 때문에 자아 이미지는 좋아요, 댓글 또는 팔로어 수에 의존할 이유가 훨씬 적으며, 가장 강력한 수집된 증거는 우울증 증상이 낮다는 것을 나타냅니다.\n\n실용적인 결론\n증거는 의도적이고 지속적인 변화를 보상합니다. 2개월 시점을 활용하여 과거로 돌아가기보다는 의도적인 한계를 유지하고 오프라인에서 의미와 관계를 키우는 데 시간을 쓰세요.';

  @override
  String get socialMediaReferenceDay90 =>
      '소셜 미디어 없는 3개월: 뉴 노멀\n\n출처: Coyne & Woodruff, PubMed Central의 \"휴식: 청소년 사이에서 2주간의 소셜 미디어 디지털 해독에 참여하는 효과...\" 행동 과학(2023)\n\n수면이 돋보입니다\n이 연구의 가장 명확한 결과 중 하나는 참가자들이 소셜 미디어를 바로 중단했을 때 수면 시간과 질 모두가 향상되었다는 것입니다. 3개월 동안 건강한 패턴을 유지하면 잠에 들기 위해 잠을 자던 심야 스크롤이 휴식과 경쟁을 멈춘 지 오래되었으며, 더 나은 수면은 기분, 집중력, 에너지를 높이는 경향이 있습니다.\n\n그 밖에 개선된 점\n같은 연구에서는 스트레스, 삶의 만족도, 인지된 건강 및 지지적인 관계가 향상되는 것으로 나타났습니다. 3개월이 지나면 이는 더 이상 새로운 것이 아닙니다. 새로운 표준에 적응할 시간을 가졌습니다.\n\n작동 방식에 대한 단서\n중재 연구에서 소셜 미디어를 끊으면 수면 시간과 수면의 질이 모두 크게 향상되었습니다. 3개월 동안 그 패턴을 유지하면 심야 스크롤 감소가 지속되는 수면 습관으로 바뀌게 됩니다.\n\n존재와 관계\n모든 조용한 순간을 전화로 채우려는 반사 작용이 훨씬 약해지면서 대화, 식사, 다운타임 등 현존하는 것이 더 자연스럽게 이루어지며, 3개월 동안 가꿔 온 관계가 더 단단하게 느껴질 수 있습니다.';

  @override
  String get socialMediaReferenceDay180 =>
      '소셜 미디어를 크게 줄인 6개월: 연구가 측정한 것\n\n출처: Ramadhan et al., \"정신 건강에 대한 디지털 소셜 미디어 해독의 영향: 체계적인 검토 및 메타 분석\", Narra J(2024), PubMed Central\n\n메타분석이 추가하는 것\n7개의 대조 시험을 포함한 10개의 연구를 결합한 연구자들은 사람들이 소셜 미디어를 줄이거나 일시 중지한 후 우울증 증상이 확실히 감소하는 것을 발견했습니다.\n\n실제로 발견된 것\n• 우울증: 통계적으로 유의미한 감소(가장 명확하고 일관된 이점)\n• 삶의 만족도: 유의미한 영향 없음\n• 스트레스: 유의미한 영향 없음\n• 전반적인 정신 건강: 유의미한 영향 없음\n가장 강력한 통합 결과는 분명합니다. 디지털 디톡스는 우울증 증상을 크게 감소시킵니다.\n\n여전히 광범위한 이점을 느낄 수 있는 이유\n6개월 동안 피드 노출을 줄이면 더 짧은 개입에서 볼 수 있는 실질적인 이점이 더 커집니다. 즉, 더 많은 시간을 사용할 수 있고 강박적인 확인이 줄어들며 우울증 증상과 관련된 디지털 노출이 지속적으로 감소합니다.\n\n피드 제어 유지\n가장 큰 이득은 무겁고, 수동적이며, 강박적인 사용을 중단함으로써 얻을 수 있습니다. 6개월이 되면 피드가 관심을 제어하는 ​​것이 아니라 소셜 미디어에 대한 의도적인 제어가 새로운 기본 설정이 됩니다.';

  @override
  String get socialMediaReferenceDay365 =>
      '소셜 미디어가 없는 1년: 재협상된 관계\n\n출처: Ramadhan et al., \"정신 건강에 대한 디지털 소셜 미디어 해독의 영향: 체계적인 검토 및 메타 분석\", Narra J(2024), PubMed Central\n\n지속적인 변화의 1년\n가장 강력한 결합 연구에 따르면 소셜 미디어에서 물러나면 우울증 증상이 감소하는 것으로 나타났습니다. 1년이라는 기간은 짧은 휴식이 아니라 노출이 적은 패턴이 일상이 되었음을 의미합니다.\n\n한 해의 성과\n1년은 실제 관계, 취미, 기술, 성찰 및 창의성을 위한 수백 시간의 시간을 제공합니다. 자동 확인은 1년 동안 약화되었으며 오프라인 루틴은 1년 동안 강화되었습니다.\n\n지속적인 혜택\n가장 명확하게 측정된 정신 건강상의 이득은 우울 증상의 감소입니다. 더 많은 시간, 더 적은 중단, 덜 강박적인 확인 등 실질적인 이점은 피드를 계속 제어하면서 매일 복합적으로 나타납니다.\n\n다음은 무엇입니까\n1년간의 고의적인 변화로 인해 관계가 재설정되었습니다. 제한된 의도적 사용으로 돌아가든 완전히 사용하지 않든 강박 고리가 깨졌습니다. 이것이 바로 지속적인 승리입니다.';

  @override
  String get ssriReferenceDay3 =>
      'SSRI 중단: 첫 며칠\n\n출처: Harvard Health Publishing\n\n중요한 안전 안내\nSSRI는 의료진의 감독 아래 서서히 감량한 뒤 중단해야 합니다. 특히 장기간 복용한 뒤 갑자기 끊으면 중단 증상이 훨씬 심해질 수 있습니다.\n\nSSRI 중단 증후군이란?\nSSRI를 중단하거나 용량을 크게 줄일 때 생길 수 있는 잘 알려진 의학적 현상입니다. 임상에서는 흔한 증상을 FINISH라는 약어로 정리합니다:\n• 독감 같은 증상(피로, 발한, 근육통)\n• 불면과 수면 장애\n• 메스꺼움\n• 균형 장애와 어지럼\n• 감각 이상 — 특히 전기충격 같은 ‘브레인 잽’\n• 과각성, 과민성, 불안\n\n반감기가 중요한 이유\n플루옥세틴(Prozac)은 반감기가 4~6일로 매우 길어 체내 농도가 자연스럽게 천천히 줄고 중단 증상도 대체로 더 완만합니다. 파록세틴(Paxil)은 흔히 쓰이는 SSRI 중 반감기가 가장 짧아 중단 증상이 더 강한 편입니다. 설트랄린, 시탈로프람, 에스시탈로프람은 그 중간에 있습니다.';

  @override
  String get ssriReferenceDay7 =>
      'SSRI 중단 1주: 급성기\n\n출처: NHS — Stopping or coming off antidepressants\n\n급성 중단 단계\nNHS는 대부분의 항우울제 중단 증상이 중단 후 5일 이내에 시작되고, 대다수의 경우 최대 6주까지 이어질 수 있다고 설명합니다. 1주 무렵에는 급성 신체 증상이 두드러질 수 있으며, 서서히 감량한 사람에서는 이후 점차 줄어드는 경향이 있습니다.\n\n1주 무렵 흔한 변화\n• 메스꺼움, 어지럼, 독감 같은 신체 증상이 강하지만 서서히 완화되기 시작할 수 있습니다\n• 생생한 꿈이나 불면 같은 수면 장애가 흔합니다\n• 감정이 빠르게 변하는 정서적 불안정이 흔합니다\n• 브레인 잽이 남아 있을 수 있지만 빈도는 보통 점차 줄어듭니다\n\n감량의 역할\nNHS는 중단 증상을 줄이기 위해 천천히 감량할 것을 강하게 권합니다. 장기 복용자는 수개월이 걸릴 수도 있습니다. Royal College of Psychiatrists도 장기간 SSRI를 복용한 사람에게 매우 점진적인 용량 감량을 권하며, 필요하면 액상 제형을 사용할 수 있다고 설명합니다.';

  @override
  String get ssriReferenceDay14 =>
      'SSRI 중단 2주: 신체 증상 완화\n\n출처: Davies & Read (2019), Addictive Behaviors — “A systematic review into the incidence, severity and duration of antidepressant withdrawal effects”\n\n연구 결과\n이 체계적 문헌고찰은 항우울제를 중단한 사람의 약 56%가 금단 효과를 경험했고, 그중 46%가 이를 심한 수준이라고 보고했다고 정리했습니다. 적절히 감량한 많은 사람에서는 2주 무렵 급성기가 상당히 가라앉습니다:\n• 브레인 잽이 크게 줄거나 사라짐\n• 메스꺼움과 독감 같은 증상이 가라앉음\n• 어지럼과 균형 문제가 호전됨\n• 수면이 정상화되기 시작함\n\n중단 증상과 재발 구분하기\n중단 후 며칠 안에 나타나고 FINISH 양상과 맞는 증상은 중단 증후군일 가능성이 높습니다. 2~4주 뒤 나타나 원래 치료하던 질환과 비슷한 증상은 재발일 가능성이 더 큽니다. 처방 의료진과 함께 이 차이를 관찰하는 것이 중요합니다.';

  @override
  String get ssriReferenceDay30 =>
      'SSRI 중단 1개월: 안정화\n\n출처: Haddad PM (2001), Drug Safety — “Antidepressant Discontinuation Syndromes”\n\n안정화 단계\n이 리뷰는 중단 증상이 항우울제를 끊거나 줄인 뒤 수일 안에 빠르게 시작하는 경우가 많고, 대부분은 가볍고 짧게 지속되어 특별한 치료 없이 사라진다고 설명합니다. 1개월은 급성기에서 안정화 단계로 넘어가는 시점이며, 점진적 감량을 마친 많은 사람에서는 급성 중단 증상이 대체로 가라앉아 있습니다.\n\n1개월 무렵의 감정 변화\n감정 변화는 사람마다 다르므로 관찰이 중요합니다:\n• 뇌가 적응하는 동안 처음에는 감정이 더 ‘평평하게’ 느껴질 수 있으며 보통 호전됩니다\n• 오랫동안 느끼지 못했던 감정의 생생함을 다시 느끼는 사람도 있습니다\n• 불안 수준은 개인과 기저 질환에 따라 크게 다릅니다\n\n비약물 지원의 가치\nCBT 같은 대화 치료와 기타 근거 기반 심리치료는 SSRI가 사용되는 여러 질환에 효과적입니다. 1개월 시점은 이런 지원이 잘 마련되어 있는지 확인하기 좋은 때입니다.';

  @override
  String get ssriReferenceDay90 =>
      '3개월: 금단 경과가 전환점을 돈다\n\n출처: Duffy 등, \"Antidepressant medication to prevent depression relapse in primary care: the ANTLER RCT,\" Health Technology Assessment (2021)\n\n12주에 측정\nANTLER는 항우울제를 최소 9개월 복용했고 중단을 고려할 만큼 안정된 1차 진료 환자 478명을 무작위 배정했습니다. 참가자는 시탈로프람, 설트랄린, 플루옥세틴 또는 미르타자핀을 복용하고 있었습니다. 중단군과 유지군의 금단 증상 차이는 12주에 가장 컸고 이후 추적에서는 더 작아졌습니다.\n\nSSRI 이정표로 맞는 이유\n연구 약물 4개 중 시탈로프람, 설트랄린, 플루옥세틴 3개가 SSRI입니다. 연구의 일반인용 요약은 중단 후 추가 금단 증상이 주로 첫 3~4개월에 집중됐다고 설명합니다.\n\n3개월을 힘차게\n90일은 바로 그 측정된 전환점에 해당합니다. 이후 금단 증상 차이가 줄어들기 때문에 3개월은 구체적인 회복 이정표입니다. 우울감이나 불안이 강하게 다시 나타나면 처방 의료진에게 일찍 연락하세요.';

  @override
  String get ssriReferenceDay180 =>
      '항우울제 중단 후 6개월: 65%가 안정된 상태 유지\n\n출처: Volkmann 외(2026), European Archives of Psychiatry and Clinical Neuroscience\n\n6개월의 구체적인 결과\n이 연구는 주요우울장애가 관해된 상태에서 항우울제를 중단한 사람들을 추적했습니다. 6개월 결과 자료가 있는 83명 중 54명(65%)이 안정된 상태를 유지했고 29명은 재발했습니다.\n\n이 이정표가 중요한 이유\n실제로 측정된 이 6개월 결과는 장기적 안정을 보여 주는 구체적인 이정표입니다. 연구는 금단 증상과 재발도 별도로 평가해 둘을 구분하는 데 도움을 줬습니다.\n\n우울 증상이 강하게 다시 나타난다면 처방 의료진에게 일찍 연락하세요.';

  @override
  String get ssriReferenceDay365 =>
      '장기 항우울제 중단 1년: ANTLER가 측정한 것\n\n출처: Duffy 등(2021), Health Technology Assessment — ANTLER 시험\n\n시험이 실제로 보여 준 결과\nANTLER는 장기간 항우울제를 복용해 왔고 중단을 고려할 만큼 안정된 영국 일차진료 성인 478명을 무작위 배정했습니다. 52주까지 중단군의 56%가 재발했고 유지 치료군은 39%였습니다. 시간에 따른 재발 위험비는 약 두 배(HR 2.06)였지만, 실제 관찰된 1년 재발 비율은 56% 대 39%였지 두 배가 아니었습니다.\n\n전체 그림\n중단이 막다른 길이었던 것은 아닙니다. 44%는 52주 동안 재발하지 않았습니다. 다만 평균 결과는 유지 치료에 유리했습니다. 중단군은 금단 증상이 더 많았고 12개월 동안 질보정수명(QALY)이 더 적었습니다. 중단군으로 배정된 사람의 39%는 원래 항우울제를 다시 시작했습니다.\n\n당신의 1년 이정표\n약 없이 1년을 보내고 잘 지내고 있다면 큰 성취입니다. ANTLER는 모두가 약을 계속해야 한다거나 모두가 중단해야 한다고 말하지 않습니다. 재발 위험과 치료 결정에 개인별 추적이 중요한 이유를 보여 줍니다. 필요할 때 약을 다시 시작하는 것은 임상적 선택이지 실패가 아닙니다.';

  @override
  String get steroidsReferenceDay1 =>
      '동화작용 스테로이드 중단: 첫날\n\n출처: \"남성의 단백동화 남성호르몬 스테로이드 사용 및 중단과 관련된 일반적인 증상\", 모범 사례 및 연구 임상 내분비학 및 대사(2022)\n\n급성기\n이 검토에서는 AAS 철회가 두 단계로 진행되는 것으로 설명합니다. 첫 번째 증상은 호르몬 수치보다는 교감신경계 활성화에 의해 발생하며 중단 후 1~2일 이내에 나타나며 다음을 포함할 수 있습니다.\n• 두통\n• 떨림\n• 심계항진\n• 메스꺼움\n\n증상이 나타나는 이유\n동화작용 스테로이드는 또한 신체 자체의 테스토스테론 생성을 억제합니다. 즉, 뇌는 스테로이드를 감지하고 일반적으로 이를 구동하는 호르몬 신호를 차단합니다. 이러한 억제는 중지 후에도 지속되어 이후 이정표에 설명된 두 번째로 오래 지속되는 금단 단계를 설정합니다.\n\n안전 참고사항\n스테로이드를 중단하는 동안 우울증이 나타나 심각해질 수 있습니다. 자해에 대한 생각이 들면 의료 조치를 취하고 긴급한 도움을 구하십시오. 임상의는 종종 회복을 안내합니다. 일부는 이를 지원하기 위해 약물을 사용합니다.';

  @override
  String get steroidsReferenceDay14 =>
      '아나볼릭 스테로이드 중단 2주\n\n출처: \"Common symptoms associated with usage and cessation of anabolic androgenic steroids in men,\" Best Practice & Research Clinical Endocrinology & Metabolism (2022)\n\n지속되는 단계가 두드러집니다\n2주가 지나면 첫 며칠의 짧은 교감신경계 증상은 대개 가라앉고, 지속적인 테스토스테론 결핍이 주도하는 두 번째 단계가 더 뚜렷해집니다.\n• 피로와 기분 저하\n• 근육통\n• 성욕 감소\n• 불면과 강한 사용 욕구\n\n아직 호르몬이 낮은 시기\n자연적인 테스토스테론 생산이 회복되는 데는 2주보다 훨씬 오래 걸립니다. 따라서 이 단계는 예상 가능한 과정이며, 그 자체로 문제가 생겼다는 뜻은 아닙니다.\n\n알려진 함정\n일부 남성은 이 불편한 기간을 피하려고 다시 스테로이드를 사용합니다. 그러면 회복이 끝나는 것이 아니라 다시 처음부터 시작됩니다. 의사나 상담사의 도움은 스테로이드를 더 사용하는 대신 이 시기를 버티는 데 도움이 될 수 있습니다.';

  @override
  String get steroidsReferenceDay30 =>
      '아나볼릭 스테로이드 중단 1개월\n\n출처: PubMed의 \"Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review\"\n\n회복이 시작됩니다\n중단 후 고환에 테스토스테론을 만들라고 지시하는 호르몬 신호가 다시 활성화되기 시작합니다. 연구에서는 회복의 상당 부분이 3~6개월에 걸쳐 진행되는 것으로 보고하므로, 한 달 시점에는 이미 과정이 시작된 상태입니다.\n\n예상할 수 있는 점\n호르몬이 다시 오르는 동안 기분 저하, 성욕 저하, 낮은 에너지가 계속될 수 있습니다. 회복 속도는 나이와 이전 사용의 강도 및 기간에 따라 달라집니다.';

  @override
  String get steroidsReferenceDay90 =>
      '동화작용 스테로이드 3개월 사용 중단\n\n출처: PubMed의 \"단백 동화 스테로이드로 인한 성선 기능 저하증의 신체적, 심리적, 생화학적 회복: 범위 지정 검토\"\n\n혈액 검사를 받기 좋은 시간\n3개월이 지나면 호르몬 시스템이 의미 있는 회복을 보일 시간을 갖게 됩니다. 이는 담당 GP에게 테스토스테론과 이를 조절하는 호르몬을 확인하도록 요청하는 데 유용한 정보입니다.\n\n무엇을 기대해야 할까요?\n3개월이 된 많은 남성의 경우 수준이 올라가지만 완전히 정상화되지는 않습니다. 테스토스테론이 완전히 따라잡기 전에 기분과 성욕이 개선되는 경우가 많습니다. 고환 크기와 정자 생산은 더 천천히 회복되며 다음 해에도 계속 개선될 수 있습니다. 발생한 유방 조직 성장(여성형 유방)은 특별한 치료 없이는 회복될 가능성이 없습니다.';

  @override
  String get steroidsReferenceDay180 =>
      '동화작용 스테로이드 6개월 사용 중단\n\n출처: PubMed의 \"단백 동화 스테로이드로 인한 성선 기능 저하증의 신체적, 심리적, 생화학적 회복: 범위 지정 검토\"\n\n증거가 가리키는 곳\n리뷰에서는 고환에서 테스토스테론을 생성하도록 지시하는 호르몬인 LH와 FSH가 일반적으로 약 3~6개월 내에 회복된다고 보고합니다. 6개월이 되면 테스토스테론 자체도 회복 경로를 따라 잘 회복됩니다.\n\n아직 거기에 없다면\n6개월 후에도 테스토스테론 수치가 낮은 증상이 계속 나타나면 내분비 전문의는 무슨 일이 일어나고 있는지 확인하고 기다리기보다는 치료 방법에 대해 논의할 수 있습니다.';

  @override
  String get steroidsReferenceDay365 =>
      '아나볼릭 스테로이드 중단 1년\n\n출처: \"Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review,\" Endocrine Connections (2023)\n\n스테로이드 없이 1년\nAAS 중단 후 회복은 사람마다 크게 다릅니다. 문헌고찰은 테스토스테론이 수개월에 걸쳐 거의 회복되고, 성선자극호르몬은 약 3~6개월에 걸쳐 회복되며, 고환 크기와 정자 생성은 수개월에서 수년에 걸쳐 회복될 수 있다고 보고합니다. 심리적 회복은 더 예측하기 어렵습니다.\n\n1년도 충분히 중요한 이정표입니다\n스테로이드 없이 1년을 보낸 것은 큰 성취이지만, 모든 사람의 호르몬이 반드시 정상화되어야 하는 보편적인 마감 시점은 아닙니다. 낮은 테스토스테론 증상이 남아 있다면 전문의 평가로 현재 회복 상태를 확인할 수 있습니다.';

  @override
  String get steroidsReferenceDay730 =>
      '아나볼릭 스테로이드 중단 2년\n\n출처: \"Physical, psychological and biochemical recovery from anabolic steroid-induced hypogonadism: a scoping review,\" Endocrine Connections (2023)\n\n꾸준히 이어 온 2년\n스테로이드 없이 2년은 재노출 없이 보낸 긴 시간입니다. 회복은 나이와 이전 안드로겐 사용 정도 같은 요인에 따라 달라지며, 모든 사람의 호르몬이 2년에 반드시 정상이어야 한다는 보편적인 기준은 없습니다.\n\n긴 회복 과정\n문헌고찰은 테스토스테론 회복이 수개월에 걸쳐 진행되고 성선자극호르몬은 약 3~6개월에 회복되는 반면, 고환 크기와 정자 생성은 수개월에서 수년에 걸쳐 계속 회복될 수 있다고 보고합니다. 낮은 테스토스테론 증상이 지속되면 또 다른 스테로이드 사이클이 아니라 전문의 평가가 필요합니다.';

  @override
  String get tcaReferenceDay3 =>
      'TCA 중단: 초기 며칠과 콜린성 반동\n\n출처: Dilsaver, Feinberg & Greden(1983), American Journal of Psychiatry — \'항콜린제로 치료한 항우울제 중단 증상\'(환자 3명의 사례 보고)\n\nTCA 중단 증상이 다를 수 있는 이유\n많은 삼환계 항우울제(TCA)는 세로토닌 및 노르아드레날린에 대한 작용 외에도 항콜린성 작용을 합니다. 발표된 세 사례에서 갑작스러운 중단이나 빠른 감량 후 나타난 증상이 항콜린제 치료에 반응했으며, 연구진은 중추 콜린성 활성 증가가 관련될 수 있다고 보았습니다.\n\n보고된 TCA 중단 증상\n• 메스꺼움, 구토, 설사, 복통 및 식욕 부진\n• 불면증 등 수면 장애\n• 불안, 초조 및 과민함\n• 두통 및 기타 신체 증상\n\n증상이 나타나는 시기는 다양합니다\n특히 갑자기 중단하거나 빠르게 감량한 뒤 초기에 증상이 나타날 수 있습니다. 이 세 명의 사례 보고는 콜린성 반동이 가능한 기전임을 뒷받침하지만, 모든 사람에게 적용되는 일정한 날짜별 경과나 TCA별 반동의 심각도를 확립하기 위한 연구는 아닙니다.';

  @override
  String get tcaReferenceDay7 =>
      'TCA 중단 후 일주일: 첫 고비를 지나서\n\n일주일의 의미\n영국 NHS 안내에 따르면 항우울제 중단 증상은 대개 며칠 안에 시작해 수주간 지속됩니다. 일부 사람에게는 심한 증상이 나타나거나 몇 달 이상 이어질 수 있습니다.\n\n여전히 나타날 수 있는 증상\n• 두통과 근육통\n• 메스꺼움과 발한\n• 심장이 빠르게 뛰거나 두근거리거나 불규칙하게 뛰는 느낌\n• 어지럼증이나 균형감 저하\n• 수면 문제, 이상한 꿈과 피로\n• 안절부절못함, 과민함, 불안, 기분 저하 또는 사고의 어려움\n\n7일간의 진전\nTCA를 중단한 지 일주일이 된 것은 축하할 만한 진전입니다. NHS는 중단 증상이 며칠에서 수주, 때로는 더 오래 지속될 수 있다고 안내합니다. 따라서 심박수, 소화, 수면 등 자율신경 기능 관련 증상은 서로 다른 속도로 가라앉을 수 있습니다.';

  @override
  String get tcaReferenceDay14 =>
      'TCA 중단 2주 후: 급성 금단이 보통 가라앉기 시작합니다\n\n일반적인 급성 구간\n항우울제 중단 증후군에 대한 임상 리뷰에서는 독감 유사 증상, 불면, 메스꺼움, 균형 장애, 감각 이상, 과각성 같은 전형적인 증상이 보통 1~2주 지속된다고 보고합니다.\n\n14일째의 의미\n2주가 되면 많은 사람이 전형적인 급성 중단 구간의 끝에 도달합니다. 첫 번째 파도의 증상은 이 시점에서 상당히 완화되는 경우가 많습니다.\n\nTCA 없이 14일\n14일은 분명한 회복 지점입니다. 급성 금단의 파도가 보통 꺾이기 시작하고, 가장 거친 초기 구간을 지나고 있습니다.';

  @override
  String get tcaReferenceDay30 =>
      'TCA 중단 후 한 달: 급성 중단 증상은 보통 가라앉음\n\n일반적인 급성 시기\nWarner 등은 항우울제 중단 증상이 대개 경미하고 1~2주 지속된다고 보고합니다. TCA도 명확히 포함되며, 중단 후 균형 및 움직임 문제는 특히 특징적으로 나타날 수 있습니다.\n\n30일의 의미\n한 달이면 대부분 일반적인 급성 시기를 충분히 지났습니다. 독감 같은 증상, 메스꺼움, 균형 이상, 불면, 감각 이상, 과각성은 대개 크게 줄거나 사라집니다.\n\n30일의 힘\nTCA 없이 한 달은 분명한 회복의 이정표입니다. 전형적인 급성 중단 시기는 보통 이미 지나갔습니다.';

  @override
  String get tcaReferenceDay90 =>
      'TCA 중단 후 3개월: 급성 중단 시기는 한참 지났습니다\n\n일반적인 급성 시기\nWarner 등은 항우울제 중단 증상이 대개 경미하고 1~2주 지속된다고 보고합니다. TCA도 명확히 포함되며, 중단 후 균형 및 움직임 문제는 특히 특징적으로 나타날 수 있습니다.\n\n90일의 의미\n90일은 일반적인 급성 시기의 상한에서 10주 이상 지난 시점입니다. 독감 같은 증상, 메스꺼움, 균형 이상, 불면, 감각 이상, 과각성과 같은 전형적인 초기 증상이 있었다면, 대개 오래전에 크게 줄거나 사라졌습니다.\n\n90일의 힘\nTCA 없이 3개월은 분명한 회복의 이정표입니다. 급성 중단 시기는 보통 한참 전에 지나갔습니다. 중요한 우울 증상이 다시 나타나면 일찍 담당 의료진에게 연락하세요.';

  @override
  String get tcaReferenceDay180 =>
      '항우울제 중단 6개월: 대부분 재발 없이 유지\n\n6개월 재발 체크포인트\n2024년 메타분석은 주요우울장애 치료를 받은 사람들의 항우울제 중단 무작위시험 35개를 통합했습니다. 중단 후 6개월의 통합 재발률은 34.81%로, 그 시점까지 약 65%가 재발하지 않은 것과 같습니다.\n\n실제 장기 결과\n같은 분석에서 12개월 재발률은 45.12%였습니다. 6개월은 의미 있는 안정의 이정표입니다. 통합된 시험의 참가자 대부분은 그때까지 재발하지 않았습니다.\n\n진전을 지키기\n우울 증상이 다시 나타나기 시작하면 의료진에게 일찍 연락하세요. 6개월은 지켜낼 가치가 있는 큰 안정 구간입니다.';

  @override
  String get tcaReferenceDay365 =>
      '항우울제 중단 1년: 대부분 재발 없이 유지\n\n12개월 재발 체크포인트\n2024년 메타분석은 주요우울장애 치료를 받은 사람들의 항우울제 중단 무작위 시험 35개를 통합했습니다. 중단 후 12개월의 통합 재발률은 45.12%로, 1년 시점까지 약 55%가 재발 없이 지냈다는 뜻입니다.\n\n1년 내내 이어진 안정\n같은 분석에서 6개월 재발률은 34.81%였습니다. 12개월에도 통합된 시험 참가자의 대부분은 여전히 재발하지 않았습니다. 1년 내내 재발 없이 지낸 것은 장기 안정성의 큰 이정표입니다.\n\n진전을 지키세요\n우울 증상이 다시 나타나기 시작하면 담당 의료진에게 일찍 연락하세요. 1년을 채운 것은 지켜낼 가치가 있는 큰 성취입니다.';

