  @override
  String vapingStreakTitle(int days) {
    return '베이프 없이: $days일째';
  }

  @override
  String get vapingDay1Description =>
      '베이프 없이 첫날입니다. 사용하던 베이프에 니코틴이 들어 있었다면 갈망, 짜증, 안절부절못함, 기분 저하, 수면 문제, 집중력 저하는 니코틴 금단일 수 있습니다. 이 첫 고비를 넘기며 이미 베이핑의 고리를 끊고 있습니다.';

  @override
  String get vapingDay3Description =>
      '베이프 없이 3일. 과거 흡연자이면서 매일 전자담배를 사용하던 사람들을 대상으로 한 임상 연구에서 평균 금단 증상 점수는 1일째 또는 2일째 정점을 찍은 뒤 다음 4일간 감소했습니다. 이제 그 연구에서 관찰된 초기 정점 구간을 지났습니다. 갈망이 다시 와도 운전대는 당신이 잡고 있습니다.';

  @override
  String get vapingDay7Description =>
      '베이프 에어로졸을 들이마시지 않은 7일. 에어로졸에 포함될 수 있는 니코틴, 미세 입자, 중금속, 휘발성 유기화합물과 기타 유해 물질에 새로 노출되지 않은 일주일입니다. 깔끔한 연속 기록 — 계속 이어가세요.';

  @override
  String vapingLongStreakDescription(int days) {
    return '$days일 동안 베이프 에어로졸을 한 모금도 더 들이마시지 않았습니다. 에어로졸에 포함될 수 있는 유해 물질에 새로 노출되지 않은 $days일입니다. 사용하던 베이프에 니코틴이 들어 있었다면 그 의존을 다시 강화하지 않은 시간도 $days일입니다. 엄청난 연속 기록 — 계속 가세요.';
  }

  @override
  String get vapingMilestone730Title => '2년: 베이프 없는 힘';

  @override
  String get vapingMilestone730Description =>
      '베이프 없이 2년입니다. CDC는 니코틴 의존이 끊기를 어렵게 만들 수 있고 베이핑의 장기 건강 영향은 아직 연구 중이라고 설명합니다. 확실히 축하할 수 있는 성과는 연속 기록 자체입니다. 730일 동안 베이프로 돌아가지 않았습니다.';

  @override
  String get vapingMilestone1095Title => '3년: 쌓아 온 추진력';

  @override
  String get vapingMilestone1095Description =>
      '베이프 없이 3년입니다. 쉽지 않은 변화를 1,095일 동안 이어 왔습니다. CDC는 3년을 생물학적 회복 기준으로 정하지 않습니다. 근거가 말해 줄 수 있는 것을 축하하세요. 베이핑에서 계속 벗어나 있는 시간입니다.';

  @override
  String get vapingMilestone1460Title => '4년: 더 단단한 기반';

  @override
  String get vapingMilestone1460Description =>
      '베이프 없이 4년입니다. 베이핑 습관을 다시 강화하지 않은 1,460일입니다. 과학은 모두에게 적용되는 하나의 장기 회복 시간표를 제시하지 않지만, 이 꾸준한 변화는 실제이며 충분히 축하할 만합니다.';

  @override
  String get vapingMilestone1825Title => '5년: 큰 이정표';

  @override
  String get vapingMilestone1825Description =>
      '베이프 없이 5년입니다. 5년 동안 베이핑으로 돌아가지 않은 것은 큰 장기 성과입니다. CDC 근거는 5년을 의학적 회복 기준으로 정하지 않습니다. 이정표는 당신이 쌓고 지킨 변화 자체입니다.';

  @override
  String get vapingLongTermReference =>
      '베이핑, 끊기, 장기 근거\n\n출처: CDC — Vaping and Quitting; CDC — Health Effects of Vaping\n\nCDC는 베이핑으로 니코틴 의존이 생길 수 있고, 끊을 때 니코틴 금단 증상이 나타날 수 있으며, 베이핑을 끊도록 돕는 최선의 방법은 아직 연구 중이라고 설명합니다. 전자담배의 장기 건강 영향도 계속 연구되고 있습니다.\n\n이 자료들은 베이핑을 끊은 뒤 2년, 3년, 4년, 5년을 생물학적 회복 기준으로 정의하지 않습니다. 따라서 Quitter는 이 날짜들을 의학적 회복 기준이 아니라 베이프 없이 이어 온 진전을 기념하는 날로 다룹니다.';

  @override
  String get vapingWithdrawalReference =>
      '전자담배 중단과 금단 증상\n\n출처: Hughes et al., Nicotine & Tobacco Research (2020)\n\n과거 흡연자이면서 매일 전자담배를 사용하던 109명을 대상으로 한 연구에서, 생물학적으로 확인된 6일간의 중단 기간 동안 니코틴 금단 증상과 갈망이 증가했습니다. 증상은 전형적인 상승-하강 패턴을 보였고 중단 첫 이틀 동안 특히 크게 증가했습니다. 이 연구는 전자담배 중단이 실제 금단을 일으킬 수 있고 초기 며칠이 가장 거센 구간일 수 있음을 보여줍니다.';

  @override
  String get vapingHealthReference =>
      '베이핑이 노출시키는 것\n\n출처: CDC — Health Effects of Vaping\n\nCDC에 따르면 대부분의 전자담배에는 중독성 니코틴이 들어 있습니다. 베이프 에어로졸에는 니코틴, 발암 물질, 니켈·주석·납 같은 중금속, 폐 깊숙이 들어갈 수 있는 미세 입자, 휘발성 유기화합물과 일부 유해 향료 화학물질이 포함될 수 있습니다. 니코틴 금단에는 짜증, 불안이나 초조, 기분 저하, 수면·집중 문제, 허기와 갈망이 나타날 수 있으며 이런 증상은 시간이 지나면서 줄어듭니다. 베이프 없이 지내는 날마다 이런 에어로졸에 대한 새로운 노출을 피하고, 니코틴을 사용했다면 그 의존을 다시 강화하지 않는 시간이 쌓입니다.';

  @override
  String get adderallMilestone730Title => '2년: 오래가는 변화';

  @override
  String get adderallMilestone730Description =>
      'Adderall 오남용 없이 2년을 지낸 것은 짧은 연속 기록이 아니라 지속된 변화입니다. 앞으로도 힘이 될 습관과 선택을 쌓아 왔습니다.';

  @override
  String get adderallReferenceDay730 =>
      'Adderall 오남용 없이 2년: 오래가는 진전\n\n출처: SAMHSA, Treatment of Stimulant Use Disorders\n\nSAMHSA 지침은 처방 자극제 오남용을 포함한 암페타민계 자극제를 다루며 회복을 위한 근거 기반 치료를 뒷받침합니다. 2년에 생물학적 ‘리셋’이 완료된다고 정하지는 않습니다.\n\n그래도 2년은 큰 성취입니다. 오랜 기간 변화를 유지해 왔습니다. 만들어 온 안정성을 기념하고 도움이 되는 방식을 계속 이어 가세요.';

  @override
  String get adderallMilestone1095Title => '3년: 단단한 기반';

  @override
  String get adderallMilestone1095Description =>
      '3년은 하루하루 쌓아 온 장기적인 진전입니다. 여기까지 가능하게 한 삶, 습관, 지원을 계속 지켜 나가세요.';

  @override
  String get adderallReferenceDay1095 =>
      'Adderall 오남용 없이 3년: 탄력을 얻은 회복\n\n출처: SAMHSA, Treatment of Stimulant Use Disorders\n\nSAMHSA는 처방 자극제와 관련된 문제를 포함한 자극제 사용장애에서 근거 기반 치료와 장기 회복을 지지합니다. 이 지침은 특정 뇌 변화가 3년에 끝난다고 주장하지 않습니다.\n\n3년은 평범한 날과 힘든 날을 모두 지나며 이어 온 변화입니다. 여기까지 오게 한 습관, 관계, 지원을 계속 지켜 나가세요.';

  @override
  String get adderallMilestone1460Title => '4년: 깊게 내린 뿌리';

  @override
  String get adderallMilestone1460Description =>
      '4년은 놀라운 꾸준함을 보여 줍니다. 이 이정표는 오남용에서 벗어난 상태를 이어 온 것과 그 주변에 만든 안정성을 기념합니다.';

  @override
  String get adderallReferenceDay1460 =>
      'Adderall 오남용 없이 4년: 삶에 자리 잡은 장기 변화\n\n출처: SAMHSA, Treatment of Stimulant Use Disorders\n\nSAMHSA 지침은 장기 회복을 돕는 치료와 지원에 초점을 둡니다. 4년을 의학적 결승선으로 정하지 않으므로, 이 이정표는 만들어 낸 건강 약속이 아니라 지속된 진전을 기념합니다.\n\n4년은 정말 긴 시간 동안의 꾸준함입니다. 진전을 안정적으로 지켜 주는 구조와 사람들을 계속 소중히 하세요.';

  @override
  String get adderallMilestone1825Title => '5년: 큰 승리';

  @override
  String get adderallMilestone1825Description =>
      '5년은 충분히 축하할 만합니다. 1,825일 동안 다른 방향을 유지했고, 변화가 오래갈 수 있다는 사실을 여러 해의 경험으로 쌓았습니다.';

  @override
  String get adderallReferenceDay1825 =>
      'Adderall 오남용 없이 5년: 5년의 진전\n\n출처: SAMHSA, Treatment of Stimulant Use Disorders\n\nSAMHSA는 자극제 사용장애 치료에서 장기 회복을 중요한 목표로 인정합니다. 지침은 5년에 특별한 생물학적 사건이 일어난다고 약속하지 않으며, 이 이정표의 의미에 그런 약속은 필요하지 않습니다.\n\n5년은 1,825일 동안 다른 방향을 유지해 온 시간입니다. 변화가 지속될 수 있다는 강력한 실제 경험입니다. 충분히 기념하고, 여기까지 가능하게 한 것들을 계속 이어 가세요.';

  @override
  String get alcoholMilestone730Title => '2년: 꾸준한 전진';

  @override
  String get alcoholMilestone730Description =>
      '2년간 금주는 NIAAA가 회복 연구에서 지속 기간으로 보는 1~5년 구간에 들어갑니다. 계속 지켜 갈 가치가 있는 큰 성취입니다.';

  @override
  String get alcoholReferenceDay730 =>
      '금주 2년: 꾸준한 전진\n\n출처: NIAAA, Recovery Research Definitions\n\nNIAAA는 알코올 사용장애의 관해와 과음 중단이 유지된 기간 중 1~5년을 ‘지속’ 범주로 봅니다. 금주는 음주량 기준보다 더 엄격한 변화지만, 금주만으로 모든 임상적 관해 기준을 충족했다고 볼 수는 없습니다.\n\n2년은 730일 동안 변화를 유지한 시간입니다. 그 꾸준함을 축하하고, 이를 지탱한 습관과 관계, 지원을 계속 지켜 가세요.';

  @override
  String get alcoholMilestone1095Title => '3년: 단단한 기반';

  @override
  String get alcoholMilestone1095Description =>
      '3년간 금주는 1,095일 이어진 장기적 변화입니다. NIAAA 회복 연구에서는 이 기간을 지속 구간 안에 둡니다.';

  @override
  String get alcoholReferenceDay1095 =>
      '금주 3년: 단단한 기반\n\n출처: NIAAA, Recovery Research Definitions\n\nNIAAA는 알코올 사용장애의 관해와 과음 중단이 유지되는 1~5년을 지속 기간 범주로 사용합니다. 3년에 특별한 생물학적 리셋이 일어난다고 주장하지는 않습니다.\n\n3년은 1,095일 동안 다른 패턴을 강화해 온 시간입니다. 그 꾸준함 자체에 의미가 있으며, 여기까지 오게 한 지원을 계속 지킬 가치가 있습니다.';

  @override
