      'GHB 없이 3년: 더 단단한 기반\n\n출처: SAMHSA, 회복과 회복 지원\n\nSAMHSA는 회복을 지속적이고 개인적인 변화의 과정으로 설명하며, 이 연차들에 GHB만의 생물학적 종료점을 정하지 않습니다.\n\n3년은 변화를 1,095일 유지한 기록입니다. 안정성을 쌓고 회복을 지탱하는 기반을 지켜 온 의미 있는 성취입니다.';

