      'GHB 없이 5년: 큰 이정표\n\n출처: SAMHSA, 회복과 회복 지원\n\nSAMHSA는 회복을 지속적이고 개인적인 변화의 과정으로 설명하며, 이 연차들에 GHB만의 생물학적 종료점을 정하지 않습니다.\n\n5년은 변화를 1,825일 유지한 기록입니다. 오랜 기간 선택을 반복해 온 노력에는 분명한 가치가 있습니다.';

  @override
