  @override
  String get inhalantsMilestone1825Title => '5년: 강한 토대';

  @override
  String get inhalantsMilestone1825Description =>
      '5년은 축하할 만한 오래 지속된 진전입니다. 장기 금단은 회복을 뒷받침할 수 있지만 결과는 이전 손상의 종류와 심각도에도 영향을 받습니다.';

  @override
  String get inhalantsReferenceDay1095 =>
      '흡입제를 끊은 지 3년\n\n출처: Cairney 등, 「만성 흡입제 남용 15년 후 신경인지 변화에 대한 전향적 연구」, Addiction (2013), PubMed\n\n2년을 넘어서\n납성 뇌병증이 없는 참여자에서는 금단 2년 뒤 큰 회복이 관찰됐고 같은 집단을 15년까지 추적했습니다. 3년에 특별한 생물학적 경계가 있다고 제시하지 않았습니다.\n\n3년의 진전\n3년은 지속된 금단을 뜻합니다. 장기 회복은 계속될 수 있지만 결과는 과거 노출과 손상 정도에 따라 달라지며, 납성 뇌병증은 지속적인 결손을 남길 수 있습니다.';

  @override
  String get inhalantsReferenceDay1460 =>
      '흡입제를 끊은 지 4년\n\n출처: Cairney 등, 「만성 흡입제 남용 15년 후 신경인지 변화에 대한 전향적 연구」, Addiction (2013), PubMed\n\n장기 회복\n납성 뇌병증이 없는 집단에서는 대부분의 점수가 2년에 정상화됐고 15년에 다시 평가됐습니다. 논문은 4년째에 별도의 회복 사건을 지정하지 않습니다.\n\n4년의 거리\n4년은 지속된 금단에 온전한 1년을 더하고 회복의 토대를 강화한 시간입니다. 과거에 심한 신경 손상이 있었다면 결과는 달라질 수 있습니다.';

  @override
  String get inhalantsReferenceDay1825 =>
      '흡입제를 끊은 지 5년\n\n출처: Cairney 등, 「만성 흡입제 남용 15년 후 신경인지 변화에 대한 전향적 연구」, Addiction (2013), PubMed\n\n장기 이정표\n이 연구는 납성 뇌병증이 없을 때 장기 금단으로 신경 및 인지 기능이 크게 회복될 가능성을 뒷받침합니다. 평가 시점은 2년과 15년이므로 5년을 보편적인 생물학적 종착점으로 보지 않습니다.\n\n쌓아 온 5년\n5년은 흡입제에서 벗어나 살아 온 긴 기간이자 지속된 진전입니다. 근거는 장기 회복을 지지하면서 심한 납 관련 손상은 남을 수 있음을 인정합니다.';

  @override
  String get maoiMilestone730Title => '2년: 단단한 발걸음';

  @override
  String get maoiMilestone730Description =>
      'MAOI를 중단한 뒤 2년은 변화를 꾸준히 이어 온 긴 시간입니다. 트라닐시프로민 중단 연구는 급성 중단 위험을 설명하지만 2년을 특별한 생물학적 회복 시점으로 정하지 않습니다. 이 이정표는 여기까지 이어 온 꾸준함, 지원, 일상의 습관을 기념합니다.';

  @override
  String get maoiMilestone1095Title => '3년: 이어지는 전진';

  @override
  String get maoiMilestone1095Description =>
      '3년은 선택한 방향을 한 해 더 지켜 온 시간입니다. MAOI 중단 연구는 3년을 생리학적 회복의 기준점으로 정하지 않습니다. 일상 속에서 쌓아 온 선택과 지원의 지속성이 바로 성취입니다.';

  @override
  String get maoiMilestone1460Title => '4년: 굳건한 지속';

  @override
  String get maoiMilestone1460Description =>
      '4년은 계절, 스트레스, 생활 변화 속에서도 꾸준히 이어 온 시간입니다. MAOI 문헌은 4년을 모두에게 적용되는 의학적 종착점으로 보지 않습니다. 이 이정표는 유지해 온 지속성 자체를 기립니다.';

  @override
  String get maoiMilestone1825Title => '5년: 뿌리내린 변화';

  @override
  String get maoiMilestone1825Description =>
