  @override
  String get maoiReferenceDay730 =>
      'MAOI 중단 후 2년\n\n출처: Gahr 등(2013), 트라닐시프로민 금단 및 중단 현상에 대한 체계적 문헌고찰.\n\n이 고찰은 갑작스러운 중단 뒤 심각한 증후군이 생길 수 있음을 보여 주지만 2년을 특별한 생물학적 회복 기준으로 정하지 않습니다. 따라서 이 기념일은 의학적 종착점이 아니라 지속된 변화, 지원, 습관을 의미합니다.';

  @override
  String get maoiReferenceDay1095 =>
      'MAOI 중단 후 3년\n\n출처: Gahr 등(2013), 트라닐시프로민 금단 및 중단 현상에 대한 체계적 문헌고찰.\n\n고찰은 급성 금단과 중단 현상을 설명하지만 3년을 생리학적 회복 시점으로 정의하지 않습니다. 3년은 선택한 방향을 한 해 더 유지하고 그 지속을 도운 지원을 기념하는 시간입니다.';

  @override
