  @override
  String get maoiReferenceDay1825 =>
      'MAOI 중단 후 5년\n\n출처: Gahr 등(2013), 트라닐시프로민 금단 및 중단 현상에 대한 체계적 문헌고찰.\n\n문헌은 중단 위험과 안전한 중단을 다루며 5년을 완치일이나 보편적 생물학적 종착점으로 정의하지 않습니다. 그래도 1,825일 동안 이어 온 시간, 습관, 지원은 큰 이정표입니다.';

  @override
