  @override
  String get mdmaReferenceDay730 =>
      'MDMA 없이 2년\n\n출처: Ung 등(2026), 지속적인 MDMA 금단 이후 장기 신경인지 결과에 대한 체계적 문헌고찰 및 메타분석.\n\n이 검토는 최소 6개월 금단을 다룬 연구를 포함했고 근거의 질을 낮게 평가했으며, 더 긴 금단 기간이 학습이나 기억의 더 큰 회복을 신뢰성 있게 예측하지 못했다고 보고했습니다. 2년을 보편적인 생물학적 회복 시점으로 정하지 않습니다.\n\n2년은 여전히 반복된 선택으로 쌓아 온 지속적 변화의 중요한 이정표입니다.';

  @override
