  @override
  String get mdmaReferenceDay1095 =>
      'MDMA 없이 3년\n\n출처: Ung 등(2026), 지속적인 MDMA 금단에 대한 체계적 문헌고찰 및 메타분석.\n\n현재 연구는 3년이 되면 인지 영향이 모두에게서 사라진다고 정의하지 않습니다. 검토에서는 금단 기간이 길수록 학습이나 기억 회복이 더 크다는 신뢰할 만한 관계를 찾지 못했고 근거의 질도 낮게 평가했습니다.\n\n3년은 근거 없는 생물학적 기한을 주장하지 않으면서 지속된 추진력과 꾸준함을 기념하는 이정표입니다.';

