  @override
  String get ssriReferenceDay730 =>
      'SSRI 중단 2년: 꾸준한 진전\n\n출처: Royal College of Psychiatrists — Stopping antidepressants\n\n이 지침은 항우울제를 보통 갑자기 중단하지 말고 감량 속도를 개인에 맞추라고 권합니다. 금단 증상은 사람마다 다릅니다.\n\nSSRI 중단 후 2년을 생물학적 회복 기준으로 정하지 않습니다. 730일은 2년간 이어진 진전을 기념하는 날입니다.';

