      'SSRI 중단 3년: 진전을 이어가다\n\n출처: Royal College of Psychiatrists — Stopping antidepressants\n\n지침은 금단 경과가 개인마다 다르며 감량 속도는 복용 기간과 이전 감량 때의 증상 등 여러 요인에 따라 달라진다고 설명합니다.\n\n3년은 보편적인 SSRI 회복 기한이 아닙니다. 1095일은 3년간 유지된 진전을 인정하는 이정표입니다.';

  @override
